  ($lektury$apokalipsa-sw-jana$lektury$, $lektury$motyw$lektury$, 6, $lektury$Ap 17–18$lektury$, $lektury$upadek miasta-symbolu. Babilon, ukazany jako symbol władzy i zepsucia, zostaje osądzony i upada. Ap 17–18. $lektury$, $lektury${"motyw":"upadek miasta-symbolu","przyklad":"Babilon, ukazany jako symbol władzy i zepsucia, zostaje osądzony i upada.","miejsce":"Ap 17–18"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$apokalipsa-sw-jana$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Biblia Tysiąclecia, tekst do sprawdzenia opisanych fragmentów$lektury$, $lektury${"url":"https://biblia.deon.pl/","rodzaj":"utwór","co":"Biblia Tysiąclecia, tekst do sprawdzenia opisanych fragmentów"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$apokalipsa-sw-jana$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Plik nie był sprawdzany w żadnym źródle online ani w wydaniu Biblii; powstał z ogólnej znajomości Apokalipsy św. Jana i wymaga weryfikacji (np. w Biblii Tysiąclecia).$lektury$, $lektury${"tekst":"Plik nie był sprawdzany w żadnym źródle online ani w wydaniu Biblii; powstał z ogólnej znajomości Apokalipsy św. Jana i wymaga weryfikacji (np. w Biblii Tysiąclecia)."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$apokalipsa-sw-jana$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Cytatów nie podano, bo tekst współczesnych polskich wydań Biblii jest objęty prawem autorskim.$lektury$, $lektury${"tekst":"Cytatów nie podano, bo tekst współczesnych polskich wydań Biblii jest objęty prawem autorskim."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$apokalipsa-sw-jana$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Zakres „fragmentów” Apokalipsy wymaganych na maturze nie jest ustalony w katalogu; w danych ujęto najczęściej omawiane wątki.$lektury$, $lektury${"tekst":"Zakres „fragmentów” Apokalipsy wymaganych na maturze nie jest ustalony w katalogu; w danych ujęto najczęściej omawiane wątki."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$apokalipsa-sw-jana$lektury$, $lektury$weryfikacja$lektury$, 4, $lektury$$lektury$, $lektury$Zakresy rozdziałów w wydarzeniach (np. Ap 8–11, Ap 16–19) podano w przybliżeniu.$lektury$, $lektury${"tekst":"Zakresy rozdziałów w wydarzeniach (np. Ap 8–11, Ap 16–19) podano w przybliżeniu."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
