insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$bajki-krasickiego$lektury$, $lektury$motyw$lektury$, 1, $lektury$Ptaszki w klatce$lektury$, $lektury$wolność i niewola. Stary ptak płacze w klatce, bo pamięta wolność, a młody, urodzony w klatce, uważa ją za wygodę. Ptaszki w klatce. Jam był wolny, dziś w klatce — i dlatego płaczę$lektury$, $lektury${"motyw":"wolność i niewola","przyklad":"Stary ptak płacze w klatce, bo pamięta wolność, a młody, urodzony w klatce, uważa ją za wygodę.","miejsce":"Ptaszki w klatce","cytat":"Jam był wolny, dziś w klatce — i dlatego płaczę"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$motyw$lektury$, 2, $lektury$Jagnię i wilcy$lektury$, $lektury$prawo silniejszego. Wilki nie szukają prawdziwego uzasadnienia: wystarczy, że jagnię jest „smaczne, słabe i w lesie”. Jagnię i wilcy. Zawżdy znajdzie przyczynę, kto zdobyczy pragnie.$lektury$, $lektury${"motyw":"prawo silniejszego","przyklad":"Wilki nie szukają prawdziwego uzasadnienia: wystarczy, że jagnię jest „smaczne, słabe i w lesie”.","miejsce":"Jagnię i wilcy","cytat":"Zawżdy znajdzie przyczynę, kto zdobyczy pragnie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$motyw$lektury$, 3, $lektury$Jagnię i wilcy$lektury$, $lektury$krytyka przemocy i nadużycia władzy. Bajka pokazuje, że silniejszy zawsze znajdzie pretekst, by skrzywdzić słabszego; można odczytać ją jako uwagę o niesprawiedliwych rządach. Jagnię i wilcy. $lektury$, $lektury${"motyw":"krytyka przemocy i nadużycia władzy","przyklad":"Bajka pokazuje, że silniejszy zawsze znajdzie pretekst, by skrzywdzić słabszego; można odczytać ją jako uwagę o niesprawiedliwych rządach.","miejsce":"Jagnię i wilcy"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$motyw$lektury$, 4, $lektury$Ptaszki w klatce; Jagnię i wilcy$lektury$, $lektury$alegoria zwierzęca. Obie bajki używają zwierząt jako postaci reprezentujących typy ludzkie i postawy polityczne. Ptaszki w klatce; Jagnię i wilcy. $lektury$, $lektury${"motyw":"alegoria zwierzęca","przyklad":"Obie bajki używają zwierząt jako postaci reprezentujących typy ludzkie i postawy polityczne.","miejsce":"Ptaszki w klatce; Jagnię i wilcy"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$utwor$lektury$, 1, $lektury$Bajki i przypowieści$lektury$, $lektury$Ptaszki w klatce. Czterowersowa bajka: młody czyżyk pyta płaczącego starego ptaka, czemu płacze, skoro w klatce ma lepiej niż w polu. Stary odpowiada, że młodzik urodził się w klatce, a on był wolny, dlatego płacze. Bajka o wolności i o tym, że ocena niewoli zależy od doświadczenia.$lektury$, $lektury${"tytul":"Ptaszki w klatce","miejsce":"Bajki i przypowieści","opis":"Czterowersowa bajka: młody czyżyk pyta płaczącego starego ptaka, czemu płacze, skoro w klatce ma lepiej niż w polu. Stary odpowiada, że młodzik urodził się w klatce, a on był wolny, dlatego płacze. Bajka o wolności i o tym, że ocena niewoli zależy od doświadczenia."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$utwor$lektury$, 2, $lektury$Bajki i przypowieści$lektury$, $lektury$Jagnię i wilcy. Czterowersowa bajka: dwa wilki znalazły w lesie jagnię i chcą je rozerwać; jagnię pyta, jakim prawem. Wilki odpowiadają, że jest smaczne, słabe i w lesie, i je zjadają. Morał w pierwszym wersie: „Zawżdy znajdzie przyczynę, kto zdobyczy pragnie.”$lektury$, $lektury${"tytul":"Jagnię i wilcy","miejsce":"Bajki i przypowieści","opis":"Czterowersowa bajka: dwa wilki znalazły w lesie jagnię i chcą je rozerwać; jagnię pyta, jakim prawem. Wilki odpowiadają, że jest smaczne, słabe i w lesie, i je zjadają. Morał w pierwszym wersie: „Zawżdy znajdzie przyczynę, kto zdobyczy pragnie.”"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Lista bajek w zbiorze (118 pozycji); sprawdzono, że są Ptaszki w klatce i Jagnię i wilcy.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/","rodzaj":"utwór","co":"Lista bajek w zbiorze (118 pozycji); sprawdzono, że są Ptaszki w klatce i Jagnię i wilcy."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Pełny tekst.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/ptaszki-w-klatce/","rodzaj":"utwór","co":"Pełny tekst."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/ptaszki-w-klatce/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$zrodlo$lektury$, 3, $lektury$$lektury$, $lektury$Pełny tekst.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/jagnie-i-wilcy/","rodzaj":"utwór","co":"Pełny tekst."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/jagnie-i-wilcy/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$„Kruk i lis” (przykład z katalogu) nie został znaleziony w spisie Wolnych Lektur („Bajki i przypowieści”); może być w innym zbiorze — nie opracowano go.$lektury$, $lektury${"tekst":"„Kruk i lis” (przykład z katalogu) nie został znaleziony w spisie Wolnych Lektur („Bajki i przypowieści”); może być w innym zbiorze — nie opracowano go."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$CKE odsyła do bajek Krasickiego bez zamkniętej listy; opisano dwie przykładowe.$lektury$, $lektury${"tekst":"CKE odsyła do bajek Krasickiego bez zamkniętej listy; opisano dwie przykładowe."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/$lektury$),
  ($lektury$bajki-krasickiego$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Rok wydania zbioru nie został sprawdzony.$lektury$, $lektury${"tekst":"Rok wydania zbioru nie został sprawdzony."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bajki-i-przypowiesci/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$ballady-mickiewicza$lektury$, $lektury$motyw$lektury$, 1, $lektury$Romantyczność$lektury$, $lektury$człowiek i zjawy. Karusia widzi ducha Jasieńka, a narrator mówi, że czucie i wiara silniej niż mędrca szkiełko i oko prowadzą do prawdy. Romantyczność. Czucie i wiara silniej mówi do mnie, Niż mędrca szkiełko i oko.$lektury$, $lektury${"motyw":"człowiek i zjawy","przyklad":"Karusia widzi ducha Jasieńka, a narrator mówi, że czucie i wiara silniej niż mędrca szkiełko i oko prowadzą do prawdy.","miejsce":"Romantyczność","cytat":"Czucie i wiara silniej mówi do mnie, Niż mędrca szkiełko i oko."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/ballady-i-romanse/$lektury$),
  ($lektury$ballady-mickiewicza$lektury$, $lektury$motyw$lektury$, 2, $lektury$Romantyczność$lektury$, $lektury$czucie i wiara wobec rozumu. Starzec z „szkiełkiem i okiem” uważa duchy za wymysły gawiedzi, a mówiący odpowiada, że znajomość „martwych prawd” nie pozwala zobaczyć cudu. Romantyczność. Miej serce i patrzaj w serce!$lektury$, $lektury${"motyw":"czucie i wiara wobec rozumu","przyklad":"Starzec z „szkiełkiem i okiem” uważa duchy za wymysły gawiedzi, a mówiący odpowiada, że znajomość „martwych prawd” nie pozwala zobaczyć cudu.","miejsce":"Romantyczność","cytat":"Miej serce i patrzaj w serce!"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/ballady-i-romanse/$lektury$),
  ($lektury$ballady-mickiewicza$lektury$, $lektury$motyw$lektury$, 3, $lektury$Romantyczność; Lilije$lektury$, $lektury$ludowość i wierzenia gminu. W „Romantyczności” prostota mówi pacierze, bo wierzy w obecność duszy, a w „Lilijach” historia pochodzi „z pieśni gminnej”. Romantyczność; Lilije. $lektury$, $lektury${"motyw":"ludowość i wierzenia gminu","przyklad":"W „Romantyczności” prostota mówi pacierze, bo wierzy w obecność duszy, a w „Lilijach” historia pochodzi „z pieśni gminnej”.","miejsce":"Romantyczność; Lilije"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/ballady-i-romanse/$lektury$),
  ($lektury$ballady-mickiewicza$lektury$, $lektury$motyw$lektury$, 4, $lektury$Świtezianka$lektury$, $lektury$kara za złamanie przysięgi. Strzelec łamie przysięgę wierności i traci życie przez nimfę.. Świtezianka. I biada jego złej duszy!$lektury$, $lektury${"motyw":"kara za złamanie przysięgi","przyklad":"Strzelec łamie przysięgę wierności i traci życie przez nimfę..","miejsce":"Świtezianka","cytat":"I biada jego złej duszy!"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/ballady-i-romanse/$lektury$),
  ($lektury$ballady-mickiewicza$lektury$, $lektury$motyw$lektury$, 5, $lektury$Lilije$lektury$, $lektury$zbrodnia i kara nadprzyrodzona. W „Lilijach” zbrodnia męża-zabójczyni wychodzi na jaw przez lilie wyrosłe na grobie i widmo, które pojawia się przy ślubie. Lilije. Zbrodnia to niesłychana, Pani zabija pana.$lektury$, $lektury${"motyw":"zbrodnia i kara nadprzyrodzona","przyklad":"W „Lilijach” zbrodnia męża-zabójczyni wychodzi na jaw przez lilie wyrosłe na grobie i widmo, które pojawia się przy ślubie.","miejsce":"Lilije","cytat":"Zbrodnia to niesłychana, Pani zabija pana."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/ballady-i-romanse/$lektury$),
  ($lektury$ballady-mickiewicza$lektury$, $lektury$motyw$lektury$, 6, $lektury$Romantyczność$lektury$, $lektury$nieszczęśliwa miłość. Karusia nie chce żyć bez Jasieńka i prosi go: „Weź mię, ja umrę przy tobie”. Romantyczność. $lektury$, $lektury${"motyw":"nieszczęśliwa miłość","przyklad":"Karusia nie chce żyć bez Jasieńka i prosi go: „Weź mię, ja umrę przy tobie”.","miejsce":"Romantyczność"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/ballady-i-romanse/$lektury$),
  ($lektury$ballady-mickiewicza$lektury$, $lektury$utwor$lektury$, 1, $lektury$Ballady i romanse$lektury$, $lektury$Romantyczność. Ballada o Karusi, która widzi zmarłego ukochanego Jasieńka. Tłum wierzy jej, że to duch, a „starzec” z „szkiełkiem i okiem” przekonuje, że duchów nie ma. Odpowiedź mówiącego (czucie i wiara kontra rozum) bywa czytana jako manifest romantyzmu. Motto z „Hamleta” wprowadza temat widzenia duszą.$lektury$, $lektury${"tytul":"Romantyczność","miejsce":"Ballady i romanse","opis":"Ballada o Karusi, która widzi zmarłego ukochanego Jasieńka. Tłum wierzy jej, że to duch, a „starzec” z „szkiełkiem i okiem” przekonuje, że duchów nie ma. Odpowiedź mówiącego (czucie i wiara kontra rozum) bywa czytana jako manifest romantyzmu. Motto z „Hamleta” wprowadza temat widzenia duszą."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/ballady-i-romanse/$lektury$),
  ($lektury$ballady-mickiewicza$lektury$, $lektury$utwor$lektury$, 2, $lektury$Ballady i romanse$lektury$, $lektury$Świtezianka. Ballada o młodzieńcu-strzelcu, który przysięga wierność dziewczynie spod lasu, a potem zdradza ją dla pięknej nimfy z jeziora Świteź. Zjawa wciąga go w głąb jeziora; po śmierci młodzieniec jęczy pod modrzewiem. Utwór kończy powtórzone pytanie narratora, kto to był.$lektury$, $lektury${"tytul":"Świtezianka","miejsce":"Ballady i romanse","opis":"Ballada o młodzieńcu-strzelcu, który przysięga wierność dziewczynie spod lasu, a potem zdradza ją dla pięknej nimfy z jeziora Świteź. Zjawa wciąga go w głąb jeziora; po śmierci młodzieniec jęczy pod modrzewiem. Utwór kończy powtórzone pytanie narratora, kto to był."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/ballady-i-romanse/$lektury$),
  ($lektury$ballady-mickiewicza$lektury$, $lektury$utwor$lektury$, 3, $lektury$Ballady i romanse$lektury$, $lektury$Lilije. Ballada „z pieśni gminnej” o kobiecie, która zabija męża i zasiewa lilie na jego grobie. Wychodzi powtórnie za mąż, lecz podczas wesela lilije z grobu stają się znakiem zemsty: mąż wraca jako upiór, a cerkiew zapada się pod ziemię. Na końcu rosną na tym miejscu lilie.$lektury$, $lektury${"tytul":"Lilije","miejsce":"Ballady i romanse","opis":"Ballada „z pieśni gminnej” o kobiecie, która zabija męża i zasiewa lilie na jego grobie. Wychodzi powtórnie za mąż, lecz podczas wesela lilije z grobu stają się znakiem zemsty: mąż wraca jako upiór, a cerkiew zapada się pod ziemię. Na końcu rosną na tym miejscu lilie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/ballady-i-romanse/$lektury$),
