insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$bogurodzica$lektury$, $lektury$motyw$lektury$, 1, $lektury$Bogurodzica, zwrotka I$lektury$, $lektury$Maryja jako pośredniczka. Pierwsza zwrotka zwraca się do Matki Bożej, a prośba „Zyszczy nam, spuści nam” wskazuje, że Maryja ma wyjednać u Syna łaskę dla wiernych. Bogurodzica, zwrotka I. Bogurodzica dziewica, Bogiem sławiena Maryja$lektury$, $lektury${"motyw":"Maryja jako pośredniczka","przyklad":"Pierwsza zwrotka zwraca się do Matki Bożej, a prośba „Zyszczy nam, spuści nam” wskazuje, że Maryja ma wyjednać u Syna łaskę dla wiernych.","miejsce":"Bogurodzica, zwrotka I","cytat":"Bogurodzica dziewica, Bogiem sławiena Maryja"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bogurodzica/$lektury$),
  ($lektury$bogurodzica$lektury$, $lektury$motyw$lektury$, 2, $lektury$Bogurodzica, zwrotka II$lektury$, $lektury$prośba o szczęście na ziemi i zbawienie po śmierci. Druga zwrotka prosi o dobre życie na świecie i raj po śmierci. Bogurodzica, zwrotka II. A na świecie zbożny pobyt, Po żywocie rajski przebyt.$lektury$, $lektury${"motyw":"prośba o szczęście na ziemi i zbawienie po śmierci","przyklad":"Druga zwrotka prosi o dobre życie na świecie i raj po śmierci.","miejsce":"Bogurodzica, zwrotka II","cytat":"A na świecie zbożny pobyt, Po żywocie rajski przebyt."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bogurodzica/$lektury$),
  ($lektury$bogurodzica$lektury$, $lektury$motyw$lektury$, 3, $lektury$Bogurodzica, części dalsze$lektury$, $lektury$odkupienie i męka Chrystusa. Dalsze części mówią, że Bóg nie odkupił ludzi srebrem ani złotem, tylko własną męką, i przypominają zmartwychwstanie. Bogurodzica, części dalsze. Ni śrebrem, ni złotem nas diabłu odkupił$lektury$, $lektury${"motyw":"odkupienie i męka Chrystusa","przyklad":"Dalsze części mówią, że Bóg nie odkupił ludzi srebrem ani złotem, tylko własną męką, i przypominają zmartwychwstanie.","miejsce":"Bogurodzica, części dalsze","cytat":"Ni śrebrem, ni złotem nas diabłu odkupił"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bogurodzica/$lektury$),
  ($lektury$bogurodzica$lektury$, $lektury$motyw$lektury$, 4, $lektury$Bogurodzica, części dalsze$lektury$, $lektury$zwrot do wiernego człowieka. Powtarza się apel „Wierzyż w to, człowiecze zbożny”, który zachęca słuchacza do wiary. Bogurodzica, części dalsze. Wierzyż w to, człowiecze zbożny$lektury$, $lektury${"motyw":"zwrot do wiernego człowieka","przyklad":"Powtarza się apel „Wierzyż w to, człowiecze zbożny”, który zachęca słuchacza do wiary.","miejsce":"Bogurodzica, części dalsze","cytat":"Wierzyż w to, człowiecze zbożny"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bogurodzica/$lektury$),
  ($lektury$bogurodzica$lektury$, $lektury$utwor$lektury$, 1, $lektury$całość (dwie zwrotki wstępne i dalsze części)$lektury$, $lektury$Bogurodzica. Średniowieczna pieśń religijna do Matki Boskiej, zbudowana jako prośba (deesis): Maryja ma wstawiać się u Syna za ludźmi. Zwrotki kończy refren „Kyrieleison”. Dalsze części w wydaniu mówią o odkupieniu przez Chrystusa, zmartwychwstaniu i nagrodzie w raju.$lektury$, $lektury${"tytul":"Bogurodzica","miejsce":"całość (dwie zwrotki wstępne i dalsze części)","opis":"Średniowieczna pieśń religijna do Matki Boskiej, zbudowana jako prośba (deesis): Maryja ma wstawiać się u Syna za ludźmi. Zwrotki kończy refren „Kyrieleison”. Dalsze części w wydaniu mówią o odkupieniu przez Chrystusa, zmartwychwstaniu i nagrodzie w raju."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bogurodzica/$lektury$),
  ($lektury$bogurodzica$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Tekst pieśni w zapisie z Wolnych Lektur: podział na zwrotki, refren, cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/bogurodzica/","rodzaj":"utwór","co":"Tekst pieśni w zapisie z Wolnych Lektur: podział na zwrotki, refren, cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bogurodzica/$lektury$),
  ($lektury$bogurodzica$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Autorstwo, czas powstania i najstarszy zapis nie zostały sprawdzone w źródle w tej sesji; podawane tradycyjnie, wymagają potwierdzenia (np. w opracowaniu ZPE lub informatorze CKE).$lektury$, $lektury${"tekst":"Autorstwo, czas powstania i najstarszy zapis nie zostały sprawdzone w źródle w tej sesji; podawane tradycyjnie, wymagają potwierdzenia (np. w opracowaniu ZPE lub informatorze CKE)."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bogurodzica/$lektury$),
  ($lektury$bogurodzica$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Które dokładnie zwrotki uznaje się za pierwotną „dwuzwrotkową” część utworu — do potwierdzenia w opracowaniu naukowym; opis opiera się na tekście z Wolnych Lektur.$lektury$, $lektury${"tekst":"Które dokładnie zwrotki uznaje się za pierwotną „dwuzwrotkową” część utworu — do potwierdzenia w opracowaniu naukowym; opis opiera się na tekście z Wolnych Lektur."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bogurodzica/$lektury$),
  ($lektury$bogurodzica$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Wolne Lektury podają tekst w pisowni zachowującej staropolskie formy; cytaty w danych są dosłowne z tego wydania.$lektury$, $lektury${"tekst":"Wolne Lektury podają tekst w pisowni zachowującej staropolskie formy; cytaty w danych są dosłowne z tego wydania."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/bogurodzica/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$borges-opowiadanie$lektury$, $lektury$postac$lektury$, 1, $lektury$Ogród o rozwidlających się ścieżkach, zeznanie$lektury$, $lektury$Yu Tsun. Yu Tsuna, Yu Tsunowi, Yu Tsunem. chiński szpieg działający dla Niemiec, narrator zeznania ścigany przez Maddena, potomek Ts’ui Pêna, zabija Alberta Ogród o rozwidlających się ścieżkach, zeznanie$lektury$, $lektury${"imie":"Yu Tsun","odmiany":["Yu Tsuna","Yu Tsunowi","Yu Tsunem"],"rola":"chiński szpieg działający dla Niemiec, narrator zeznania","relacje":"ścigany przez Maddena, potomek Ts’ui Pêna, zabija Alberta","miejsca":["Ogród o rozwidlających się ścieżkach, zeznanie"]}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$postac$lektury$, 2, $lektury$Ogród o rozwidlających się ścieżkach, spotkanie u Alberta$lektury$, $lektury$Stephen Albert. Stephena Alberta, Stephenowi Albertowi, Stephenem Albertem. sinolog, odczytuje zasadę budowy powieści Ts’ui Pêna przyjmuje Yu Tsuna i ginie z jego ręki Ogród o rozwidlających się ścieżkach, spotkanie u Alberta$lektury$, $lektury${"imie":"Stephen Albert","odmiany":["Stephena Alberta","Stephenowi Albertowi","Stephenem Albertem"],"rola":"sinolog, odczytuje zasadę budowy powieści Ts’ui Pêna","relacje":"przyjmuje Yu Tsuna i ginie z jego ręki","miejsca":["Ogród o rozwidlających się ścieżkach, spotkanie u Alberta"]}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$postac$lektury$, 3, $lektury$Ogród o rozwidlających się ścieżkach, pościg i finał$lektury$, $lektury$Richard Madden. Richarda Maddena, Richardowi Maddenowi, Richardem Maddenem. kapitan ścigający szpiega aresztuje Yu Tsuna po zabójstwie Alberta Ogród o rozwidlających się ścieżkach, pościg i finał$lektury$, $lektury${"imie":"Richard Madden","odmiany":["Richarda Maddena","Richardowi Maddenowi","Richardem Maddenem"],"rola":"kapitan ścigający szpiega","relacje":"aresztuje Yu Tsuna po zabójstwie Alberta","miejsca":["Ogród o rozwidlających się ścieżkach, pościg i finał"]}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$postac$lektury$, 4, $lektury$Ogród o rozwidlających się ścieżkach, rozmowa o rękopisie$lektury$, $lektury$Ts’ui Pên. Ts’ui Pêna, Ts’ui Pênowi, Ts’ui Pênem, Tsui Pen. przodek Yu Tsuna, twórca powieści uważanej za chaotyczną jego projekt bada Stephen Albert Ogród o rozwidlających się ścieżkach, rozmowa o rękopisie$lektury$, $lektury${"imie":"Ts’ui Pên","odmiany":["Ts’ui Pêna","Ts’ui Pênowi","Ts’ui Pênem","Tsui Pen"],"rola":"przodek Yu Tsuna, twórca powieści uważanej za chaotyczną","relacje":"jego projekt bada Stephen Albert","miejsca":["Ogród o rozwidlających się ścieżkach, rozmowa o rękopisie"]}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$motyw$lektury$, 1, $lektury$Ogród o rozwidlających się ścieżkach, rama$lektury$, $lektury$historia i fikcyjny dokument. Wzmianka o opisie brytyjskiej ofensywy wprowadza zeznanie Yu Tsuna, którego początkowych stron brakuje. Ogród o rozwidlających się ścieżkach, rama. $lektury$, $lektury${"motyw":"historia i fikcyjny dokument","przyklad":"Wzmianka o opisie brytyjskiej ofensywy wprowadza zeznanie Yu Tsuna, którego początkowych stron brakuje.","miejsce":"Ogród o rozwidlających się ścieżkach, rama"}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$motyw$lektury$, 2, $lektury$Ogród o rozwidlających się ścieżkach, droga do Alberta$lektury$, $lektury$labirynt przestrzenny. Yu Tsun idzie do domu Alberta według wskazówki, aby na rozdrożach skręcać w lewo, co przypomina mu sposób poruszania się po labiryncie. Ogród o rozwidlających się ścieżkach, droga do Alberta. $lektury$, $lektury${"motyw":"labirynt przestrzenny","przyklad":"Yu Tsun idzie do domu Alberta według wskazówki, aby na rozdrożach skręcać w lewo, co przypomina mu sposób poruszania się po labiryncie.","miejsce":"Ogród o rozwidlających się ścieżkach, droga do Alberta"}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$motyw$lektury$, 3, $lektury$Ogród o rozwidlających się ścieżkach, rozmowa o rękopisie$lektury$, $lektury$księga jako labirynt. Albert wyjaśnia Yu Tsunowi, że rzekomo zaginiony labirynt i niespójna powieść jego przodka są tym samym dziełem. Ogród o rozwidlających się ścieżkach, rozmowa o rękopisie. $lektury$, $lektury${"motyw":"księga jako labirynt","przyklad":"Albert wyjaśnia Yu Tsunowi, że rzekomo zaginiony labirynt i niespójna powieść jego przodka są tym samym dziełem.","miejsce":"Ogród o rozwidlających się ścieżkach, rozmowa o rękopisie"}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$motyw$lektury$, 4, $lektury$Ogród o rozwidlających się ścieżkach, rozmowa o rękopisie$lektury$, $lektury$rozwidlenia czasu. Albert wskazuje, że powieść Ts’ui Pêna dopuszcza równoczesne rozwijanie się różnych wyników jednej decyzji. Ogród o rozwidlających się ścieżkach, rozmowa o rękopisie. $lektury$, $lektury${"motyw":"rozwidlenia czasu","przyklad":"Albert wskazuje, że powieść Ts’ui Pêna dopuszcza równoczesne rozwijanie się różnych wyników jednej decyzji.","miejsce":"Ogród o rozwidlających się ścieżkach, rozmowa o rękopisie"}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$motyw$lektury$, 5, $lektury$Ogród o rozwidlających się ścieżkach, finał$lektury$, $lektury$znak i jego odczytanie. Wieść o śmierci sinologa pozwala dowództwu odczytać nazwę Albert jako cel wojskowy, gdyż miasto i uczony noszą tę samą nazwę. Ogród o rozwidlających się ścieżkach, finał. $lektury$, $lektury${"motyw":"znak i jego odczytanie","przyklad":"Wieść o śmierci sinologa pozwala dowództwu odczytać nazwę Albert jako cel wojskowy, gdyż miasto i uczony noszą tę samą nazwę.","miejsce":"Ogród o rozwidlających się ścieżkach, finał"}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$motyw$lektury$, 6, $lektury$Ogród o rozwidlających się ścieżkach, finał$lektury$, $lektury$koszt dokonanej decyzji. Madden aresztuje Yu Tsuna, a narrator kończy zeznanie świadomością, że przekazał informację kosztem życia życzliwego mu człowieka. Ogród o rozwidlających się ścieżkach, finał. $lektury$, $lektury${"motyw":"koszt dokonanej decyzji","przyklad":"Madden aresztuje Yu Tsuna, a narrator kończy zeznanie świadomością, że przekazał informację kosztem życia życzliwego mu człowieka.","miejsce":"Ogród o rozwidlających się ścieżkach, finał"}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$utwor$lektury$, 1, $lektury$całe opowiadanie, Fikcje$lektury$, $lektury$Ogród o rozwidlających się ścieżkach. Zeznanie szpiega łączy pościg i zabójstwo z rozmową o powieści, która przedstawia rozgałęziające się możliwości czasu; tytuł wybrano za katalogiem.$lektury$, $lektury${"tytul":"Ogród o rozwidlających się ścieżkach","miejsce":"całe opowiadanie, Fikcje","opis":"Zeznanie szpiega łączy pościg i zabójstwo z rozmową o powieści, która przedstawia rozgałęziające się możliwości czasu; tytuł wybrano za katalogiem."}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Informator CKE dopuszcza dowolne wybrane opowiadanie Borgesa jako lekturę w zakresie rozszerzonym.$lektury$, $lektury${"url":"https://bip.cke.gov.pl/attachments/download/10092","rodzaj":"opracowanie","co":"Informator CKE dopuszcza dowolne wybrane opowiadanie Borgesa jako lekturę w zakresie rozszerzonym."}$lektury$::jsonb, $lektury$https://bip.cke.gov.pl/attachments/download/10092$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Artykuł w Variaciones Borges omawia konstrukcję labiryntu, postacie i powieść Ts’ui Pêna.$lektury$, $lektury${"url":"https://www.borges.pitt.edu/sites/default/files/1808.pdf","rodzaj":"opracowanie","co":"Artykuł w Variaciones Borges omawia konstrukcję labiryntu, postacie i powieść Ts’ui Pêna."}$lektury$::jsonb, $lektury$https://www.borges.pitt.edu/sites/default/files/1808.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$zrodlo$lektury$, 3, $lektury$$lektury$, $lektury$Ciberletras nr 1, omówienie pościgu, spotkania Alberta z Yu Tsunem, planu przekazania nazwy miasta i rozgałęzień czasu.$lektury$, $lektury${"url":"https://lehman.edu/media/Ciberletras/documents/ISSUE-1.pdf","rodzaj":"opracowanie","co":"Ciberletras nr 1, omówienie pościgu, spotkania Alberta z Yu Tsunem, planu przekazania nazwy miasta i rozgałęzień czasu."}$lektury$::jsonb, $lektury$https://lehman.edu/media/Ciberletras/documents/ISSUE-1.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$zrodlo$lektury$, 4, $lektury$$lektury$, $lektury$Przekład dostępny w materiałach dydaktycznych MIT; sprawdzono ramę, drogę do domu Alberta i finał zeznania.$lektury$, $lektury${"url":"https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf","rodzaj":"utwór","co":"Przekład dostępny w materiałach dydaktycznych MIT; sprawdzono ramę, drogę do domu Alberta i finał zeznania."}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$),
  ($lektury$borges-opowiadanie$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Informator CKE nie wskazuje konkretnego tytułu; Ogród o rozwidlających się ścieżkach wybrano za przykładem w katalogu.$lektury$, $lektury${"tekst":"Informator CKE nie wskazuje konkretnego tytułu; Ogród o rozwidlających się ścieżkach wybrano za przykładem w katalogu."}$lektury$::jsonb, $lektury$https://web.mit.edu/uricchio/Public/television/documentary/Borges_GardenOfForkingPaths.pdf$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$boska-komedia$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$Piekło, pieśń I$lektury$, $lektury$Piekło, pieśń I. Dante, Wergiliusz. ciemny las; wzgórze. Dante błądzi w ciemnym lesie w połowie życia, napotyka trzy zwierzęta (pantera, lew, wilczyca) i spotyka Wergiliusza, który zapowiada drogę przez zaświaty.$lektury$, $lektury${"nr":1,"miejsce":"Piekło, pieśń I","kto":["Dante","Wergiliusz"],"gdzie":"ciemny las; wzgórze","opis":"Dante błądzi w ciemnym lesie w połowie życia, napotyka trzy zwierzęta (pantera, lew, wilczyca) i spotyka Wergiliusza, który zapowiada drogę przez zaświaty."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/boska-komedia/$lektury$),
  ($lektury$boska-komedia$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$Piekło, pieśń II$lektury$, $lektury$Piekło, pieśń II. Dante, Wergiliusz, Beatrycze. przed bramą piekła. Wergiliusz wyjaśnia, że posłała go Beatrycze za wstawiennictwem Łucji; Dante zbiera odwagę do podróży.$lektury$, $lektury${"nr":2,"miejsce":"Piekło, pieśń II","kto":["Dante","Wergiliusz","Beatrycze"],"gdzie":"przed bramą piekła","opis":"Wergiliusz wyjaśnia, że posłała go Beatrycze za wstawiennictwem Łucji; Dante zbiera odwagę do podróży."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/boska-komedia/$lektury$),
