insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$prolog, sc. I–III$lektury$, $lektury$prolog, sc. I–III. Wykrętowic (Strepsjades), Ksantias, Odrzykoń (Fidippides). Ateny, plac między domem Wykrętowica a uczelnią Sokratesa. O świcie Wykrętowic nie może spać, bo nęka go zbliżający się termin spłaty długów zaciągniętych przez rozrzutność żony i miłość syna do wyścigów konnych.$lektury$, $lektury${"nr":1,"miejsce":"prolog, sc. I–III","kto":["Wykrętowic (Strepsjades)","Ksantias","Odrzykoń (Fidippides)"],"gdzie":"Ateny, plac między domem Wykrętowica a uczelnią Sokratesa","opis":"O świcie Wykrętowic nie może spać, bo nęka go zbliżający się termin spłaty długów zaciągniętych przez rozrzutność żony i miłość syna do wyścigów konnych."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$prolog, sc. III–IV$lektury$, $lektury$prolog, sc. III–IV. Wykrętowic, Odrzykoń. Ateny, plac przed domem. Wykrętowic namawia syna, żeby wstąpił do szkoły Sokratesa, gdzie nauczy się mówić tak, by wygrywać wszystkie procesy; Odrzykoń odmawia.$lektury$, $lektury${"nr":2,"miejsce":"prolog, sc. III–IV","kto":["Wykrętowic","Odrzykoń"],"gdzie":"Ateny, plac przed domem","opis":"Wykrętowic namawia syna, żeby wstąpił do szkoły Sokratesa, gdzie nauczy się mówić tak, by wygrywać wszystkie procesy; Odrzykoń odmawia."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$sc. V–VI$lektury$, $lektury$sc. V–VI. Wykrętowic, Uczeń Sokratesa, Sokrates. przed domem Sokratesa (Myślarnia). Wykrętowic sam idzie do „pomysłowni” Sokratesa, rozmawia z uczniem i z Sokratesem, który unosi się w koszu i bada niebo.$lektury$, $lektury${"nr":3,"miejsce":"sc. V–VI","kto":["Wykrętowic","Uczeń Sokratesa","Sokrates"],"gdzie":"przed domem Sokratesa (Myślarnia)","opis":"Wykrętowic sam idzie do „pomysłowni” Sokratesa, rozmawia z uczniem i z Sokratesem, który unosi się w koszu i bada niebo."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$sc. VII–IX; parodos$lektury$, $lektury$sc. VII–IX; parodos. Sokrates, Wykrętowic, Chór Chmur. przed uczelnią Sokratesa. Sokrates wzywa Chmury jako nowych bogów; chór wchodzi na scenę, a Wykrętowic zostaje wprowadzony w naukę o Chmurach zamiast starych bogów.$lektury$, $lektury${"nr":4,"miejsce":"sc. VII–IX; parodos","kto":["Sokrates","Wykrętowic","Chór Chmur"],"gdzie":"przed uczelnią Sokratesa","opis":"Sokrates wzywa Chmury jako nowych bogów; chór wchodzi na scenę, a Wykrętowic zostaje wprowadzony w naukę o Chmurach zamiast starych bogów."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$sc. X–XIII$lektury$, $lektury$sc. X–XIII. Sokrates, Wykrętowic, Chór Chmur. uczelnia Sokratesa. Sokrates uczy Wykrętowica, ale stary okazuje się tępy i zbyt zacofany; Sokrates wypędza go ze szkoły.$lektury$, $lektury${"nr":5,"miejsce":"sc. X–XIII","kto":["Sokrates","Wykrętowic","Chór Chmur"],"gdzie":"uczelnia Sokratesa","opis":"Sokrates uczy Wykrętowica, ale stary okazuje się tępy i zbyt zacofany; Sokrates wypędza go ze szkoły."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$sc. XIV–XVI$lektury$, $lektury$sc. XIV–XVI. Wykrętowic, Chór Chmur. przed uczelnią. Wykrętowic w rozpaczy radzi się Chmur; Arcychmura każe mu zmusić syna do nauki u Sokratesa.$lektury$, $lektury${"nr":6,"miejsce":"sc. XIV–XVI","kto":["Wykrętowic","Chór Chmur"],"gdzie":"przed uczelnią","opis":"Wykrętowic w rozpaczy radzi się Chmur; Arcychmura każe mu zmusić syna do nauki u Sokratesa."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$sc. XVI–XVII$lektury$, $lektury$sc. XVI–XVII. Wykrętowic, Odrzykoń, Sokrates. przed uczelnią. Wykrętowic grozi synowi wypędzeniem z domu, więc ten niechętnie idzie do Sokratesa.$lektury$, $lektury${"nr":7,"miejsce":"sc. XVI–XVII","kto":["Wykrętowic","Odrzykoń","Sokrates"],"gdzie":"przed uczelnią","opis":"Wykrętowic grozi synowi wypędzeniem z domu, więc ten niechętnie idzie do Sokratesa."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$sc. XVIII–XIX (agon)$lektury$, $lektury$sc. XVIII–XIX (agon). Rzecznik Prawy, Rzecznik Nieprawy, Odrzykoń, Wykrętowic. przed uczelnią. Stary, „prawy” sposób wychowania (Rzecznik Prawy) spiera się z modnym „nieprawym” (Rzecznik Nieprawy); wygrywa Rzecznik Nieprawy, a Odrzykoń wybiera jego naukę.$lektury$, $lektury${"nr":8,"miejsce":"sc. XVIII–XIX (agon)","kto":["Rzecznik Prawy","Rzecznik Nieprawy","Odrzykoń","Wykrętowic"],"gdzie":"przed uczelnią","opis":"Stary, „prawy” sposób wychowania (Rzecznik Prawy) spiera się z modnym „nieprawym” (Rzecznik Nieprawy); wygrywa Rzecznik Nieprawy, a Odrzykoń wybiera jego naukę."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$sc. XX–XXIII (po parabazie)$lektury$, $lektury$sc. XX–XXIII (po parabazie). Chór, Sokrates, Wykrętowic, Odrzykoń. przed uczelnią. Odrzykoń uczy się sofistyki, a po jakimś czasie Sokrates oddaje go ojcu jako „wyzwolonego” ucznia.$lektury$, $lektury${"nr":9,"miejsce":"sc. XX–XXIII (po parabazie)","kto":["Chór","Sokrates","Wykrętowic","Odrzykoń"],"gdzie":"przed uczelnią","opis":"Odrzykoń uczy się sofistyki, a po jakimś czasie Sokrates oddaje go ojcu jako „wyzwolonego” ucznia."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$sc. XXIV–XXVI$lektury$, $lektury$sc. XXIV–XXVI. Wykrętowic, Sokrates, Odrzykoń, Chór. przed uczelnią. Wykrętowic wychodzi z domu z workiem mąki dla Sokratesa; Sokrates oddaje mu syna, który wraca brudny, chudy i obdarty (ojciec początkowo go nie poznaje), a Wykrętowic cieszy się, że syn nauczył się sztuki wykrętów.$lektury$, $lektury${"nr":10,"miejsce":"sc. XXIV–XXVI","kto":["Wykrętowic","Sokrates","Odrzykoń","Chór"],"gdzie":"przed uczelnią","opis":"Wykrętowic wychodzi z domu z workiem mąki dla Sokratesa; Sokrates oddaje mu syna, który wraca brudny, chudy i obdarty (ojciec początkowo go nie poznaje), a Wykrętowic cieszy się, że syn nauczył się sztuki wykrętów."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 11, $lektury$sc. XXVII–XXIX$lektury$, $lektury$sc. XXVII–XXIX. Wykrętowic, Pasjas, Amynias, Świadek. przed domem Sokratesa. Do Wykrętowica przychodzą lichwiarze Pasjas i Amynias z żądaniem spłaty; pewny sztuki syna, odprawia ich batogiem i drwinami.$lektury$, $lektury${"nr":11,"miejsce":"sc. XXVII–XXIX","kto":["Wykrętowic","Pasjas","Amynias","Świadek"],"gdzie":"przed domem Sokratesa","opis":"Do Wykrętowica przychodzą lichwiarze Pasjas i Amynias z żądaniem spłaty; pewny sztuki syna, odprawia ich batogiem i drwinami."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 12, $lektury$sc. XXX$lektury$, $lektury$sc. XXX. Wykrętowic, Odrzykoń. przed domem Wykrętowica. Po uczcie wynikła sprzeczka o Eurypidesa, a Odrzykoń bije ojca i dowodzi, że ma do tego prawo; Wykrętowic krzyczy o pomoc.$lektury$, $lektury${"nr":12,"miejsce":"sc. XXX","kto":["Wykrętowic","Odrzykoń"],"gdzie":"przed domem Wykrętowica","opis":"Po uczcie wynikła sprzeczka o Eurypidesa, a Odrzykoń bije ojca i dowodzi, że ma do tego prawo; Wykrętowic krzyczy o pomoc."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
  ($lektury$chmury$lektury$, $lektury$wydarzenie$lektury$, 13, $lektury$sc. XXXI–XXXII$lektury$, $lektury$sc. XXXI–XXXII. Wykrętowic, Odrzykoń, Chór. przed domem Wykrętowica. Odrzykoń przekonuje, że można bić nawet matkę; Wykrętowic uświadamia sobie, że jego plan zawiódł, i obwinia Sokratesa.$lektury$, $lektury${"nr":13,"miejsce":"sc. XXXI–XXXII","kto":["Wykrętowic","Odrzykoń","Chór"],"gdzie":"przed domem Wykrętowica","opis":"Odrzykoń przekonuje, że można bić nawet matkę; Wykrętowic uświadamia sobie, że jego plan zawiódł, i obwinia Sokratesa."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystofanes-chmury/$lektury$),
