insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$ks. I$lektury$, $lektury$ks. I. Junona, Eol, Enej. Morze Śródziemne. Junona prosi Eola, żeby wypuścił wiatry i rozbił flotę trojańskich rozbitków.$lektury$, $lektury${"nr":1,"miejsce":"ks. I","kto":["Junona","Eol","Enej"],"gdzie":"Morze Śródziemne","opis":"Junona prosi Eola, żeby wypuścił wiatry i rozbił flotę trojańskich rozbitków."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$ks. I$lektury$, $lektury$ks. I. Neptun, Enej, Trojanie. morze i wybrzeże Libii. Neptun ucisza burzę, a Enej dociera do brzegu z siedmioma okrętami.$lektury$, $lektury${"nr":2,"miejsce":"ks. I","kto":["Neptun","Enej","Trojanie"],"gdzie":"morze i wybrzeże Libii","opis":"Neptun ucisza burzę, a Enej dociera do brzegu z siedmioma okrętami."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$ks. I$lektury$, $lektury$ks. I. Wenus, Jowisz. siedziba bogów. Wenus skarży się na los Trojan, a Jowisz zapowiada przyszłą potęgę ich potomków.$lektury$, $lektury${"nr":3,"miejsce":"ks. I","kto":["Wenus","Jowisz"],"gdzie":"siedziba bogów","opis":"Wenus skarży się na los Trojan, a Jowisz zapowiada przyszłą potęgę ich potomków."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$ks. I$lektury$, $lektury$ks. I. Wenus, Enej, Achat. okolice Kartaginy. Wenus pod postacią łowczyni opowiada Enejowi o Dydonie i założeniu Kartaginy.$lektury$, $lektury${"nr":4,"miejsce":"ks. I","kto":["Wenus","Enej","Achat"],"gdzie":"okolice Kartaginy","opis":"Wenus pod postacią łowczyni opowiada Enejowi o Dydonie i założeniu Kartaginy."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$ks. I$lektury$, $lektury$ks. I. Enej, Dydona, Trojanie. Kartagina. Dydona przyjmuje Trojan, a Enej ujawnia się po rozmowie królowej z jego towarzyszami.$lektury$, $lektury${"nr":5,"miejsce":"ks. I","kto":["Enej","Dydona","Trojanie"],"gdzie":"Kartagina","opis":"Dydona przyjmuje Trojan, a Enej ujawnia się po rozmowie królowej z jego towarzyszami."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$ks. I$lektury$, $lektury$ks. I. Wenus, Amor, Dydona, Enej. pałac w Kartaginie. Amor przybiera postać Julusa i podczas uczty wzbudza w Dydonie miłość do Eneja.$lektury$, $lektury${"nr":6,"miejsce":"ks. I","kto":["Wenus","Amor","Dydona","Enej"],"gdzie":"pałac w Kartaginie","opis":"Amor przybiera postać Julusa i podczas uczty wzbudza w Dydonie miłość do Eneja."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$ks. II$lektury$, $lektury$ks. II. Enej, Synon, Laokon, Trojanie. Troja, opowieść Eneja. Synon przekonuje Trojan do wprowadzenia drewnianego konia do miasta, a śmierć Laokona i jego synów od węży utwierdza ich w tej decyzji.$lektury$, $lektury${"nr":7,"miejsce":"ks. II","kto":["Enej","Synon","Laokon","Trojanie"],"gdzie":"Troja, opowieść Eneja","opis":"Synon przekonuje Trojan do wprowadzenia drewnianego konia do miasta, a śmierć Laokona i jego synów od węży utwierdza ich w tej decyzji."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$ks. II$lektury$, $lektury$ks. II. Synon, Grecy, Trojanie. Troja, noc. Synon wypuszcza wojowników ukrytych w koniu, a Grecy wdzierają się do miasta.$lektury$, $lektury${"nr":8,"miejsce":"ks. II","kto":["Synon","Grecy","Trojanie"],"gdzie":"Troja, noc","opis":"Synon wypuszcza wojowników ukrytych w koniu, a Grecy wdzierają się do miasta."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$ks. II$lektury$, $lektury$ks. II. Enej, Hektor. Troja, dom Eneja. Hektor ukazuje się Enejowi we śnie i poleca mu ocalić świętości Troi.$lektury$, $lektury${"nr":9,"miejsce":"ks. II","kto":["Enej","Hektor"],"gdzie":"Troja, dom Eneja","opis":"Hektor ukazuje się Enejowi we śnie i poleca mu ocalić świętości Troi."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$ks. II$lektury$, $lektury$ks. II. Enej, Priam, Pyrrus. Troja, pałac Priama. Enej w walczącej Troi widzi, jak Pyrrus zabija króla Priama przy ołtarzu.$lektury$, $lektury${"nr":10,"miejsce":"ks. II","kto":["Enej","Priam","Pyrrus"],"gdzie":"Troja, pałac Priama","opis":"Enej w walczącej Troi widzi, jak Pyrrus zabija króla Priama przy ołtarzu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
  ($lektury$eneida$lektury$, $lektury$wydarzenie$lektury$, 11, $lektury$ks. II$lektury$, $lektury$ks. II. Enej, Anchizes, Julus, Kreuza. Troja i okolica. Enej wynosi ojca z płonącego miasta i prowadzi syna, lecz w czasie ucieczki traci Kreuzę.$lektury$, $lektury${"nr":11,"miejsce":"ks. II","kto":["Enej","Anchizes","Julus","Kreuza"],"gdzie":"Troja i okolica","opis":"Enej wynosi ojca z płonącego miasta i prowadzi syna, lecz w czasie ucieczki traci Kreuzę."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wergiliusz-eneida/$lektury$),
