insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$fortepian-szopena$lektury$, $lektury$motyw$lektury$, 1, $lektury$Fortepian Szopena, rozdz. III–IV$lektury$, $lektury$sztuka i doskonałość. Gra Chopina porównana do doskonałości „peryklejskiej”, a artysta do postaci wydobywanej z marmuru przez dłuto geniuszu. Fortepian Szopena, rozdz. III–IV. $lektury$, $lektury${"motyw":"sztuka i doskonałość","przyklad":"Gra Chopina porównana do doskonałości „peryklejskiej”, a artysta do postaci wydobywanej z marmuru przez dłuto geniuszu.","miejsce":"Fortepian Szopena, rozdz. III–IV"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/fortepian-chopina/$lektury$),
  ($lektury$fortepian-szopena$lektury$, $lektury$motyw$lektury$, 2, $lektury$Fortepian Szopena, rozdz. V; IX–X$lektury$, $lektury$Polska i jej los. W grze Chopina mówiący widzi Polskę „przemienionych kołodziejów”; później scena zniszczenia fortepianu odnosi się do niszczenia kultury narodowej. Fortepian Szopena, rozdz. V; IX–X. $lektury$, $lektury${"motyw":"Polska i jej los","przyklad":"W grze Chopina mówiący widzi Polskę „przemienionych kołodziejów”; później scena zniszczenia fortepianu odnosi się do niszczenia kultury narodowej.","miejsce":"Fortepian Szopena, rozdz. V; IX–X"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/fortepian-chopina/$lektury$),
  ($lektury$fortepian-szopena$lektury$, $lektury$motyw$lektury$, 3, $lektury$Fortepian Szopena, rozdz. IX$lektury$, $lektury$zniszczenie dzieła przez przemoc. Rozdział IX opisuje, jak żołnierze wyrzucają fortepian, który „runął” na bruk; można odczytać to jako obraz klęski polskiej kultury w czasie represji. Fortepian Szopena, rozdz. IX. Ideał — sięgnął bruku$lektury$, $lektury${"motyw":"zniszczenie dzieła przez przemoc","przyklad":"Rozdział IX opisuje, jak żołnierze wyrzucają fortepian, który „runął” na bruk; można odczytać to jako obraz klęski polskiej kultury w czasie represji.","miejsce":"Fortepian Szopena, rozdz. IX","cytat":"Ideał — sięgnął bruku"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/fortepian-chopina/$lektury$),
  ($lektury$fortepian-szopena$lektury$, $lektury$motyw$lektury$, 4, $lektury$Fortepian Szopena, rozdz. VII$lektury$, $lektury$niespełnienie i „brak”. Rozdział VII mówi, że doskonałość ma swoje przekleństwo, bo ludzkość żyje w niedostatku i woli „rozpoczynać”. Fortepian Szopena, rozdz. VII. $lektury$, $lektury${"motyw":"niespełnienie i „brak”","przyklad":"Rozdział VII mówi, że doskonałość ma swoje przekleństwo, bo ludzkość żyje w niedostatku i woli „rozpoczynać”.","miejsce":"Fortepian Szopena, rozdz. VII"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/fortepian-chopina/$lektury$),
  ($lektury$fortepian-szopena$lektury$, $lektury$motyw$lektury$, 5, $lektury$Fortepian Szopena, rozdz. I–II$lektury$, $lektury$wspomnienie i pożegnanie artysty. Początek utworu to powrót myślą do ostatnich dni Chopina: „byłem u Ciebie w te dni przedostatnie”. Fortepian Szopena, rozdz. I–II. Byłem u Ciebie w te dni przedostatnie$lektury$, $lektury${"motyw":"wspomnienie i pożegnanie artysty","przyklad":"Początek utworu to powrót myślą do ostatnich dni Chopina: „byłem u Ciebie w te dni przedostatnie”.","miejsce":"Fortepian Szopena, rozdz. I–II","cytat":"Byłem u Ciebie w te dni przedostatnie"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/fortepian-chopina/$lektury$),
  ($lektury$fortepian-szopena$lektury$, $lektury$utwor$lektury$, 1, $lektury$cały utwór (rozdziały I–X i zakończenie)$lektury$, $lektury$Fortepian Szopena. Dziesięcioczęściowy wiersz-poemat Norwida o Chopinie. Mówiący wspomina ostatnie dni muzyka, opisuje prostotę i doskonałość jego gry, widzi w niej polskość, a potem relacjonuje scenę zniszczenia fortepianu w Warszawie: żołnierze wyrzucają instrument z gmachu na bruk. Wiersz kończy się zdaniem, że ideał sięgnął bruku.$lektury$, $lektury${"tytul":"Fortepian Szopena","miejsce":"cały utwór (rozdziały I–X i zakończenie)","opis":"Dziesięcioczęściowy wiersz-poemat Norwida o Chopinie. Mówiący wspomina ostatnie dni muzyka, opisuje prostotę i doskonałość jego gry, widzi w niej polskość, a potem relacjonuje scenę zniszczenia fortepianu w Warszawie: żołnierze wyrzucają instrument z gmachu na bruk. Wiersz kończy się zdaniem, że ideał sięgnął bruku."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/fortepian-chopina/$lektury$),
  ($lektury$fortepian-szopena$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pełny tekst (Wolne Lektury, tytuł „Fortepian Chopina”): podział na rozdziały, obrazy, cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/fortepian-chopina/","rodzaj":"utwór","co":"Pełny tekst (Wolne Lektury, tytuł „Fortepian Chopina”): podział na rozdziały, obrazy, cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/fortepian-chopina/$lektury$),
  ($lektury$fortepian-szopena$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Datę powstania (1863?) i historyczne tło zniszczenia fortepianu Chopina w Warszawie (wrzesień 1863?) podano z pamięci i bez sprawdzania w źródle — do weryfikacji w opracowaniu.$lektury$, $lektury${"tekst":"Datę powstania (1863?) i historyczne tło zniszczenia fortepianu Chopina w Warszawie (wrzesień 1863?) podano z pamięci i bez sprawdzania w źródle — do weryfikacji w opracowaniu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/fortepian-chopina/$lektury$),
  ($lektury$fortepian-szopena$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wolne Lektury podają tytuł „Fortepian Chopina”, a katalog „Fortepian Szopena”; pisownia „Szopen” zgodna z podstawą programową.$lektury$, $lektury${"tekst":"Wolne Lektury podają tytuł „Fortepian Chopina”, a katalog „Fortepian Szopena”; pisownia „Szopen” zgodna z podstawą programową."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/fortepian-chopina/$lektury$),
  ($lektury$fortepian-szopena$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Interpretacje (Polska, zmaganie ideału z rzeczywistością) są odczytaniem tekstu, nie danymi z opracowania.$lektury$, $lektury${"tekst":"Interpretacje (Polska, zmaganie ideału z rzeczywistością) są odczytaniem tekstu, nie danymi z opracowania."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/fortepian-chopina/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$ks. I, rozdz. 3–4$lektury$, $lektury$ks. I, rozdz. 3–4. Gargamela, Tęgospust. kraj Tęgospusta. Gargamela, która nosi Gargantuę przez jedenaście miesięcy, podczas uczty je wielką ilość flaków.$lektury$, $lektury${"nr":1,"miejsce":"ks. I, rozdz. 3–4","kto":["Gargamela","Tęgospust"],"gdzie":"kraj Tęgospusta","opis":"Gargamela, która nosi Gargantuę przez jedenaście miesięcy, podczas uczty je wielką ilość flaków."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$ks. I, rozdz. 6$lektury$, $lektury$ks. I, rozdz. 6. Gargamela, Gargantua. kraj Tęgospusta. Gargantua przychodzi na świat przez lewe ucho matki i domaga się picia.$lektury$, $lektury${"nr":2,"miejsce":"ks. I, rozdz. 6","kto":["Gargamela","Gargantua"],"gdzie":"kraj Tęgospusta","opis":"Gargantua przychodzi na świat przez lewe ucho matki i domaga się picia."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$ks. I, rozdz. 7$lektury$, $lektury$ks. I, rozdz. 7. Gargantua, Tęgospust. kraj Tęgospusta. Tęgospust słyszy krzyk dziecka, a jego okrzyk podsuwa zebranym imię Gargantua.$lektury$, $lektury${"nr":3,"miejsce":"ks. I, rozdz. 7","kto":["Gargantua","Tęgospust"],"gdzie":"kraj Tęgospusta","opis":"Tęgospust słyszy krzyk dziecka, a jego okrzyk podsuwa zebranym imię Gargantua."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$ks. I, rozdz. 13$lektury$, $lektury$ks. I, rozdz. 13. Gargantua, Tęgospust. siedziba Tęgospusta. Gargantua opowiada ojcu o swoich próbach znalezienia najwygodniejszego sposobu podcierania się.$lektury$, $lektury${"nr":4,"miejsce":"ks. I, rozdz. 13","kto":["Gargantua","Tęgospust"],"gdzie":"siedziba Tęgospusta","opis":"Gargantua opowiada ojcu o swoich próbach znalezienia najwygodniejszego sposobu podcierania się."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$ks. I, rozdz. 14–15$lektury$, $lektury$ks. I, rozdz. 14–15. Gargantua, Tęgospust, Eudemon, Ponokrates. siedziba Tęgospusta. Po latach nauki u teologów Gargantua wypada źle w zestawieniu z młodym Eudemonem, więc ojciec oddaje go pod opiekę Ponokratesa.$lektury$, $lektury${"nr":5,"miejsce":"ks. I, rozdz. 14–15","kto":["Gargantua","Tęgospust","Eudemon","Ponokrates"],"gdzie":"siedziba Tęgospusta","opis":"Po latach nauki u teologów Gargantua wypada źle w zestawieniu z młodym Eudemonem, więc ojciec oddaje go pod opiekę Ponokratesa."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$ks. I, rozdz. 16–17$lektury$, $lektury$ks. I, rozdz. 16–17. Gargantua, Ponokrates. droga do Paryża i Paryż. Gargantua przybywa do Paryża na ogromnej klaczy, a potem zabiera z kościoła Najświętszej Panny dzwony, które chce zawiesić klaczy na szyi.$lektury$, $lektury${"nr":6,"miejsce":"ks. I, rozdz. 16–17","kto":["Gargantua","Ponokrates"],"gdzie":"droga do Paryża i Paryż","opis":"Gargantua przybywa do Paryża na ogromnej klaczy, a potem zabiera z kościoła Najświętszej Panny dzwony, które chce zawiesić klaczy na szyi."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$ks. I, rozdz. 18–20$lektury$, $lektury$ks. I, rozdz. 18–20. Janotus Berdysz, Gargantua. Paryż. Teolog Janotus Berdysz występuje z mową o zwrot dzwonów, które Gargantua polecił już oddać.$lektury$, $lektury${"nr":7,"miejsce":"ks. I, rozdz. 18–20","kto":["Janotus Berdysz","Gargantua"],"gdzie":"Paryż","opis":"Teolog Janotus Berdysz występuje z mową o zwrot dzwonów, które Gargantua polecił już oddać."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$ks. I, rozdz. 21–23$lektury$, $lektury$ks. I, rozdz. 21–23. Ponokrates, Gargantua. Paryż. Ponokrates przygląda się nawykom ucznia i wprowadza nowy porządek dnia, który łączy lekturę, obserwację, rozmowę i ćwiczenia.$lektury$, $lektury${"nr":8,"miejsce":"ks. I, rozdz. 21–23","kto":["Ponokrates","Gargantua"],"gdzie":"Paryż","opis":"Ponokrates przygląda się nawykom ucznia i wprowadza nowy porządek dnia, który łączy lekturę, obserwację, rozmowę i ćwiczenia."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$ks. I, rozdz. 24$lektury$, $lektury$ks. I, rozdz. 24. Ponokrates, Gargantua. Paryż. W dni deszczowe Gargantua i jego nauczyciel zmieniają zajęcia, by poznać między innymi pracę rzemieślników.$lektury$, $lektury${"nr":9,"miejsce":"ks. I, rozdz. 24","kto":["Ponokrates","Gargantua"],"gdzie":"Paryż","opis":"W dni deszczowe Gargantua i jego nauczyciel zmieniają zajęcia, by poznać między innymi pracę rzemieślników."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$ks. I, rozdz. 25$lektury$, $lektury$ks. I, rozdz. 25. piekarze z Lerny, pasterze Tęgospusta. pogranicze Lerny. Odmowa sprzedaży kołaczy doprowadza do bójki piekarzy z pasterzami.$lektury$, $lektury${"nr":10,"miejsce":"ks. I, rozdz. 25","kto":["piekarze z Lerny","pasterze Tęgospusta"],"gdzie":"pogranicze Lerny","opis":"Odmowa sprzedaży kołaczy doprowadza do bójki piekarzy z pasterzami."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 11, $lektury$ks. I, rozdz. 26–27$lektury$, $lektury$ks. I, rozdz. 26–27. Żółcik, brat Jan Łomignat. ziemie Tęgospusta, Selia. Wojska Żółcika najeżdżają sąsiedni kraj, a brat Jan broni klasztornej winnicy przed rabunkiem.$lektury$, $lektury${"nr":11,"miejsce":"ks. I, rozdz. 26–27","kto":["Żółcik","brat Jan Łomignat"],"gdzie":"ziemie Tęgospusta, Selia","opis":"Wojska Żółcika najeżdżają sąsiedni kraj, a brat Jan broni klasztornej winnicy przed rabunkiem."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 12, $lektury$ks. I, rozdz. 28–32$lektury$, $lektury$ks. I, rozdz. 28–32. Tęgospust, Żółcik, Ulrych Swędzimir. Skała Klermoncka i ziemie Tęgospusta. Tęgospust usiłuje zakończyć konflikt przez poselstwo i wypłacenie rekompensaty za kołacze, lecz Żółcik nie przerywa wojny.$lektury$, $lektury${"nr":12,"miejsce":"ks. I, rozdz. 28–32","kto":["Tęgospust","Żółcik","Ulrych Swędzimir"],"gdzie":"Skała Klermoncka i ziemie Tęgospusta","opis":"Tęgospust usiłuje zakończyć konflikt przez poselstwo i wypłacenie rekompensaty za kołacze, lecz Żółcik nie przerywa wojny."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 13, $lektury$ks. I, rozdz. 34–36$lektury$, $lektury$ks. I, rozdz. 34–36. Gargantua, Gymnastes, Flaczek. droga z Paryża i zamek Wedeński. Gargantua wraca z Paryża, Gymnastes pokonuje napotkany oddział, a Gargantua burzy zamek Wedeński.$lektury$, $lektury${"nr":13,"miejsce":"ks. I, rozdz. 34–36","kto":["Gargantua","Gymnastes","Flaczek"],"gdzie":"droga z Paryża i zamek Wedeński","opis":"Gargantua wraca z Paryża, Gymnastes pokonuje napotkany oddział, a Gargantua burzy zamek Wedeński."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 14, $lektury$ks. I, rozdz. 37–38$lektury$, $lektury$ks. I, rozdz. 37–38. Gargantua, pielgrzymi. siedziba Tęgospusta. Gargantua wyczesuje z włosów kule armatnie, a potem nie zauważa sześciu pielgrzymów, których zjada wraz z sałatą.$lektury$, $lektury${"nr":14,"miejsce":"ks. I, rozdz. 37–38","kto":["Gargantua","pielgrzymi"],"gdzie":"siedziba Tęgospusta","opis":"Gargantua wyczesuje z włosów kule armatnie, a potem nie zauważa sześciu pielgrzymów, których zjada wraz z sałatą."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
  ($lektury$gargantua-i-pantagruel$lektury$, $lektury$wydarzenie$lektury$, 15, $lektury$ks. I, rozdz. 43–44$lektury$, $lektury$ks. I, rozdz. 43–44. brat Jan Łomignat, Gargantua, Pukawka. okolice siedziby Tęgospusta. Brat Jan wpada w ręce podjazdu Żółcika, wydostaje się z niewoli, a podjazd zostaje rozbity.$lektury$, $lektury${"nr":15,"miejsce":"ks. I, rozdz. 43–44","kto":["brat Jan Łomignat","Gargantua","Pukawka"],"gdzie":"okolice siedziby Tęgospusta","opis":"Brat Jan wpada w ręce podjazdu Żółcika, wydostaje się z niewoli, a podjazd zostaje rozbity."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gargantua-i-pantagruel/$lektury$),
