insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$początek noweli (rama: wiatr i las)$lektury$, $lektury$początek noweli (rama: wiatr i las). wiatr, las. Polesie litewskie, Kanał Królewski. Wiatr przylatuje letnim wieczorem na Polesie i wita się z lasem; w lesie, na polanie, dostrzega usypaną mogiłę z małym krzyżykiem.$lektury$, $lektury${"nr":1,"miejsce":"początek noweli (rama: wiatr i las)","kto":["wiatr","las"],"gdzie":"Polesie litewskie, Kanał Królewski","opis":"Wiatr przylatuje letnim wieczorem na Polesie i wita się z lasem; w lesie, na polanie, dostrzega usypaną mogiłę z małym krzyżykiem."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$rama: rozmowa wiatru z drzewami$lektury$, $lektury$rama: rozmowa wiatru z drzewami. wiatr, dąb, brzoza, świerk, róża dzika, dzwonki liliowe. polana w lesie. Drzewa mówią, że to mogiła bezimiennych bohaterów, a róża od pół wieku rzuca na nią płatki, dzwonki liliowe „dzwonią pacierz żałobny”; wiatr prosi, by mu opowiedziano jej dzieje.$lektury$, $lektury${"nr":2,"miejsce":"rama: rozmowa wiatru z drzewami","kto":["wiatr","dąb","brzoza","świerk","róża dzika","dzwonki liliowe"],"gdzie":"polana w lesie","opis":"Drzewa mówią, że to mogiła bezimiennych bohaterów, a róża od pół wieku rzuca na nią płatki, dzwonki liliowe „dzwonią pacierz żałobny”; wiatr prosi, by mu opowiedziano jej dzieje."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$opowieść dębu: obóz$lektury$, $lektury$opowieść dębu: obóz. Romuald Traugutt, oddział powstańców. polana w lesie, maj 1863. W maju na polanę przychodzi kilkuset młodych powstańców w czapkach czworokątnych, rozkładają obóz i śpiewają hymn; dowodzi nimi Romuald Traugutt, który opuścił żonę i dzieci dla sprawy narodu.$lektury$, $lektury${"nr":3,"miejsce":"opowieść dębu: obóz","kto":["Romuald Traugutt","oddział powstańców"],"gdzie":"polana w lesie, maj 1863","opis":"W maju na polanę przychodzi kilkuset młodych powstańców w czapkach czworokątnych, rozkładają obóz i śpiewają hymn; dowodzi nimi Romuald Traugutt, który opuścił żonę i dzieci dla sprawy narodu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$opowieść dębu: bohater Tarłowski$lektury$, $lektury$opowieść dębu: bohater Tarłowski. mały Tarłowski (Maryś), Jagmin, Anielka. polana w lesie; pobliskie miasteczko. Dąb opowiada o „małym Tarłowskim”, młodym przyrodniku, który przybył w te strony, by uczyć ludzi, razem z młodszą siostrą Anielką; dowódcą jazdy jest silny, wysoki Jagmin.$lektury$, $lektury${"nr":4,"miejsce":"opowieść dębu: bohater Tarłowski","kto":["mały Tarłowski (Maryś)","Jagmin","Anielka"],"gdzie":"polana w lesie; pobliskie miasteczko","opis":"Dąb opowiada o „małym Tarłowskim”, młodym przyrodniku, który przybył w te strony, by uczyć ludzi, razem z młodszą siostrą Anielką; dowódcą jazdy jest silny, wysoki Jagmin."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$opowieść dębu: przyjaźń trojga$lektury$, $lektury$opowieść dębu: przyjaźń trojga. Tarłowski, Anielka, Jagmin. miasteczko i las obok. Jagmin zaprzyjaźnia się z rodzeństwem i zakochuje w Anielce; ostatecznie zawiadamia, że za dziesięć dni zbiórka w Dziatkowiczach, skąd idą za Kanał Królewski do lasów horeckich.$lektury$, $lektury${"nr":5,"miejsce":"opowieść dębu: przyjaźń trojga","kto":["Tarłowski","Anielka","Jagmin"],"gdzie":"miasteczko i las obok","opis":"Jagmin zaprzyjaźnia się z rodzeństwem i zakochuje w Anielce; ostatecznie zawiadamia, że za dziesięć dni zbiórka w Dziatkowiczach, skąd idą za Kanał Królewski do lasów horeckich."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$opowieść dębu: rozstanie$lektury$, $lektury$opowieść dębu: rozstanie. Tarłowski, Anielka, Jagmin. las pod miasteczkiem; ogródek. Anielka płacze, ale mówi bratu „Idź, Marysiu, idź!”; wieczorem prosi Jagmina, by miał opiekę nad bratem, a on przyrzeka być mu przyjacielem i bratem.$lektury$, $lektury${"nr":6,"miejsce":"opowieść dębu: rozstanie","kto":["Tarłowski","Anielka","Jagmin"],"gdzie":"las pod miasteczkiem; ogródek","opis":"Anielka płacze, ale mówi bratu „Idź, Marysiu, idź!”; wieczorem prosi Jagmina, by miał opiekę nad bratem, a on przyrzeka być mu przyjacielem i bratem."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$opowieść dębu: życie obozu$lektury$, $lektury$opowieść dębu: życie obozu. oddział, Traugutt, Tarłowski. polana w lesie. Oddział odbywa potyczki i wraca na polanę zwycięski; Traugutt dziękuje żołnierzom za karność i odwagę.$lektury$, $lektury${"nr":7,"miejsce":"opowieść dębu: życie obozu","kto":["oddział","Traugutt","Tarłowski"],"gdzie":"polana w lesie","opis":"Oddział odbywa potyczki i wraca na polanę zwycięski; Traugutt dziękuje żołnierzom za karność i odwagę."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$opowieść dębu: wyróżnienie Tarłowskiego$lektury$, $lektury$opowieść dębu: wyróżnienie Tarłowskiego. Traugutt, Tarłowski, Jagmin. polana w lesie. Po bitwie Traugutt przed szeregiem dziękuje Tarłowskiemu, który uratował mu życie, i nazywa go dzielnym rycerzem Umęczonej; Jagmin szepcze mu o Anielce.$lektury$, $lektury${"nr":8,"miejsce":"opowieść dębu: wyróżnienie Tarłowskiego","kto":["Traugutt","Tarłowski","Jagmin"],"gdzie":"polana w lesie","opis":"Po bitwie Traugutt przed szeregiem dziękuje Tarłowskiemu, który uratował mu życie, i nazywa go dzielnym rycerzem Umęczonej; Jagmin szepcze mu o Anielce."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$opowieść brzozy: Tarłowski w obozie$lektury$, $lektury$opowieść brzozy: Tarłowski w obozie. Tarłowski, towarzysze. polana w lesie. Brzoza opowiada, że Tarłowski w wolnych chwilach zbiera rośliny i owady i opowiada o nich towarzyszom; jest zamyślony, choć nie okazuje radości z wyróżnienia.$lektury$, $lektury${"nr":9,"miejsce":"opowieść brzozy: Tarłowski w obozie","kto":["Tarłowski","towarzysze"],"gdzie":"polana w lesie","opis":"Brzoza opowiada, że Tarłowski w wolnych chwilach zbiera rośliny i owady i opowiada o nich towarzyszom; jest zamyślony, choć nie okazuje radości z wyróżnienia."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$opowieść brzozy: nocna rozmowa$lektury$, $lektury$opowieść brzozy: nocna rozmowa. Tarłowski, Jagmin. polana w lesie. Nocą dwaj przyjaciele rozmawiają o przyszłości świata bez wojen; Tarłowski cytuje starożytnego poetę (Horacego) o ludzkiej wściekłości, a Jagmin mówi, że dopóki jest krzywda, walka jest powinnością.$lektury$, $lektury${"nr":10,"miejsce":"opowieść brzozy: nocna rozmowa","kto":["Tarłowski","Jagmin"],"gdzie":"polana w lesie","opis":"Nocą dwaj przyjaciele rozmawiają o przyszłości świata bez wojen; Tarłowski cytuje starożytnego poetę (Horacego) o ludzkiej wściekłości, a Jagmin mówi, że dopóki jest krzywda, walka jest powinnością."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 11, $lektury$opowieść dębu: dzień bitwy$lektury$, $lektury$opowieść dębu: dzień bitwy. Kalikst, Radowicki, Traugutt, oddział. polana w lesie. Do obozu przybywa goniec Kalikst z wieścią, że ogromne wojsko rosyjskie otacza las; Traugutt ogłasza bitwę pod hasłem „W imię Boga i ojczyzny!”.$lektury$, $lektury${"nr":11,"miejsce":"opowieść dębu: dzień bitwy","kto":["Kalikst","Radowicki","Traugutt","oddział"],"gdzie":"polana w lesie","opis":"Do obozu przybywa goniec Kalikst z wieścią, że ogromne wojsko rosyjskie otacza las; Traugutt ogłasza bitwę pod hasłem „W imię Boga i ojczyzny!”."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 12, $lektury$opowieść dębu: list od Anielki$lektury$, $lektury$opowieść dębu: list od Anielki. Kalikst, Tarłowski, Jagmin. polana w lesie. Kalikst oddaje Tarłowskiemu zwinięty karteczkowy list od siostry; oddział wychodzi z obozu na bitwę.$lektury$, $lektury${"nr":12,"miejsce":"opowieść dębu: list od Anielki","kto":["Kalikst","Tarłowski","Jagmin"],"gdzie":"polana w lesie","opis":"Kalikst oddaje Tarłowskiemu zwinięty karteczkowy list od siostry; oddział wychodzi z obozu na bitwę."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 13, $lektury$opowieść dębu: bitwa w lesie$lektury$, $lektury$opowieść dębu: bitwa w lesie. powstańcy, wojsko rosyjskie, Tarłowski. las i polana. Powstańcy z zasadzek ostrzeliwują nadciągające wojska; wielogodzinna bitwa; Tarłowski strzela z klęczek, aż kula trafia go w ramię i wynoszą go do namiotu z rannymi.$lektury$, $lektury${"nr":13,"miejsce":"opowieść dębu: bitwa w lesie","kto":["powstańcy","wojsko rosyjskie","Tarłowski"],"gdzie":"las i polana","opis":"Powstańcy z zasadzek ostrzeliwują nadciągające wojska; wielogodzinna bitwa; Tarłowski strzela z klęczek, aż kula trafia go w ramię i wynoszą go do namiotu z rannymi."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 14, $lektury$opowieść dębu: zabicie rannych$lektury$, $lektury$opowieść dębu: zabicie rannych. oddział jazdy rosyjskiej, Jagmin, Tarłowski. polana, namiot dla rannych. Rosyjska jazda dopada namiotu z rannymi; Jagmin ze swoim oddziałem rusza z pomocą, ale zastaje tylko zabitych; Tarłowski wzniesiony na ostrzach pik rzuca mu zakrwawioną chustę i woła „Jagmin! Siostrze!”, a Jagmin znika w zamieszaniu.$lektury$, $lektury${"nr":14,"miejsce":"opowieść dębu: zabicie rannych","kto":["oddział jazdy rosyjskiej","Jagmin","Tarłowski"],"gdzie":"polana, namiot dla rannych","opis":"Rosyjska jazda dopada namiotu z rannymi; Jagmin ze swoim oddziałem rusza z pomocą, ale zastaje tylko zabitych; Tarłowski wzniesiony na ostrzach pik rzuca mu zakrwawioną chustę i woła „Jagmin! Siostrze!”, a Jagmin znika w zamieszaniu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 15, $lektury$zakończenie opowieści: Anielka przy mogile$lektury$, $lektury$zakończenie opowieści: Anielka przy mogile. Anielka. polana, mogiła. Po wielu latach, jesienią, przychodzi na mogiłę Anielka, upada na zioła i stawia mały krzyżyk; potem odchodzi i nigdy nie wraca.$lektury$, $lektury${"nr":15,"miejsce":"zakończenie opowieści: Anielka przy mogile","kto":["Anielka"],"gdzie":"polana, mogiła","opis":"Po wielu latach, jesienią, przychodzi na mogiłę Anielka, upada na zioła i stawia mały krzyżyk; potem odchodzi i nigdy nie wraca."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$wydarzenie$lektury$, 16, $lektury$zakończenie (rama)$lektury$, $lektury$zakończenie (rama). wiatr. polana w lesie, cały świat. Lata mijają, a strumień czasu szemrze „Vae victis!”; wiatr wstaje nad mogiłą i woła na cały świat „Gloria victis!”.$lektury$, $lektury${"nr":16,"miejsce":"zakończenie (rama)","kto":["wiatr"],"gdzie":"polana w lesie, cały świat","opis":"Lata mijają, a strumień czasu szemrze „Vae victis!”; wiatr wstaje nad mogiłą i woła na cały świat „Gloria victis!”."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$postac$lektury$, 1, $lektury$polana w lesie$lektury$, $lektury$Romuald Traugutt. Traugutta, Trauguttowi, Trauguttem, wódz, wodza, naczelnik, naczelnika. dowódca oddziału powstańczego, który przychodzi do lasu z hufcem młodych ochotników wódz Jagmina i Tarłowskiego; Tarłowski ratuje mu życie polana w lesie$lektury$, $lektury${"imie":"Romuald Traugutt","odmiany":["Traugutta","Trauguttowi","Trauguttem","wódz","wodza","naczelnik","naczelnika"],"rola":"dowódca oddziału powstańczego, który przychodzi do lasu z hufcem młodych ochotników","relacje":"wódz Jagmina i Tarłowskiego; Tarłowski ratuje mu życie","miejsca":["polana w lesie"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$postac$lektury$, 2, $lektury$miasteczko$lektury$, $lektury$Tarłowski (Maryś). Tarłowskiego, Tarłowskiemu, Tarłowskim, Marysia, Marysiu, Marysiem, mały. młody, wątły przyrodnik-powstaniec, który ginie na pikach w namiocie dla rannych brat Anielki, przyjaciel Jagmina miasteczko; polana w lesie$lektury$, $lektury${"imie":"Tarłowski (Maryś)","odmiany":["Tarłowskiego","Tarłowskiemu","Tarłowskim","Marysia","Marysiu","Marysiem","mały"],"rola":"młody, wątły przyrodnik-powstaniec, który ginie na pikach w namiocie dla rannych","relacje":"brat Anielki, przyjaciel Jagmina","miejsca":["miasteczko","polana w lesie"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$postac$lektury$, 3, $lektury$miasteczko$lektury$, $lektury$Anielka (panna Aniela). Anielki, Anielce, Anielkę, Anielką, Aniela, Anieli, siostra. siostra Tarłowskiego, zostaje poza obozem, po latach odwiedza mogiłę brata siostra Tarłowskiego, ukochana Jagmina (według tekstu) miasteczko; mogiła na polanie$lektury$, $lektury${"imie":"Anielka (panna Aniela)","odmiany":["Anielki","Anielce","Anielkę","Anielką","Aniela","Anieli","siostra"],"rola":"siostra Tarłowskiego, zostaje poza obozem, po latach odwiedza mogiłę brata","relacje":"siostra Tarłowskiego, ukochana Jagmina (według tekstu)","miejsca":["miasteczko","mogiła na polanie"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$postac$lektury$, 4, $lektury$polana w lesie$lektury$, $lektury$Jagmin. Jagmina, Jagminowi, Jagminem, dowódca jazdy, dowódcę jazdy. dowódca jazdy w oddziale Traugutta, przyjaciel Tarłowskiego przyjaciel Tarłowskiego, adorator Anielki polana w lesie$lektury$, $lektury${"imie":"Jagmin","odmiany":["Jagmina","Jagminowi","Jagminem","dowódca jazdy","dowódcę jazdy"],"rola":"dowódca jazdy w oddziale Traugutta, przyjaciel Tarłowskiego","relacje":"przyjaciel Tarłowskiego, adorator Anielki","miejsca":["polana w lesie"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$postac$lektury$, 5, $lektury$polana w lesie$lektury$, $lektury$Kalikst (Kaliś). Kaliksta, Kalikstowi, Kaliś, Kalisia, posłaniec. goniec poczty obywatelskiej, który przynosi ostrzeżenie przed wojskiem rosyjskim kolega szkolny Radowickiego polana w lesie$lektury$, $lektury${"imie":"Kalikst (Kaliś)","odmiany":["Kaliksta","Kalikstowi","Kaliś","Kalisia","posłaniec"],"rola":"goniec poczty obywatelskiej, który przynosi ostrzeżenie przed wojskiem rosyjskim","relacje":"kolega szkolny Radowickiego","miejsca":["polana w lesie"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$postac$lektury$, 6, $lektury$polana w lesie$lektury$, $lektury$Radowicki. Radowickiego, Radowickiemu, Radowickim, adiutant. adiutant Traugutta kolega szkolny Kaliksta polana w lesie$lektury$, $lektury${"imie":"Radowicki","odmiany":["Radowickiego","Radowickiemu","Radowickim","adiutant"],"rola":"adiutant Traugutta","relacje":"kolega szkolny Kaliksta","miejsca":["polana w lesie"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$postac$lektury$, 7, $lektury$Polesie litewskie$lektury$, $lektury$wiatr prędki. wiatru, wiatrowi, wiatrem, wiatrze. narrator ramowy, który zbiera dzieje ludzi i głosi „Gloria victis” rozmówca drzew Polesie litewskie$lektury$, $lektury${"imie":"wiatr prędki","odmiany":["wiatru","wiatrowi","wiatrem","wiatrze"],"rola":"narrator ramowy, który zbiera dzieje ludzi i głosi „Gloria victis”","relacje":"rozmówca drzew","miejsca":["Polesie litewskie"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$postac$lektury$, 8, $lektury$las nad Kanałem Królewskim$lektury$, $lektury$dąb, brzoza, świerk. dębu, brzozy, świerka, dęby, drzewa. drzewa-świadkowie, opowiadają wiatrowi dzieje mogiły przyjaciele wiatru las nad Kanałem Królewskim$lektury$, $lektury${"imie":"dąb, brzoza, świerk","odmiany":["dębu","brzozy","świerka","dęby","drzewa"],"rola":"drzewa-świadkowie, opowiadają wiatrowi dzieje mogiły","relacje":"przyjaciele wiatru","miejsca":["las nad Kanałem Królewskim"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$motyw$lektury$, 1, $lektury$rama noweli: początek$lektury$, $lektury$hołd dla bezimiennych bohaterów powstania. Drzewa mówią wiatrowi, że mogiła nie ma imion, tylko mały krzyżyk, a świerk wymienia bohaterów „wieńczonych i niewieńczonych”. rama noweli: początek. są na ziemi bohaterzy wieńczeni i nie wieńczeni$lektury$, $lektury${"motyw":"hołd dla bezimiennych bohaterów powstania","przyklad":"Drzewa mówią wiatrowi, że mogiła nie ma imion, tylko mały krzyżyk, a świerk wymienia bohaterów „wieńczonych i niewieńczonych”.","miejsce":"rama noweli: początek","cytat":"są na ziemi bohaterzy wieńczeni i nie wieńczeni"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$motyw$lektury$, 2, $lektury$opowieść dębu: obóz$lektury$, $lektury$ofiara młodości i dobrowolne poświęcenie. Dąb opowiada o młodych ochotnikach, którzy „nie niewolnikami byli”, lecz dobrowolnymi ofiarnikami, i ginął w maju, w pełni wiosny. opowieść dębu: obóz. $lektury$, $lektury${"motyw":"ofiara młodości i dobrowolne poświęcenie","przyklad":"Dąb opowiada o młodych ochotnikach, którzy „nie niewolnikami byli”, lecz dobrowolnymi ofiarnikami, i ginął w maju, w pełni wiosny.","miejsce":"opowieść dębu: obóz"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$motyw$lektury$, 3, $lektury$opowieść brzozy: nocna rozmowa$lektury$, $lektury$wojna a człowieczeństwo (pacyfizm bohatera). Tarłowski, przyrodnik, w nocnej rozmowie z Jagminem marzy o świecie bez wojen i mówi o „kropli wściekłości lwiej” wlanej człowiekowi; mimo to walczy. opowieść brzozy: nocna rozmowa. Dopóki gwałt, dopóty święty przeciwko gwałtowi gniew!$lektury$, $lektury${"motyw":"wojna a człowieczeństwo (pacyfizm bohatera)","przyklad":"Tarłowski, przyrodnik, w nocnej rozmowie z Jagminem marzy o świecie bez wojen i mówi o „kropli wściekłości lwiej” wlanej człowiekowi; mimo to walczy.","miejsce":"opowieść brzozy: nocna rozmowa","cytat":"Dopóki gwałt, dopóty święty przeciwko gwałtowi gniew!"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$motyw$lektury$, 4, $lektury$opowieść brzozy; opowieść dębu: dzień bitwy$lektury$, $lektury$obowiązek walki wbrew nadziei. Hasło obozu brzmi „Z nadzieją czy przeciw nadziei!”; Jagmin mówi, że „teraz walka to powinność”. opowieść brzozy; opowieść dębu: dzień bitwy. Z nadzieją czy przeciw nadziei!$lektury$, $lektury${"motyw":"obowiązek walki wbrew nadziei","przyklad":"Hasło obozu brzmi „Z nadzieją czy przeciw nadziei!”; Jagmin mówi, że „teraz walka to powinność”.","miejsce":"opowieść brzozy; opowieść dębu: dzień bitwy","cytat":"Z nadzieją czy przeciw nadziei!"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$motyw$lektury$, 5, $lektury$opowieść dębu: rozstanie; zabicie rannych$lektury$, $lektury$przyjaźń i braterstwo broni. Jagmin przyrzeka Anielce, że będzie bratem jej bratu, a w ostatniej chwili Tarłowski rzuca mu zakrwawioną chustę „Siostrze!”. opowieść dębu: rozstanie; zabicie rannych. Jagmin! Siostrze!$lektury$, $lektury${"motyw":"przyjaźń i braterstwo broni","przyklad":"Jagmin przyrzeka Anielce, że będzie bratem jej bratu, a w ostatniej chwili Tarłowski rzuca mu zakrwawioną chustę „Siostrze!”.","miejsce":"opowieść dębu: rozstanie; zabicie rannych","cytat":"Jagmin! Siostrze!"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$motyw$lektury$, 6, $lektury$opowieść brzozy: Tarłowski w obozie$lektury$, $lektury$miłość do natury. Tarłowski w obozie zbiera zioła i owady i opowiada o nich towarzyszom, co daje im ukojenie. opowieść brzozy: Tarłowski w obozie. $lektury$, $lektury${"motyw":"miłość do natury","przyklad":"Tarłowski w obozie zbiera zioła i owady i opowiada o nich towarzyszom, co daje im ukojenie.","miejsce":"opowieść brzozy: Tarłowski w obozie"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$motyw$lektury$, 7, $lektury$opowieść dębu: zabicie rannych$lektury$, $lektury$okrucieństwo wojny wobec rannych. Rosyjska jazda wpada do namiotu z rannymi, zabija ich i lekarzy, a Tarłowskiego unosi na pikach. opowieść dębu: zabicie rannych. $lektury$, $lektury${"motyw":"okrucieństwo wojny wobec rannych","przyklad":"Rosyjska jazda wpada do namiotu z rannymi, zabija ich i lekarzy, a Tarłowskiego unosi na pikach.","miejsce":"opowieść dębu: zabicie rannych"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$motyw$lektury$, 8, $lektury$zakończenie noweli$lektury$, $lektury$pamięć i zwycięstwo moralne klęski (gloria victis). Mimo klęski wiatr wstaje nad mogiłą i obwieszcza całemu światu „Gloria victis!”, choć czas szemrze „Vae victis!”. zakończenie noweli. Gloria victis!$lektury$, $lektury${"motyw":"pamięć i zwycięstwo moralne klęski (gloria victis)","przyklad":"Mimo klęski wiatr wstaje nad mogiłą i obwieszcza całemu światu „Gloria victis!”, choć czas szemrze „Vae victis!”.","miejsce":"zakończenie noweli","cytat":"Gloria victis!"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$motyw$lektury$, 9, $lektury$opowieść dębu: list od Anielki; zakończenie opowieści$lektury$, $lektury$rola kobiet w powstaniu (poczta, żałoba). Anielka zostaje poza obozem, pisze list do brata, a po latach przychodzi na mogiłę ze skromnym krzyżykiem. opowieść dębu: list od Anielki; zakończenie opowieści. $lektury$, $lektury${"motyw":"rola kobiet w powstaniu (poczta, żałoba)","przyklad":"Anielka zostaje poza obozem, pisze list do brata, a po latach przychodzi na mogiłę ze skromnym krzyżykiem.","miejsce":"opowieść dębu: list od Anielki; zakończenie opowieści"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$motyw$lektury$, 10, $lektury$opowieść dębu: obóz$lektury$, $lektury$porównanie powstańców do bohaterów antyku. Narrator porównuje Traugutta do Leonidasa pod Termopilami: obaj idą na pewną śmierć. opowieść dębu: obóz. $lektury$, $lektury${"motyw":"porównanie powstańców do bohaterów antyku","przyklad":"Narrator porównuje Traugutta do Leonidasa pod Termopilami: obaj idą na pewną śmierć.","miejsce":"opowieść dębu: obóz"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Przeczytana cała nowela z Wolnych Lektur (domena publiczna); sprawdzony przebieg zdarzeń i cytaty.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/","rodzaj":"utwór","co":"Przeczytana cała nowela z Wolnych Lektur (domena publiczna); sprawdzony przebieg zdarzeń i cytaty."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Tekst nie nazywa konkretnej bitwy ani oddziału; identyfikacja z historycznymi wydarzeniami 1863 r. niesprawdzona.$lektury$, $lektury${"tekst":"Tekst nie nazywa konkretnej bitwy ani oddziału; identyfikacja z historycznymi wydarzeniami 1863 r. niesprawdzona."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Nowela nie dzieli się na rozdziały; miejsca opisane według warstwy narracji (rama, opowieść dębu, opowieść brzozy).$lektury$, $lektury${"tekst":"Nowela nie dzieli się na rozdziały; miejsca opisane według warstwy narracji (rama, opowieść dębu, opowieść brzozy)."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
  ($lektury$gloria-victis$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Związek Jagmina i Anielki to w tekście sugestia (pocałunki w dłonie, „Siostrze!”), nie jednoznaczna deklaracja.$lektury$, $lektury${"tekst":"Związek Jagmina i Anielki to w tekście sugestia (pocałunki w dłonie, „Siostrze!”), nie jednoznaczna deklaracja."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/gloria-victis-gloria-victis/$lektury$),
