insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$gora-edek$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$początek, skojarzenie z Tangiem$lektury$, $lektury$początek, skojarzenie z Tangiem. narrator. Warszawa, ruchliwa ulica w centrum. Narrator przywołuje Edka z dramatu Mrożka i łączy go ze sceną, którą obserwował na zatłoczonej ulicy.$lektury$, $lektury${"nr":1,"miejsce":"początek, skojarzenie z Tangiem","kto":["narrator"],"gdzie":"Warszawa, ruchliwa ulica w centrum","opis":"Narrator przywołuje Edka z dramatu Mrożka i łączy go ze sceną, którą obserwował na zatłoczonej ulicy."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LPDHCLV14X/71/a/dowiedz-sie/DF6BHUF4D$lektury$),
  ($lektury$gora-edek$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$zwolnienie miejsca parkingowego$lektury$, $lektury$zwolnienie miejsca parkingowego. kierowca fiata, kierowca forda. ulica, rząd zaparkowanych samochodów. Kierowca małego fiata podjeżdża pierwszy do wolnego miejsca, lecz wysuwa się na tyle daleko, że kierowca forda może je zablokować.$lektury$, $lektury${"nr":2,"miejsce":"zwolnienie miejsca parkingowego","kto":["kierowca fiata","kierowca forda"],"gdzie":"ulica, rząd zaparkowanych samochodów","opis":"Kierowca małego fiata podjeżdża pierwszy do wolnego miejsca, lecz wysuwa się na tyle daleko, że kierowca forda może je zablokować."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LPDHCLV14X/71/a/dowiedz-sie/DF6BHUF4D$lektury$),
