insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$herling-esej$lektury$, $lektury$motyw$lektury$, 1, $lektury$Dziennik pisany nocą 1973–1979, zapis o wystawie w Zamku Anioła$lektury$, $lektury$miejsce ekspozycji a odbiór sztuki. Herling łączy wrażenie wywołane przez więzienne ryciny ze zwiedzaniem podziemnego korytarza rzymskiego zamku. Dziennik pisany nocą 1973–1979, zapis o wystawie w Zamku Anioła. $lektury$, $lektury${"motyw":"miejsce ekspozycji a odbiór sztuki","przyklad":"Herling łączy wrażenie wywołane przez więzienne ryciny ze zwiedzaniem podziemnego korytarza rzymskiego zamku.","miejsce":"Dziennik pisany nocą 1973–1979, zapis o wystawie w Zamku Anioła"}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$motyw$lektury$, 2, $lektury$Dziennik pisany nocą 1973–1979, zapis o wystawie w Zamku Anioła$lektury$, $lektury$światło jako składnik doświadczenia. Skąpe oświetlenie w korytarzu potęguje w odczuciu pisarza zagadkowość oglądanych rycin. Dziennik pisany nocą 1973–1979, zapis o wystawie w Zamku Anioła. $lektury$, $lektury${"motyw":"światło jako składnik doświadczenia","przyklad":"Skąpe oświetlenie w korytarzu potęguje w odczuciu pisarza zagadkowość oglądanych rycin.","miejsce":"Dziennik pisany nocą 1973–1979, zapis o wystawie w Zamku Anioła"}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$motyw$lektury$, 3, $lektury$Dziennik pisany nocą 1973–1979, zapis o wystawie w Zamku Anioła$lektury$, $lektury$granice opisu dzieła. Pisarz daje wyraz przekonaniu, że nadmiar objaśnień mógłby naruszyć siłę przeżycia wywołanego przez grafiki. Dziennik pisany nocą 1973–1979, zapis o wystawie w Zamku Anioła. $lektury$, $lektury${"motyw":"granice opisu dzieła","przyklad":"Pisarz daje wyraz przekonaniu, że nadmiar objaśnień mógłby naruszyć siłę przeżycia wywołanego przez grafiki.","miejsce":"Dziennik pisany nocą 1973–1979, zapis o wystawie w Zamku Anioła"}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$motyw$lektury$, 4, $lektury$Dziennik pisany nocą 1980–1983, fragment o Carceri$lektury$, $lektury$więzienie i labirynt. W odczytaniu Joanny Bielskiej-Krawczyk załamania i urwane schody w wizjach Piranesiego pozwalają odczytać wnętrze jako przestrzeń bez drogi wyjścia. Dziennik pisany nocą 1980–1983, fragment o Carceri. $lektury$, $lektury${"motyw":"więzienie i labirynt","przyklad":"W odczytaniu Joanny Bielskiej-Krawczyk załamania i urwane schody w wizjach Piranesiego pozwalają odczytać wnętrze jako przestrzeń bez drogi wyjścia.","miejsce":"Dziennik pisany nocą 1980–1983, fragment o Carceri"}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$motyw$lektury$, 5, $lektury$Dziennik pisany nocą 1980–1983, fragment o Carceri$lektury$, $lektury$samotność i skala. Bielska-Krawczyk interpretuje przytłaczające wnętrza rycin jako obraz zagubienia człowieka w świecie, z którym nie potrafi się porozumieć. Dziennik pisany nocą 1980–1983, fragment o Carceri. $lektury$, $lektury${"motyw":"samotność i skala","przyklad":"Bielska-Krawczyk interpretuje przytłaczające wnętrza rycin jako obraz zagubienia człowieka w świecie, z którym nie potrafi się porozumieć.","miejsce":"Dziennik pisany nocą 1980–1983, fragment o Carceri"}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$motyw$lektury$, 6, $lektury$Dziennik pisany nocą 1984–1988, fragment o Piranesim i Walpole’u$lektury$, $lektury$powinowactwo sztuk. Herling zestawia ryciny Piranesiego z gotycką wyobraźnią Horace’a Walpole’a, co pozwala porównać sposoby budowania grozy w obrazie i literaturze. Dziennik pisany nocą 1984–1988, fragment o Piranesim i Walpole’u. $lektury$, $lektury${"motyw":"powinowactwo sztuk","przyklad":"Herling zestawia ryciny Piranesiego z gotycką wyobraźnią Horace’a Walpole’a, co pozwala porównać sposoby budowania grozy w obrazie i literaturze.","miejsce":"Dziennik pisany nocą 1984–1988, fragment o Piranesim i Walpole’u"}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$utwor$lektury$, 1, $lektury$Dziennik pisany nocą 1973–1979, s. 445 wydania cytowanego przez Bibliotekę Narodową$lektury$, $lektury$Carceri w Zamku Anioła. Zapis o oglądaniu rycin wiąże ich oddziaływanie z podziemną przestrzenią wystawy, półmrokiem i powściągliwością w komentowaniu.$lektury$, $lektury${"tytul":"Carceri w Zamku Anioła","miejsce":"Dziennik pisany nocą 1973–1979, s. 445 wydania cytowanego przez Bibliotekę Narodową","opis":"Zapis o oglądaniu rycin wiąże ich oddziaływanie z podziemną przestrzenią wystawy, półmrokiem i powściągliwością w komentowaniu."}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$utwor$lektury$, 2, $lektury$Dziennik pisany nocą 1980–1983, Pisma zebrane, t. 5, s. 292$lektury$, $lektury$Wyobrażone więzienia Piranesiego. Fragment przywoływany w badaniach jako punkt wyjścia do interpretacji więzienia u Herlinga.$lektury$, $lektury${"tytul":"Wyobrażone więzienia Piranesiego","miejsce":"Dziennik pisany nocą 1980–1983, Pisma zebrane, t. 5, s. 292","opis":"Fragment przywoływany w badaniach jako punkt wyjścia do interpretacji więzienia u Herlinga."}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$utwor$lektury$, 3, $lektury$Dziennik pisany nocą 1984–1988, wyd. Czytelnik 1996, s. 83–84$lektury$, $lektury$Piranesi i Horace Walpole. Fragment zestawia grafika z autorem Zamczyska w Otranto; porównanie dotyczy wyobraźni gotyckiej i grozy.$lektury$, $lektury${"tytul":"Piranesi i Horace Walpole","miejsce":"Dziennik pisany nocą 1984–1988, wyd. Czytelnik 1996, s. 83–84","opis":"Fragment zestawia grafika z autorem Zamczyska w Otranto; porównanie dotyczy wyobraźni gotyckiej i grozy."}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Wykaz dopuszcza wybór eseju Herlinga-Grudzińskiego wśród propozycji wskazanych autorów.$lektury$, $lektury${"url":"https://bip.cke.gov.pl/attachments/download/10092","rodzaj":"opracowanie","co":"Wykaz dopuszcza wybór eseju Herlinga-Grudzińskiego wśród propozycji wskazanych autorów."}$lektury$::jsonb, $lektury$https://bip.cke.gov.pl/attachments/download/10092$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Przedruk zapisu z Dziennika o wystawie grafik Piranesiego w Zamku Anioła; sprawdzono miejsce, oświetlenie i reakcję autora.$lektury$, $lektury${"url":"https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/","rodzaj":"utwór","co":"Przedruk zapisu z Dziennika o wystawie grafik Piranesiego w Zamku Anioła; sprawdzono miejsce, oświetlenie i reakcję autora."}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$zrodlo$lektury$, 3, $lektury$$lektury$, $lektury$Joanna Bielska-Krawczyk, Świat w sąsiedztwie zaświatów, s. 18, analiza obrazu uwięzienia i odsyłacz do zapisu w Dzienniku 1980–1983.$lektury$, $lektury${"url":"https://www.nexto.pl/upload/sklep/universitas/ebook/swiat_w_sasiedztwie_zaswiatow-bielska_krawczyk_joanna-universitas/public/swiat_w_sasiedztwie_zaswiatow-universitas-demo.pdf","rodzaj":"opracowanie","co":"Joanna Bielska-Krawczyk, Świat w sąsiedztwie zaświatów, s. 18, analiza obrazu uwięzienia i odsyłacz do zapisu w Dzienniku 1980–1983."}$lektury$::jsonb, $lektury$https://www.nexto.pl/upload/sklep/universitas/ebook/swiat_w_sasiedztwie_zaswiatow-bielska_krawczyk_joanna-universitas/public/swiat_w_sasiedztwie_zaswiatow-universitas-demo.pdf$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$zrodlo$lektury$, 4, $lektury$$lektury$, $lektury$Studium z odsyłaczem do Dziennika 1984–1988, s. 83–84, o zestawieniu Piranesiego z Walpole’em.$lektury$, $lektury${"url":"https://www.centropannunzio.it/obj/files/annali/annali%202004-2005.pdf","rodzaj":"opracowanie","co":"Studium z odsyłaczem do Dziennika 1984–1988, s. 83–84, o zestawieniu Piranesiego z Walpole’em."}$lektury$::jsonb, $lektury$https://www.centropannunzio.it/obj/files/annali/annali%202004-2005.pdf$lektury$),
  ($lektury$herling-esej$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Katalog podaje temat szkicu, ale bez tytułu i daty; użyto trzech udokumentowanych zapisów o Piranesim z Dziennika pisanego nocą.$lektury$, $lektury${"tekst":"Katalog podaje temat szkicu, ale bez tytułu i daty; użyto trzech udokumentowanych zapisów o Piranesim z Dziennika pisanego nocą."}$lektury$::jsonb, $lektury$https://sensualnosc.bn.org.pl/gustaw-herling-grudzinski-wizualnosc-a-sztuka-433/$lektury$),
