insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$horacy-wybrane$lektury$, $lektury$postac$lektury$, 1, $lektury$Pieśń I, 11$lektury$, $lektury$Leukonoe. Leukonoe. adresatka pieśni I 11, wyobrażona młoda kobieta mówiący radzi jej przestać wróżyć o przyszłości Pieśń I, 11$lektury$, $lektury${"imie":"Leukonoe","odmiany":["Leukonoe"],"rola":"adresatka pieśni I 11, wyobrażona młoda kobieta","relacje":"mówiący radzi jej przestać wróżyć o przyszłości","miejsca":["Pieśń I, 11"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$postac$lektury$, 2, $lektury$Pieśń III, 30$lektury$, $lektury$Melpomena. Melpomena, Melpomeny, Melpomenie, Melpomeno. muza, adresatka pieśni III 30 podmiot prosi ją o uwieńczenie wawrzynem Pieśń III, 30$lektury$, $lektury${"imie":"Melpomena","odmiany":["Melpomena","Melpomeny","Melpomenie","Melpomeno"],"rola":"muza, adresatka pieśni III 30","relacje":"podmiot prosi ją o uwieńczenie wawrzynem","miejsca":["Pieśń III, 30"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$motyw$lektury$, 1, $lektury$Pieśń I, 11$lektury$, $lektury$carpe diem. Podmiot radzi Leukonoe, by nie badała przyszłości, lecz korzystała z chwili, bo czas ucieka. Pieśń I, 11. korzystaj z obecnej doby, nie wierząc następnej!$lektury$, $lektury${"motyw":"carpe diem","przyklad":"Podmiot radzi Leukonoe, by nie badała przyszłości, lecz korzystała z chwili, bo czas ucieka.","miejsce":"Pieśń I, 11","cytat":"korzystaj z obecnej doby, nie wierząc następnej!"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$motyw$lektury$, 2, $lektury$Pieśń I, 11$lektury$, $lektury$przemijanie czasu. Podmiot mówi, że czas nam ucieka zazdrosny w ciągu rozmów. Pieśń I, 11. Czas nam ucieka zazdrosny$lektury$, $lektury${"motyw":"przemijanie czasu","przyklad":"Podmiot mówi, że czas nam ucieka zazdrosny w ciągu rozmów.","miejsce":"Pieśń I, 11","cytat":"Czas nam ucieka zazdrosny"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$motyw$lektury$, 3, $lektury$Pieśń I, 11$lektury$, $lektury$umiar i spokój wobec losu. Zamiast badać wyroki bogów i liczby babilońskie, mówiący radzi wycierpieć, co przyniesie los, i obciąć długie nadzieje krótką miarą. Pieśń I, 11. $lektury$, $lektury${"motyw":"umiar i spokój wobec losu","przyklad":"Zamiast badać wyroki bogów i liczby babilońskie, mówiący radzi wycierpieć, co przyniesie los, i obciąć długie nadzieje krótką miarą.","miejsce":"Pieśń I, 11"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$motyw$lektury$, 4, $lektury$Pieśń III, 30$lektury$, $lektury$nieśmiertelność poety (exegi monumentum). Poeta mówi, że ukończył pomnik trwalszy od spiżu i piramid, bo część jego pozostanie po śmierci. Pieśń III, 30. Nie umrę ja cały;$lektury$, $lektury${"motyw":"nieśmiertelność poety (exegi monumentum)","przyklad":"Poeta mówi, że ukończył pomnik trwalszy od spiżu i piramid, bo część jego pozostanie po śmierci.","miejsce":"Pieśń III, 30","cytat":"Nie umrę ja cały;"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$motyw$lektury$, 5, $lektury$Pieśń III, 30$lektury$, $lektury$trwałość poezji ponad dziełami materialnymi. Pomnik poety nie ulegnie deszczom, wichrom ani upływowi lat. Pieśń III, 30. Ukończyłem już pomnik ten trwalszy od spiżu,$lektury$, $lektury${"motyw":"trwałość poezji ponad dziełami materialnymi","przyklad":"Pomnik poety nie ulegnie deszczom, wichrom ani upływowi lat.","miejsce":"Pieśń III, 30","cytat":"Ukończyłem już pomnik ten trwalszy od spiżu,"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$motyw$lektury$, 6, $lektury$Pieśń III, 30$lektury$, $lektury$pochodzenie i zasługa poety. Poeta podkreśla, że jest synem gminu, a najpierwszy zaszczepił italskie dźwięki w pieśniach eolskich. Pieśń III, 30. $lektury$, $lektury${"motyw":"pochodzenie i zasługa poety","przyklad":"Poeta podkreśla, że jest synem gminu, a najpierwszy zaszczepił italskie dźwięki w pieśniach eolskich.","miejsce":"Pieśń III, 30"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$motyw$lektury$, 7, $lektury$Pieśń III, 30$lektury$, $lektury$apostrofa do muzy. Na końcu pieśni III 30 poeta prosi Melpomenę o uwieńczenie delfickim wawrzynem. Pieśń III, 30. $lektury$, $lektury${"motyw":"apostrofa do muzy","przyklad":"Na końcu pieśni III 30 poeta prosi Melpomenę o uwieńczenie delfickim wawrzynem.","miejsce":"Pieśń III, 30"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$utwor$lektury$, 1, $lektury$Pieśń I, 11$lektury$, $lektury$Pieśń I, 11 (Do Leukonoe). Rada skierowana do Leukonoe, by nie dochodziła, jaki koniec bogowie im przeznaczyli, i nie badała liczb babilońskich; pieśń kończy się wezwaniem do korzystania z chwili.$lektury$, $lektury${"tytul":"Pieśń I, 11 (Do Leukonoe)","miejsce":"Pieśń I, 11","opis":"Rada skierowana do Leukonoe, by nie dochodziła, jaki koniec bogowie im przeznaczyli, i nie badała liczb babilońskich; pieśń kończy się wezwaniem do korzystania z chwili."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$utwor$lektury$, 2, $lektury$Pieśń III, 30$lektury$, $lektury$Pieśń III, 30 (Do Melpomeny, Exegi monumentum). Poeta mówi o ukończeniu pomnika trwalszego od spiżu, o własnej nieśmiertelności dzięki poezji i prosi Melpomenę o uwieńczenie wawrzynem.$lektury$, $lektury${"tytul":"Pieśń III, 30 (Do Melpomeny, Exegi monumentum)","miejsce":"Pieśń III, 30","opis":"Poeta mówi o ukończeniu pomnika trwalszego od spiżu, o własnej nieśmiertelności dzięki poezji i prosi Melpomenę o uwieńczenie wawrzynem."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pobrane i przeczytane Pieśń I 11 i Pieśń III 30 w tłumaczeniu Marcelego Mottego (domena publiczna); sprawdzono listę dostępnych utworów w zbiorze WL.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/","rodzaj":"utwór","co":"Pobrane i przeczytane Pieśń I 11 i Pieśń III 30 w tłumaczeniu Marcelego Mottego (domena publiczna); sprawdzono listę dostępnych utworów w zbiorze WL."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Katalog wymienia jako przykłady Pieśń I 11 i III 30; pełna lista wymaganych utworów Horacego (np. inne pieśni, Ars poetica, satyry) nie jest ustalona i nie została opisana.$lektury$, $lektury${"tekst":"Katalog wymienia jako przykłady Pieśń I 11 i III 30; pełna lista wymaganych utworów Horacego (np. inne pieśni, Ars poetica, satyry) nie jest ustalona i nie została opisana."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Cytaty pochodzą z przekładu Marcelego Mottego z WL; w szkołach często używane są inne tłumaczenia (np. Leopolda Staffa), więc brzmienie cytatów może się różnić.$lektury$, $lektury${"tekst":"Cytaty pochodzą z przekładu Marcelego Mottego z WL; w szkołach często używane są inne tłumaczenia (np. Leopolda Staffa), więc brzmienie cytatów może się różnić."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$),
  ($lektury$horacy-wybrane$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Biografia Horacego i historyczne tło pieśni nie zostały sprawdzone w źródłach.$lektury$, $lektury${"tekst":"Biografia Horacego i historyczne tło pieśni nie zostały sprawdzone w źródłach."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/horacy-wybrane-utwory/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$hymn-do-milosci-ojczyzny$lektury$, $lektury$motyw$lektury$, 1, $lektury$Hymn do miłości ojczyzny, w. 1–2$lektury$, $lektury$miłość do ojczyzny jako wartość najwyższa. Pierwszy wers zwraca się do miłości ojczyzny jak do świętości; tylko ludzie poczciwi ją czują. Hymn do miłości ojczyzny, w. 1–2. Święta miłości kochanej ojczyzny$lektury$, $lektury${"motyw":"miłość do ojczyzny jako wartość najwyższa","przyklad":"Pierwszy wers zwraca się do miłości ojczyzny jak do świętości; tylko ludzie poczciwi ją czują.","miejsce":"Hymn do miłości ojczyzny, w. 1–2","cytat":"Święta miłości kochanej ojczyzny"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-milosci-ojczyzny/$lektury$),
  ($lektury$hymn-do-milosci-ojczyzny$lektury$, $lektury$motyw$lektury$, 2, $lektury$Hymn do miłości ojczyzny, w. 3–8$lektury$, $lektury$gotowość do ofiary. Dla ojczyzny można znosić trucizny, więzy i pęta; wers końcowy mówi, że nie żal ani żyć w nędzy, ani umierać. Hymn do miłości ojczyzny, w. 3–8. Nie żal żyć w nędzy, nie żal i umierać.$lektury$, $lektury${"motyw":"gotowość do ofiary","przyklad":"Dla ojczyzny można znosić trucizny, więzy i pęta; wers końcowy mówi, że nie żal ani żyć w nędzy, ani umierać.","miejsce":"Hymn do miłości ojczyzny, w. 3–8","cytat":"Nie żal żyć w nędzy, nie żal i umierać."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-milosci-ojczyzny/$lektury$),
  ($lektury$hymn-do-milosci-ojczyzny$lektury$, $lektury$motyw$lektury$, 3, $lektury$Hymn do miłości ojczyzny, w. 5$lektury$, $lektury$blizny jako chluba. Rany zdobyte dla ojczyzny uczą, by uznawać kalectwo za zaszczyt. Hymn do miłości ojczyzny, w. 5. $lektury$, $lektury${"motyw":"blizny jako chluba","przyklad":"Rany zdobyte dla ojczyzny uczą, by uznawać kalectwo za zaszczyt.","miejsce":"Hymn do miłości ojczyzny, w. 5"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-milosci-ojczyzny/$lektury$),
  ($lektury$hymn-do-milosci-ojczyzny$lektury$, $lektury$utwor$lektury$, 1, $lektury$całość$lektury$, $lektury$Hymn do miłości ojczyzny. Ośmiowersowy hymn Ignacego Krasickiego, w którym osoba mówiąca zwraca się do „świętej miłości” ojczyzny. Wymienia, co dla niej można znieść: trucizny, więzy, rany; kończy myślą, że warto żyć i umierać dla ojczyzny.$lektury$, $lektury${"tytul":"Hymn do miłości ojczyzny","miejsce":"całość","opis":"Ośmiowersowy hymn Ignacego Krasickiego, w którym osoba mówiąca zwraca się do „świętej miłości” ojczyzny. Wymienia, co dla niej można znieść: trucizny, więzy, rany; kończy myślą, że warto żyć i umierać dla ojczyzny."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-milosci-ojczyzny/$lektury$),
  ($lektury$hymn-do-milosci-ojczyzny$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pełny tekst utworu; cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/hymn-do-milosci-ojczyzny/","rodzaj":"utwór","co":"Pełny tekst utworu; cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-milosci-ojczyzny/$lektury$),
  ($lektury$hymn-do-milosci-ojczyzny$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Okoliczności powstania (pierwodruk, związek z operą „Hymn do miłości ojczyzny” i jej użycie jako pieśni patriotycznej) nie były sprawdzane — do weryfikacji w źródle naukowym.$lektury$, $lektury${"tekst":"Okoliczności powstania (pierwodruk, związek z operą „Hymn do miłości ojczyzny” i jej użycie jako pieśni patriotycznej) nie były sprawdzane — do weryfikacji w źródle naukowym."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-milosci-ojczyzny/$lektury$),
  ($lektury$hymn-do-milosci-ojczyzny$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wolne Lektury podają jedną ośmiowersową zwrotkę; CKE i szkolne wydania mogą podawać ją jako całość.$lektury$, $lektury${"tekst":"Wolne Lektury podają jedną ośmiowersową zwrotkę; CKE i szkolne wydania mogą podawać ją jako całość."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-milosci-ojczyzny/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$ks. I$lektury$, $lektury$ks. I. Chryzes, Agamemnon, Apollo. obóz Achajów pod Troją. Agamemnon odrzuca prośbę Chryzesa o wydanie córki, a Apollo na modlitwę kapłana zsyła zarazę na obóz Achajów.$lektury$, $lektury${"nr":1,"miejsce":"ks. I","kto":["Chryzes","Agamemnon","Apollo"],"gdzie":"obóz Achajów pod Troją","opis":"Agamemnon odrzuca prośbę Chryzesa o wydanie córki, a Apollo na modlitwę kapłana zsyła zarazę na obóz Achajów."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$ks. I$lektury$, $lektury$ks. I. Achilles, Agamemnon, Kalchas, Chryzeida, Bryzeida. obóz Achajów. Gdy Kalchas wyjaśnia przyczynę zarazy, Agamemnon oddaje Chryzeidę i zabiera Achillesowi Bryzeidę, przez co Achilles wycofuje się z walki.$lektury$, $lektury${"nr":2,"miejsce":"ks. I","kto":["Achilles","Agamemnon","Kalchas","Chryzeida","Bryzeida"],"gdzie":"obóz Achajów","opis":"Gdy Kalchas wyjaśnia przyczynę zarazy, Agamemnon oddaje Chryzeidę i zabiera Achillesowi Bryzeidę, przez co Achilles wycofuje się z walki."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$ks. I$lektury$, $lektury$ks. I. Achilles, Tetyda, Zeus. brzeg morza i Olimp. Na prośbę syna Tetyda nakłania Zeusa, aby sprzyjał Trojanom, dopóki Achajowie nie odczują braku Achillesa.$lektury$, $lektury${"nr":3,"miejsce":"ks. I","kto":["Achilles","Tetyda","Zeus"],"gdzie":"brzeg morza i Olimp","opis":"Na prośbę syna Tetyda nakłania Zeusa, aby sprzyjał Trojanom, dopóki Achajowie nie odczują braku Achillesa."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$ks. II$lektury$, $lektury$ks. II. Zeus, Agamemnon, Odyseusz, Tersytes. obóz Achajów. Po zwodniczym śnie zesłanym przez Zeusa Agamemnon zwołuje wojsko, a Odyseusz powstrzymuje odwrót i ucisza Tersytesa.$lektury$, $lektury${"nr":4,"miejsce":"ks. II","kto":["Zeus","Agamemnon","Odyseusz","Tersytes"],"gdzie":"obóz Achajów","opis":"Po zwodniczym śnie zesłanym przez Zeusa Agamemnon zwołuje wojsko, a Odyseusz powstrzymuje odwrót i ucisza Tersytesa."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$ks. III$lektury$, $lektury$ks. III. Parys, Menelaos, Afrodyta, Helena. pole przed Troją i komnata Parysa. Menelaos zyskuje przewagę w pojedynku o Helenę, lecz Afrodyta przenosi Parysa z pola walki do jego komnaty.$lektury$, $lektury${"nr":5,"miejsce":"ks. III","kto":["Parys","Menelaos","Afrodyta","Helena"],"gdzie":"pole przed Troją i komnata Parysa","opis":"Menelaos zyskuje przewagę w pojedynku o Helenę, lecz Afrodyta przenosi Parysa z pola walki do jego komnaty."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$ks. IV$lektury$, $lektury$ks. IV. Atena, Pandar, Menelaos. pole przed Troją. Za namową Ateny Pandar strzela do Menelaosa, naruszając układ zawarty przed pojedynkiem.$lektury$, $lektury${"nr":6,"miejsce":"ks. IV","kto":["Atena","Pandar","Menelaos"],"gdzie":"pole przed Troją","opis":"Za namową Ateny Pandar strzela do Menelaosa, naruszając układ zawarty przed pojedynkiem."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$ks. V$lektury$, $lektury$ks. V. Diomedes, Atena, Afrodyta, Ares, Eneasz. pole bitwy. Diomedes rani Afrodytę, gdy ta osłania Eneasza, a później z pomocą Ateny rani także Aresa.$lektury$, $lektury${"nr":7,"miejsce":"ks. V","kto":["Diomedes","Atena","Afrodyta","Ares","Eneasz"],"gdzie":"pole bitwy","opis":"Diomedes rani Afrodytę, gdy ta osłania Eneasza, a później z pomocą Ateny rani także Aresa."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$ks. VI$lektury$, $lektury$ks. VI. Diomedes, Glaukos. pole bitwy. Diomedes i Glaukos rozpoznają więź gościnności łączącą ich rody i wymieniają się zbrojami.$lektury$, $lektury${"nr":8,"miejsce":"ks. VI","kto":["Diomedes","Glaukos"],"gdzie":"pole bitwy","opis":"Diomedes i Glaukos rozpoznają więź gościnności łączącą ich rody i wymieniają się zbrojami."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$ks. VI$lektury$, $lektury$ks. VI. Hektor, Andromacha, Astyanaks. Troja, przy bramie. Andromacha prosi Hektora, aby się nie narażał, a on na pożegnanie zdejmuje hełm, którego przestraszył się ich syn.$lektury$, $lektury${"nr":9,"miejsce":"ks. VI","kto":["Hektor","Andromacha","Astyanaks"],"gdzie":"Troja, przy bramie","opis":"Andromacha prosi Hektora, aby się nie narażał, a on na pożegnanie zdejmuje hełm, którego przestraszył się ich syn."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$ks. VII$lektury$, $lektury$ks. VII. Hektor, Ajas Telamonida, heroldowie. pole przed Troją. Heroldowie przerywają nastający o zmierzchu pojedynek Hektora i Ajasa, a rywale wymieniają podarunki.$lektury$, $lektury${"nr":10,"miejsce":"ks. VII","kto":["Hektor","Ajas Telamonida","heroldowie"],"gdzie":"pole przed Troją","opis":"Heroldowie przerywają nastający o zmierzchu pojedynek Hektora i Ajasa, a rywale wymieniają podarunki."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
  ($lektury$iliada$lektury$, $lektury$wydarzenie$lektury$, 11, $lektury$ks. VIII$lektury$, $lektury$ks. VIII. Zeus, Hektor, Trojanie, Achajowie. Ida i równina przed Troją. Kiedy w walkach górę biorą Trojanie, Hektor zatrzymuje ich na noc na równinie i nakazuje rozpalić ogniska.$lektury$, $lektury${"nr":11,"miejsce":"ks. VIII","kto":["Zeus","Hektor","Trojanie","Achajowie"],"gdzie":"Ida i równina przed Troją","opis":"Kiedy w walkach górę biorą Trojanie, Hektor zatrzymuje ich na noc na równinie i nakazuje rozpalić ogniska."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/homer-iliada/$lektury$),
