insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$Wstęp$lektury$, $lektury$Wstęp. narrator. brzegi Niemna, granica Litwy i państwa krzyżackiego. Narrator opisuje Niemen jako granicę między Litwinami a Zakonem Krzyżowym; po obu stronach stoją straże, a przez rzekę przechodzą tylko chmiel, słowiki i miłość; zapowiada opowieść o dwojgu ludzi.$lektury$, $lektury${"nr":1,"miejsce":"Wstęp","kto":["narrator"],"gdzie":"brzegi Niemna, granica Litwy i państwa krzyżackiego","opis":"Narrator opisuje Niemen jako granicę między Litwinami a Zakonem Krzyżowym; po obu stronach stoją straże, a przez rzekę przechodzą tylko chmiel, słowiki i miłość; zapowiada opowieść o dwojgu ludzi."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$cz. I (Obiór)$lektury$, $lektury$cz. I (Obiór). komturowie, Konrad Wallenrod. Malbork (Maryjenburg). Komturowie zjeżdżają do stolicy Zakonu na wybór wielkiego mistrza i po naradach największe poparcie ma cudzoziemiec Konrad Wallenrod, sławny z wypraw przeciwko Maurom i Turkom oraz z ubóstwa i pogardy dla świata.$lektury$, $lektury${"nr":2,"miejsce":"cz. I (Obiór)","kto":["komturowie","Konrad Wallenrod"],"gdzie":"Malbork (Maryjenburg)","opis":"Komturowie zjeżdżają do stolicy Zakonu na wybór wielkiego mistrza i po naradach największe poparcie ma cudzoziemiec Konrad Wallenrod, sławny z wypraw przeciwko Maurom i Turkom oraz z ubóstwa i pogardy dla świata."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$cz. I (Obiór)$lektury$, $lektury$cz. I (Obiór). Konrad Wallenrod, Halban. Malbork. Narrator pokazuje Wallenroda jako człowieka ponurego, wrażliwego na słowa „ojczyzna”, „powinność”, „Litwa”, który zwierza się tylko mnichowi Halbanowi, a samotnie pije i śpiewa ponure pieśni w obcym języku.$lektury$, $lektury${"nr":3,"miejsce":"cz. I (Obiór)","kto":["Konrad Wallenrod","Halban"],"gdzie":"Malbork","opis":"Narrator pokazuje Wallenroda jako człowieka ponurego, wrażliwego na słowa „ojczyzna”, „powinność”, „Litwa”, który zwierza się tylko mnichowi Halbanowi, a samotnie pije i śpiewa ponure pieśni w obcym języku."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$cz. II (Hymn)$lektury$, $lektury$cz. II (Hymn). kapituła, arcykomtur Konrad, Halban. Malbork, kaplica i okolice zamku. Zakon śpiewa w kaplicy hymn do Ducha Świętego, po czym Konrad z Halbanem i braćmi wychodzi na równinę i słyszy głos pustelnicy z narożnej wieży.$lektury$, $lektury${"nr":4,"miejsce":"cz. II (Hymn)","kto":["kapituła","arcykomtur Konrad","Halban"],"gdzie":"Malbork, kaplica i okolice zamku","opis":"Zakon śpiewa w kaplicy hymn do Ducha Świętego, po czym Konrad z Halbanem i braćmi wychodzi na równinę i słyszy głos pustelnicy z narożnej wieży."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$cz. II (opis pustelnicy)$lektury$, $lektury$cz. II (opis pustelnicy). pustelnica (Aldona). wieża pod Malborkiem. Narrator opowiada, że od dziesięciu lat w wieży mieszka tajemnicza kobieta, zamurowana na własną prośbę; Konrad kieruje ku wieży swoje śpiewy.$lektury$, $lektury${"nr":5,"miejsce":"cz. II (opis pustelnicy)","kto":["pustelnica (Aldona)"],"gdzie":"wieża pod Malborkiem","opis":"Narrator opowiada, że od dziesięciu lat w wieży mieszka tajemnicza kobieta, zamurowana na własną prośbę; Konrad kieruje ku wieży swoje śpiewy."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$cz. III (początek)$lektury$, $lektury$cz. III (początek). Konrad Wallenrod, komtur. Malbork. Konrad przyjmuje od komtura miecz i krzyż jako wielki mistrz i wszyscy oczekują wojny z Litwą.$lektury$, $lektury${"nr":6,"miejsce":"cz. III (początek)","kto":["Konrad Wallenrod","komtur"],"gdzie":"Malbork","opis":"Konrad przyjmuje od komtura miecz i krzyż jako wielki mistrz i wszyscy oczekują wojny z Litwą."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$cz. III$lektury$, $lektury$cz. III. Konrad Wallenrod. Malbork. Mija rok bez wojny; Konrad nie prowadzi wojsk i zaostrza dyscyplinę w zakonie, narzuca posty, pokuty i kary, a Litwini coraz śmielej napadają na pogranicze.$lektury$, $lektury${"nr":7,"miejsce":"cz. III","kto":["Konrad Wallenrod"],"gdzie":"Malbork","opis":"Mija rok bez wojny; Konrad nie prowadzi wojsk i zaostrza dyscyplinę w zakonie, narzuca posty, pokuty i kary, a Litwini coraz śmielej napadają na pogranicze."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$cz. III$lektury$, $lektury$cz. III. Witołd, Zakon. Malbork. Witołd, wygnany z tronu litewskiego, szuka u Zakonu poparcia, ale nie dostaje wsparcia; bracia szemrzą i szukają mistrza.$lektury$, $lektury${"nr":8,"miejsce":"cz. III","kto":["Witołd","Zakon"],"gdzie":"Malbork","opis":"Witołd, wygnany z tronu litewskiego, szuka u Zakonu poparcia, ale nie dostaje wsparcia; bracia szemrzą i szukają mistrza."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$cz. III (Pieśń z wieży, rozmowa Konrada z pustelnicą)$lektury$, $lektury$cz. III (Pieśń z wieży, rozmowa Konrada z pustelnicą). Konrad Wallenrod, Aldona (głos z wieży). wieża pod Malborkiem, nad jeziorem. Co wieczór Konrad chodzi nad jezioro pod wieżę; z wieży Aldona śpiewa i rozmawia z nim; ona opowiada, jak weszła do pustelni, by zobaczyć go raz jeszcze, a on mówi o zemście i o cierpieniu.$lektury$, $lektury${"nr":9,"miejsce":"cz. III (Pieśń z wieży, rozmowa Konrada z pustelnicą)","kto":["Konrad Wallenrod","Aldona (głos z wieży)"],"gdzie":"wieża pod Malborkiem, nad jeziorem","opis":"Co wieczór Konrad chodzi nad jezioro pod wieżę; z wieży Aldona śpiewa i rozmawia z nim; ona opowiada, jak weszła do pustelni, by zobaczyć go raz jeszcze, a on mówi o zemście i o cierpieniu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$cz. III (zakończenie)$lektury$, $lektury$cz. III (zakończenie). Konrad Wallenrod. okolice wieży. O świcie Konrad żegna pustelnicę i znika w krzakach; narrator porównuje go do ducha piekielnego uciekającego na dźwięk dzwonu.$lektury$, $lektury${"nr":10,"miejsce":"cz. III (zakończenie)","kto":["Konrad Wallenrod"],"gdzie":"okolice wieży","opis":"O świcie Konrad żegna pustelnicę i znika w krzakach; narrator porównuje go do ducha piekielnego uciekającego na dźwięk dzwonu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 11, $lektury$cz. IV (Uczta)$lektury$, $lektury$cz. IV (Uczta). Konrad Wallenrod, Witołd, komturowie, bracia. Malbork. W dzień patrona Konrad wydaje ucztę dla stu braci i księcia Witołda ze świtą; jest niezadowolony z głośnej biesiady i żąda innego śpiewaka niż Włoch i trubadur.$lektury$, $lektury${"nr":11,"miejsce":"cz. IV (Uczta)","kto":["Konrad Wallenrod","Witołd","komturowie","bracia"],"gdzie":"Malbork","opis":"W dzień patrona Konrad wydaje ucztę dla stu braci i księcia Witołda ze świtą; jest niezadowolony z głośnej biesiady i żąda innego śpiewaka niż Włoch i trubadur."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 12, $lektury$cz. IV (Uczta, Pieśń Wajdeloty)$lektury$, $lektury$cz. IV (Uczta, Pieśń Wajdeloty). Halban (wajdelota), Konrad Wallenrod, Witołd. Malbork, sala uczty. Do śpiewu zgłasza się stary wajdelota (to Halban w przebraniu); śpiewa o zarazie, o upadku Litwy i o zdrajcach, a Witołd blednie z gniewu i wstydu.$lektury$, $lektury${"nr":12,"miejsce":"cz. IV (Uczta, Pieśń Wajdeloty)","kto":["Halban (wajdelota)","Konrad Wallenrod","Witołd"],"gdzie":"Malbork, sala uczty","opis":"Do śpiewu zgłasza się stary wajdelota (to Halban w przebraniu); śpiewa o zarazie, o upadku Litwy i o zdrajcach, a Witołd blednie z gniewu i wstydu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 13, $lektury$cz. IV (Powieść Wajdeloty)$lektury$, $lektury$cz. IV (Powieść Wajdeloty). Walter Alf, Winrych, wajdelota, Kiejstut. Prusy i Litwa. W powieści młodzieniec Walter Alf, porwany z Litwy jako dziecko i wychowany przez wielkiego mistrza Winrycha, ucieka z wajdelotą do Litwinów, bo wajdelota podsycał w nim tęsknotę za ojczyzną; książę Kiejstut przyjmuje ich do Kowna.$lektury$, $lektury${"nr":13,"miejsce":"cz. IV (Powieść Wajdeloty)","kto":["Walter Alf","Winrych","wajdelota","Kiejstut"],"gdzie":"Prusy i Litwa","opis":"W powieści młodzieniec Walter Alf, porwany z Litwy jako dziecko i wychowany przez wielkiego mistrza Winrycha, ucieka z wajdelotą do Litwinów, bo wajdelota podsycał w nim tęsknotę za ojczyzną; książę Kiejstut przyjmuje ich do Kowna."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 14, $lektury$cz. IV (Powieść Wajdeloty)$lektury$, $lektury$cz. IV (Powieść Wajdeloty). Walter Alf, Aldona, Kiejstut. Kowno. Walter i córka Kiejstuta, Aldona, zakochują się; Kiejstut wydaje córkę za Waltera, bo jest mu potrzebny dla Litwy.$lektury$, $lektury${"nr":14,"miejsce":"cz. IV (Powieść Wajdeloty)","kto":["Walter Alf","Aldona","Kiejstut"],"gdzie":"Kowno","opis":"Walter i córka Kiejstuta, Aldona, zakochują się; Kiejstut wydaje córkę za Waltera, bo jest mu potrzebny dla Litwy."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 15, $lektury$cz. IV (Powieść Wajdeloty)$lektury$, $lektury$cz. IV (Powieść Wajdeloty). Walter Alf, Kiejstut, Aldona, Krzyżacy. Kowno, Kiejdany, Rudawa. Krzyżacy zdobywają Kowno i Kiejdany, a bitwa na błoniach Rudawy kończy się klęską Litwinów; Walter, znając potęgę Zakonu, mówi Aldonie, że jedyna droga ocalenia to zdrada i zemsta.$lektury$, $lektury${"nr":15,"miejsce":"cz. IV (Powieść Wajdeloty)","kto":["Walter Alf","Kiejstut","Aldona","Krzyżacy"],"gdzie":"Kowno, Kiejdany, Rudawa","opis":"Krzyżacy zdobywają Kowno i Kiejdany, a bitwa na błoniach Rudawy kończy się klęską Litwinów; Walter, znając potęgę Zakonu, mówi Aldonie, że jedyna droga ocalenia to zdrada i zemsta."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 16, $lektury$cz. IV (Powieść Wajdeloty)$lektury$, $lektury$cz. IV (Powieść Wajdeloty). Walter Alf, wajdelota, Aldona. okolice Kowna. Walter z wajdelotą wyjeżdża, by wstąpić do Zakonu i go zniszczyć od środka; w dolinie żegna się z Aldoną, która wybiera klasztorną wieżę.$lektury$, $lektury${"nr":16,"miejsce":"cz. IV (Powieść Wajdeloty)","kto":["Walter Alf","wajdelota","Aldona"],"gdzie":"okolice Kowna","opis":"Walter z wajdelotą wyjeżdża, by wstąpić do Zakonu i go zniszczyć od środka; w dolinie żegna się z Aldoną, która wybiera klasztorną wieżę."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
  ($lektury$konrad-wallenrod$lektury$, $lektury$wydarzenie$lektury$, 17, $lektury$cz. IV (Alpuhara)$lektury$, $lektury$cz. IV (Alpuhara). Konrad Wallenrod, Almanzor. Malbork, sala uczty. Wstrząśnięty powieścią Konrad pije, bierze lutnię i śpiewa balladę o Almanzorze z Alpuhary, który mścił się na Hiszpanach, zarażając ich dżumą; potem Konrad zasypia pijany, a Witołd opuszcza ucztę.$lektury$, $lektury${"nr":17,"miejsce":"cz. IV (Alpuhara)","kto":["Konrad Wallenrod","Almanzor"],"gdzie":"Malbork, sala uczty","opis":"Wstrząśnięty powieścią Konrad pije, bierze lutnię i śpiewa balladę o Almanzorze z Alpuhary, który mścił się na Hiszpanach, zarażając ich dżumą; potem Konrad zasypia pijany, a Witołd opuszcza ucztę."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/konrad-wallenrod/$lektury$),
