insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$ksiega-koheleta$lektury$, $lektury$postac$lektury$, 1, $lektury$Koh 1,1$lektury$, $lektury$Kohelet. Kohelet, Koheleta, Koheletowi, Koheletem. mędrzec, narrator księgi, który bada sens ludzkiego życia zwraca się do czytelnika Koh 1,1; Koh 12$lektury$, $lektury${"imie":"Kohelet","odmiany":["Kohelet","Koheleta","Koheletowi","Koheletem"],"rola":"mędrzec, narrator księgi, który bada sens ludzkiego życia","relacje":"zwraca się do czytelnika","miejsca":["Koh 1,1","Koh 12"]}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$motyw$lektury$, 1, $lektury$Koh 1,2–11$lektury$, $lektury$marność wszystkiego. Kohelet na początku księgi stwierdza, że wszystko jest marnością, a człowiek na próżno się trudzi pod słońcem. Koh 1,2–11. $lektury$, $lektury${"motyw":"marność wszystkiego","przyklad":"Kohelet na początku księgi stwierdza, że wszystko jest marnością, a człowiek na próżno się trudzi pod słońcem.","miejsce":"Koh 1,2–11"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$motyw$lektury$, 2, $lektury$Koh 1,12–2,26$lektury$, $lektury$poszukiwanie sensu w mądrości, bogactwie i rozkoszy. Kohelet opisuje, że poznawał mądrość, gromadził majątek i zażywał przyjemności, a na koniec uznał to za pogoń za wiatrem. Koh 1,12–2,26. $lektury$, $lektury${"motyw":"poszukiwanie sensu w mądrości, bogactwie i rozkoszy","przyklad":"Kohelet opisuje, że poznawał mądrość, gromadził majątek i zażywał przyjemności, a na koniec uznał to za pogoń za wiatrem.","miejsce":"Koh 1,12–2,26"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$motyw$lektury$, 3, $lektury$Koh 3,1–8$lektury$, $lektury$czas i rytm życia. Księga wylicza, że jest czas rodzenia i umierania, sadzenia i wyrywania, płaczu i śmiechu. Koh 3,1–8. $lektury$, $lektury${"motyw":"czas i rytm życia","przyklad":"Księga wylicza, że jest czas rodzenia i umierania, sadzenia i wyrywania, płaczu i śmiechu.","miejsce":"Koh 3,1–8"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$motyw$lektury$, 4, $lektury$Koh 2,12–17; Koh 3,18–22$lektury$, $lektury$przemijanie i nieuchronna śmierć. Kohelet podkreśla, że wszyscy, mądrzy i głupi, spotkają ten sam los. Koh 2,12–17; Koh 3,18–22. $lektury$, $lektury${"motyw":"przemijanie i nieuchronna śmierć","przyklad":"Kohelet podkreśla, że wszyscy, mądrzy i głupi, spotkają ten sam los.","miejsce":"Koh 2,12–17; Koh 3,18–22"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$motyw$lektury$, 5, $lektury$Koh 2,24–26; Koh 9,7–10$lektury$, $lektury$radość z codziennych darów. Kohelet wielokrotnie radzi cieszyć się jedzeniem, pracą i życiem jako darem od Boga. Koh 2,24–26; Koh 9,7–10. $lektury$, $lektury${"motyw":"radość z codziennych darów","przyklad":"Kohelet wielokrotnie radzi cieszyć się jedzeniem, pracą i życiem jako darem od Boga.","miejsce":"Koh 2,24–26; Koh 9,7–10"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$motyw$lektury$, 6, $lektury$Koh 11,9–12,8$lektury$, $lektury$młodość i starość. W zakończeniu Kohelet radzi pamiętać o Stwórcy w dniach młodości, przed nadejściem starości. Koh 11,9–12,8. $lektury$, $lektury${"motyw":"młodość i starość","przyklad":"W zakończeniu Kohelet radzi pamiętać o Stwórcy w dniach młodości, przed nadejściem starości.","miejsce":"Koh 11,9–12,8"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$motyw$lektury$, 7, $lektury$Koh 12,13–14$lektury$, $lektury$bojaźń Boża jako wniosek końcowy. Księga kończy się radą, by bać się Boga i zachowywać jego przykazania. Koh 12,13–14. $lektury$, $lektury${"motyw":"bojaźń Boża jako wniosek końcowy","przyklad":"Księga kończy się radą, by bać się Boga i zachowywać jego przykazania.","miejsce":"Koh 12,13–14"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$utwor$lektury$, 1, $lektury$Koh 1,1–11$lektury$, $lektury$Marność wszystkiego (wstęp księgi). Kohelet stwierdza, że wszystko jest marnością, a pokolenia i rzeczy powracają w niekończącym się cyklu.$lektury$, $lektury${"tytul":"Marność wszystkiego (wstęp księgi)","miejsce":"Koh 1,1–11","opis":"Kohelet stwierdza, że wszystko jest marnością, a pokolenia i rzeczy powracają w niekończącym się cyklu."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$utwor$lektury$, 2, $lektury$Koh 3,1–8$lektury$, $lektury$Wiersz o czasie. Lista zestawionych przeciwieństw (rodzić się i umierać, płakać i śmiać się), pokazująca, że każda rzecz ma swój czas.$lektury$, $lektury${"tytul":"Wiersz o czasie","miejsce":"Koh 3,1–8","opis":"Lista zestawionych przeciwieństw (rodzić się i umierać, płakać i śmiać się), pokazująca, że każda rzecz ma swój czas."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$utwor$lektury$, 3, $lektury$Koh 11,9–12,8$lektury$, $lektury$Wezwanie do pamięci o Stwórcy. Rada skierowana do młodego człowieka, by pamiętał o Stwórcy, zanim nadejdzie starość i śmierć, opisana poetyckimi obrazami.$lektury$, $lektury${"tytul":"Wezwanie do pamięci o Stwórcy","miejsce":"Koh 11,9–12,8","opis":"Rada skierowana do młodego człowieka, by pamiętał o Stwórcy, zanim nadejdzie starość i śmierć, opisana poetyckimi obrazami."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Biblia Tysiąclecia, tekst do sprawdzenia opisanych fragmentów$lektury$, $lektury${"url":"https://biblia.deon.pl/","rodzaj":"utwór","co":"Biblia Tysiąclecia, tekst do sprawdzenia opisanych fragmentów"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Plik nie był sprawdzany w żadnym źródle online ani w wydaniu Biblii; powstał z ogólnej znajomości Księgi Koheleta i wymaga weryfikacji (np. w Biblii Tysiąclecia).$lektury$, $lektury${"tekst":"Plik nie był sprawdzany w żadnym źródle online ani w wydaniu Biblii; powstał z ogólnej znajomości Księgi Koheleta i wymaga weryfikacji (np. w Biblii Tysiąclecia)."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Cytatów nie podano, bo tekst współczesnych polskich wydań Biblii jest objęty prawem autorskim.$lektury$, $lektury${"tekst":"Cytatów nie podano, bo tekst współczesnych polskich wydań Biblii jest objęty prawem autorskim."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-koheleta$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Zakres „fragmentów” Księgi Koheleta wymaganych na maturze nie jest ustalony w katalogu; wybrano najczęściej omawiane fragmenty.$lektury$, $lektury${"tekst":"Zakres „fragmentów” Księgi Koheleta wymaganych na maturze nie jest ustalony w katalogu; wybrano najczęściej omawiane fragmenty."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
