  ($lektury$ksiega-koheleta$lektury$, $lektury$weryfikacja$lektury$, 5, $lektury$$lektury$, $lektury$Opis nie został porównany z tekstem Biblii przy zapisie; sprawdzić rozdziały i wersety.$lektury$, $lektury${"tekst":"Opis nie został porównany z tekstem Biblii przy zapisie; sprawdzić rozdziały i wersety."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$ksiega-psalmow$lektury$, $lektury$postac$lektury$, 1, $lektury$Ps 22$lektury$, $lektury$Pan (Bóg). Pan, Pana, Panu, Panem, Bóg, Boga. adresat modlitw i pasterz w psalmie 23 do niego zwraca się psalmista Ps 22; Ps 23; Ps 130$lektury$, $lektury${"imie":"Pan (Bóg)","odmiany":["Pan","Pana","Panu","Panem","Bóg","Boga"],"rola":"adresat modlitw i pasterz w psalmie 23","relacje":"do niego zwraca się psalmista","miejsca":["Ps 22","Ps 23","Ps 130"]}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-psalmow$lektury$, $lektury$postac$lektury$, 2, $lektury$Ps 22$lektury$, $lektury$Psalmista. psalmista, psalmisty, psalmiście. podmiot liryczny psalmów, osoba w potrzebie lub zaufaniu zwraca się do Boga Ps 22; Ps 23; Ps 130$lektury$, $lektury${"imie":"Psalmista","odmiany":["psalmista","psalmisty","psalmiście"],"rola":"podmiot liryczny psalmów, osoba w potrzebie lub zaufaniu","relacje":"zwraca się do Boga","miejsca":["Ps 22","Ps 23","Ps 130"]}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-psalmow$lektury$, $lektury$motyw$lektury$, 1, $lektury$Ps 23$lektury$, $lektury$Bóg jako pasterz. W Psalmie 23 psalmista porównuje Boga do pasterza, który prowadzi go na zielone pastwiska i nad wodę spokojną. Ps 23. $lektury$, $lektury${"motyw":"Bóg jako pasterz","przyklad":"W Psalmie 23 psalmista porównuje Boga do pasterza, który prowadzi go na zielone pastwiska i nad wodę spokojną.","miejsce":"Ps 23"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-psalmow$lektury$, $lektury$motyw$lektury$, 2, $lektury$Ps 23$lektury$, $lektury$zaufanie w obliczu zagrożenia. W Psalmie 23 psalmista nie boi się, idąc ciemną doliną, bo Bóg jest przy nim. Ps 23. $lektury$, $lektury${"motyw":"zaufanie w obliczu zagrożenia","przyklad":"W Psalmie 23 psalmista nie boi się, idąc ciemną doliną, bo Bóg jest przy nim.","miejsce":"Ps 23"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-psalmow$lektury$, $lektury$motyw$lektury$, 3, $lektury$Ps 22$lektury$, $lektury$opuszczenie i skarga do Boga. Psalm 22 zaczyna się wołaniem o opuszczenie przez Boga i opisuje cierpienie psalmisty. Ps 22. $lektury$, $lektury${"motyw":"opuszczenie i skarga do Boga","przyklad":"Psalm 22 zaczyna się wołaniem o opuszczenie przez Boga i opisuje cierpienie psalmisty.","miejsce":"Ps 22"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
  ($lektury$ksiega-psalmow$lektury$, $lektury$motyw$lektury$, 4, $lektury$Ps 22$lektury$, $lektury$przejście od lamentu do ufności i uwielbienia. Psalm 22 po skardze przechodzi w ufność i obietnicę głoszenia chwały Bożej. Ps 22. $lektury$, $lektury${"motyw":"przejście od lamentu do ufności i uwielbienia","przyklad":"Psalm 22 po skardze przechodzi w ufność i obietnicę głoszenia chwały Bożej.","miejsce":"Ps 22"}$lektury$::jsonb, $lektury$https://biblia.deon.pl/$lektury$),
