insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$początek utworu (wstęp)$lektury$, $lektury$początek utworu (wstęp). narrator. —. Narrator prosi Boga o rozum i zapowiada opowieść o świętym, który miłował Boga, zaczerpniętą z księgi, którą czytał.$lektury$, $lektury${"nr":1,"miejsce":"początek utworu (wstęp)","kto":["narrator"],"gdzie":"—","opis":"Narrator prosi Boga o rozum i zapowiada opowieść o świętym, który miłował Boga, zaczerpniętą z księgi, którą czytał."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$opis rodziny Aleksego$lektury$, $lektury$opis rodziny Aleksego. Eufemian, Aglijas. Rzym. W Rzymie żyje pobożny i bogaty pan Eufemian z żoną Aglijas; utrzymuje trzystu rycerzy, karmi wdowy, sieroty i pielgrzymów, ale nie ma dzieci.$lektury$, $lektury${"nr":2,"miejsce":"opis rodziny Aleksego","kto":["Eufemian","Aglijas"],"gdzie":"Rzym","opis":"W Rzymie żyje pobożny i bogaty pan Eufemian z żoną Aglijas; utrzymuje trzystu rycerzy, karmi wdowy, sieroty i pielgrzymów, ale nie ma dzieci."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$opis rodziny Aleksego$lektury$, $lektury$opis rodziny Aleksego. Eufemian, Aglijas, Aleksy. Rzym. Małżonkowie proszą Boga o potomka, Bóg ich wysłuchuje i rodzi się syn Aleksy, który od dziecka służy Bogu.$lektury$, $lektury${"nr":3,"miejsce":"opis rodziny Aleksego","kto":["Eufemian","Aglijas","Aleksy"],"gdzie":"Rzym","opis":"Małżonkowie proszą Boga o potomka, Bóg ich wysłuchuje i rodzi się syn Aleksy, który od dziecka służy Bogu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$rozmowa Aleksego z ojcem$lektury$, $lektury$rozmowa Aleksego z ojcem. Eufemian, Aleksy. Rzym. Gdy Aleksy ma dwadzieścia cztery lata, ojciec każe mu się ożenić, a syn z posłuszeństwa się zgadza.$lektury$, $lektury${"nr":4,"miejsce":"rozmowa Aleksego z ojcem","kto":["Eufemian","Aleksy"],"gdzie":"Rzym","opis":"Gdy Aleksy ma dwadzieścia cztery lata, ojciec każe mu się ożenić, a syn z posłuszeństwa się zgadza."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$ślub Aleksego$lektury$, $lektury$ślub Aleksego. Aleksy, cesarz, papież Innocenty, królewna. Rzym. Cesarz oddaje Aleksemu córkę za żonę, a papież Innocenty udziela ślubu.$lektury$, $lektury${"nr":5,"miejsce":"ślub Aleksego","kto":["Aleksy","cesarz","papież Innocenty","królewna"],"gdzie":"Rzym","opis":"Cesarz oddaje Aleksemu córkę za żonę, a papież Innocenty udziela ślubu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$noc poślubna$lektury$, $lektury$noc poślubna. Aleksy, królewna. Rzym. W noc poślubną Aleksy zwraca żonie jej pierścień, zostawia ją w dziewictwie, prosi, by służyła Bogu, i mówi, że jutro odejdzie służyć Bogu; królewna się zgadza.$lektury$, $lektury${"nr":6,"miejsce":"noc poślubna","kto":["Aleksy","królewna"],"gdzie":"Rzym","opis":"W noc poślubną Aleksy zwraca żonie jej pierścień, zostawia ją w dziewictwie, prosi, by służyła Bogu, i mówi, że jutro odejdzie służyć Bogu; królewna się zgadza."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$odejście z domu$lektury$, $lektury$odejście z domu. Aleksy, Eufemian. Rzym, morze. Rano Aleksy zabiera trochę srebra i złota, o niczym nie mówi nikomu poza żoną i odpływa morzem; ojciec i matka zostają w żałości.$lektury$, $lektury${"nr":7,"miejsce":"odejście z domu","kto":["Aleksy","Eufemian"],"gdzie":"Rzym, morze","opis":"Rano Aleksy zabiera trochę srebra i złota, o niczym nie mówi nikomu poza żoną i odpływa morzem; ojciec i matka zostają w żałości."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$pobyt w obcej ziemi$lektury$, $lektury$pobyt w obcej ziemi. Aleksy. obca ziemia (nazwa niepodana). Aleksy rozdaje swoje mienie żebrakom, duchownym i żakom, po czym siedzi jako żebrak pod kościołem i nikt nie wie o jego pochodzeniu.$lektury$, $lektury${"nr":8,"miejsce":"pobyt w obcej ziemi","kto":["Aleksy"],"gdzie":"obca ziemia (nazwa niepodana)","opis":"Aleksy rozdaje swoje mienie żebrakom, duchownym i żakom, po czym siedzi jako żebrak pod kościołem i nikt nie wie o jego pochodzeniu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$cud z obrazem Matki Bożej$lektury$, $lektury$cud z obrazem Matki Bożej. Aleksy, żak (kościelny), obraz Matki Bożej. obca ziemia, kościół. Gdy kościół zamknięto, Aleksy leży na mrozie przy progu; obraz Matki Bożej przemawia do żaka z kluczem i każe otworzyć kościół temu człowiekowi.$lektury$, $lektury${"nr":9,"miejsce":"cud z obrazem Matki Bożej","kto":["Aleksy","żak (kościelny)","obraz Matki Bożej"],"gdzie":"obca ziemia, kościół","opis":"Gdy kościół zamknięto, Aleksy leży na mrozie przy progu; obraz Matki Bożej przemawia do żaka z kluczem i każe otworzyć kościół temu człowiekowi."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$cud z obrazem Matki Bożej$lektury$, $lektury$cud z obrazem Matki Bożej. Aleksy, żak (kościelny), lud. obca ziemia. Cud powtarza się często, żak opowiada o nim wszystkim, lud uznaje Aleksego za świętego i obdarza go hojnie.$lektury$, $lektury${"nr":10,"miejsce":"cud z obrazem Matki Bożej","kto":["Aleksy","żak (kościelny)","lud"],"gdzie":"obca ziemia","opis":"Cud powtarza się często, żak opowiada o nim wszystkim, lud uznaje Aleksego za świętego i obdarza go hojnie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 11, $lektury$poszukiwania syna$lektury$, $lektury$poszukiwania syna. Eufemian, słudzy Eufemiana, Aleksy. Jelidocnia (nazwa w tekście), obce miasto. Ojciec rozsyła sługi po świecie; znajdują Aleksego w mieście, ale go nie poznają, a on poznaje ich i przyjmuje od nich jałmużnę.$lektury$, $lektury${"nr":11,"miejsce":"poszukiwania syna","kto":["Eufemian","słudzy Eufemiana","Aleksy"],"gdzie":"Jelidocnia (nazwa w tekście), obce miasto","opis":"Ojciec rozsyła sługi po świecie; znajdują Aleksego w mieście, ale go nie poznają, a on poznaje ich i przyjmuje od nich jałmużnę."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 12, $lektury$poszukiwania syna$lektury$, $lektury$poszukiwania syna. słudzy Eufemiana, Eufemian, matka Aleksego. Rzym. Słudzy wracają do Rzymu z wieścią, że nie znaleźli syna, a rodzice na nowo rozpaczają.$lektury$, $lektury${"nr":12,"miejsce":"poszukiwania syna","kto":["słudzy Eufemiana","Eufemian","matka Aleksego"],"gdzie":"Rzym","opis":"Słudzy wracają do Rzymu z wieścią, że nie znaleźli syna, a rodzice na nowo rozpaczają."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 13, $lektury$ucieczka przed sławą$lektury$, $lektury$ucieczka przed sławą. Aleksy. Tars w Syrii (według tekstu). Niechętny rosnącej sławie Aleksy wsiada na statek i płynie do Tarsu w Syrii, gdzie czcił świętego Pawła.$lektury$, $lektury${"nr":13,"miejsce":"ucieczka przed sławą","kto":["Aleksy"],"gdzie":"Tars w Syrii (według tekstu)","opis":"Niechętny rosnącej sławie Aleksy wsiada na statek i płynie do Tarsu w Syrii, gdzie czcił świętego Pawła."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 14, $lektury$powrót do Rzymu$lektury$, $lektury$powrót do Rzymu. Aleksy. morze, Rzym. Zmienia się wiatr i zawraca statek; Aleksy trafia do Rzymu, dziękuje Bogu i postanawia cierpieć w domu ojca.$lektury$, $lektury${"nr":14,"miejsce":"powrót do Rzymu","kto":["Aleksy"],"gdzie":"morze, Rzym","opis":"Zmienia się wiatr i zawraca statek; Aleksy trafia do Rzymu, dziękuje Bogu i postanawia cierpieć w domu ojca."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 15, $lektury$spotkanie z ojcem przed grodem$lektury$, $lektury$spotkanie z ojcem przed grodem. Aleksy, Eufemian. Rzym, przed grodem. Aleksy spotyka ojca przed grodem i w imię jego syna Aleksego prosi o jałmużnę i okruchy ze stołu; ojciec płacze, nie poznając go, i oddaje go pod opiekę szafarza.$lektury$, $lektury${"nr":15,"miejsce":"spotkanie z ojcem przed grodem","kto":["Aleksy","Eufemian"],"gdzie":"Rzym, przed grodem","opis":"Aleksy spotyka ojca przed grodem i w imię jego syna Aleksego prosi o jałmużnę i okruchy ze stołu; ojciec płacze, nie poznając go, i oddaje go pod opiekę szafarza."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 16, $lektury$życie pod schodami$lektury$, $lektury$życie pod schodami. Aleksy, szafarz. dwór Eufemiana w Rzymie. Szafarz źle traktuje Aleksego; ten leży pod schodami, a domownicy wylewają na niego pomyje, co znosi dla Boga.$lektury$, $lektury${"nr":16,"miejsce":"życie pod schodami","kto":["Aleksy","szafarz"],"gdzie":"dwór Eufemiana w Rzymie","opis":"Szafarz źle traktuje Aleksego; ten leży pod schodami, a domownicy wylewają na niego pomyje, co znosi dla Boga."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 17, $lektury$śmierć Aleksego$lektury$, $lektury$śmierć Aleksego. Aleksy. dwór Eufemiana w Rzymie. Przed śmiercią Aleksy sam pisze list o swoich cierpieniach i o całym życiu, po czym umiera, ściskając go w dłoni.$lektury$, $lektury${"nr":17,"miejsce":"śmierć Aleksego","kto":["Aleksy"],"gdzie":"dwór Eufemiana w Rzymie","opis":"Przed śmiercią Aleksy sam pisze list o swoich cierpieniach i o całym życiu, po czym umiera, ściskając go w dłoni."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 18, $lektury$cud dzwonów$lektury$, $lektury$cud dzwonów. lud Rzymu, dziecko. Rzym. Po jego śmierci same dzwony biją we wszystkich rzymskich kościołach; ludzie szukają zmarłego, aż dziecko wskazuje, że leży u Eufemiana pod schodami.$lektury$, $lektury${"nr":18,"miejsce":"cud dzwonów","kto":["lud Rzymu","dziecko"],"gdzie":"Rzym","opis":"Po jego śmierci same dzwony biją we wszystkich rzymskich kościołach; ludzie szukają zmarłego, aż dziecko wskazuje, że leży u Eufemiana pod schodami."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 19, $lektury$uroczyste odnalezienie ciała$lektury$, $lektury$uroczyste odnalezienie ciała. papież, cesarz, kapłani, lud. Rzym, dwór Eufemiana. Papież z kardynałami i cesarz z duchowieństwem idą do ciała z chorągwiami; od ciała wychodzi woń, a chorzy odzyskują zdrowie.$lektury$, $lektury${"nr":19,"miejsce":"uroczyste odnalezienie ciała","kto":["papież","cesarz","kapłani","lud"],"gdzie":"Rzym, dwór Eufemiana","opis":"Papież z kardynałami i cesarz z duchowieństwem idą do ciała z chorągwiami; od ciała wychodzi woń, a chorzy odzyskują zdrowie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
  ($lektury$legenda-o-aleksym$lektury$, $lektury$wydarzenie$lektury$, 20, $lektury$list w dłoni zmarłego$lektury$, $lektury$list w dłoni zmarłego. cesarz, papież, żona Aleksego. Rzym. Nikt, ani cesarz, ani papież, nie może wyjąć listu z ręki zmarłego; dopiero żona Aleksego wyciąga rękę i list sam wpada jej w dłoń.$lektury$, $lektury${"nr":20,"miejsce":"list w dłoni zmarłego","kto":["cesarz","papież","żona Aleksego"],"gdzie":"Rzym","opis":"Nikt, ani cesarz, ani papież, nie może wyjąć listu z ręki zmarłego; dopiero żona Aleksego wyciąga rękę i list sam wpada jej w dłoń."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/legenda-o-sw-aleksym/$lektury$),
