insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$piesn-nad-piesniami$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$Pnp 1,2–8$lektury$, $lektury$Pnp 1,2–8. Oblubienica, Oblubieniec, Córki jerozolimskie, Chór. winnice i szałasy pasterzy przywołane w dialogu. Oblubienica wspomina pilnowanie winnic i pyta ukochanego, gdzie może go znaleźć przy stadach.$lektury$, $lektury${"nr":1,"miejsce":"Pnp 1,2–8","kto":["Oblubienica","Oblubieniec","Córki jerozolimskie","Chór"],"gdzie":"winnice i szałasy pasterzy przywołane w dialogu","opis":"Oblubienica wspomina pilnowanie winnic i pyta ukochanego, gdzie może go znaleźć przy stadach."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
  ($lektury$piesn-nad-piesniami$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$Pnp 1,9–2,7$lektury$, $lektury$Pnp 1,9–2,7. Oblubienica, Oblubieniec, Córki jerozolimskie. sceny bliskości. Ukochani opisują się nawzajem za pomocą obrazów związanych z przyrodą i wonnościami, a oblubieniec zwraca się do córek jerozolimskich z prośbą o uszanowanie odpoczynku ukochanej.$lektury$, $lektury${"nr":2,"miejsce":"Pnp 1,9–2,7","kto":["Oblubienica","Oblubieniec","Córki jerozolimskie"],"gdzie":"sceny bliskości","opis":"Ukochani opisują się nawzajem za pomocą obrazów związanych z przyrodą i wonnościami, a oblubieniec zwraca się do córek jerozolimskich z prośbą o uszanowanie odpoczynku ukochanej."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
  ($lektury$piesn-nad-piesniami$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$Pnp 2,8–14$lektury$, $lektury$Pnp 2,8–14. Oblubienica, Oblubieniec. za murem domu, wiosenny krajobraz. Oblubienica widzi powracającego ukochanego za oknem, a on zaprasza ją do wyjścia i opisuje oznaki wiosny.$lektury$, $lektury${"nr":3,"miejsce":"Pnp 2,8–14","kto":["Oblubienica","Oblubieniec"],"gdzie":"za murem domu, wiosenny krajobraz","opis":"Oblubienica widzi powracającego ukochanego za oknem, a on zaprasza ją do wyjścia i opisuje oznaki wiosny."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
  ($lektury$piesn-nad-piesniami$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$Pnp 2,15–17$lektury$, $lektury$Pnp 2,15–17. Oblubienica, Chór, Oblubieniec. kwitnące winnice i góry Beter przywołane w pieśni. Po obrazie lisów zagrażających winnicom oblubienica mówi o więzi z ukochanym i zwraca się do niego.$lektury$, $lektury${"nr":4,"miejsce":"Pnp 2,15–17","kto":["Oblubienica","Chór","Oblubieniec"],"gdzie":"kwitnące winnice i góry Beter przywołane w pieśni","opis":"Po obrazie lisów zagrażających winnicom oblubienica mówi o więzi z ukochanym i zwraca się do niego."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
  ($lektury$piesn-nad-piesniami$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$Pnp 3,1–5$lektury$, $lektury$Pnp 3,1–5. Oblubienica, Oblubieniec, Strażnicy miasta. nocne ulice miasta. Oblubienica pyta strażników o ukochanego, znajduje go po ich minięciu i chce zabrać go do domu matki.$lektury$, $lektury${"nr":5,"miejsce":"Pnp 3,1–5","kto":["Oblubienica","Oblubieniec","Strażnicy miasta"],"gdzie":"nocne ulice miasta","opis":"Oblubienica pyta strażników o ukochanego, znajduje go po ich minięciu i chce zabrać go do domu matki."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
  ($lektury$piesn-nad-piesniami$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$Pnp 3,6–11$lektury$, $lektury$Pnp 3,6–11. Chór, Salomon, Córki jerozolimskie. okolice miasta. Chór opisuje lektykę Salomona otoczoną przez wojowników i wzywa córki jerozolimskie, aby zobaczyły króla w dniu zaślubin.$lektury$, $lektury${"nr":6,"miejsce":"Pnp 3,6–11","kto":["Chór","Salomon","Córki jerozolimskie"],"gdzie":"okolice miasta","opis":"Chór opisuje lektykę Salomona otoczoną przez wojowników i wzywa córki jerozolimskie, aby zobaczyły króla w dniu zaślubin."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
  ($lektury$piesn-nad-piesniami$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$Pnp 4,1–15$lektury$, $lektury$Pnp 4,1–15. Oblubieniec, Oblubienica. wypowiedź z obrazami gór, roślin i źródła. Oblubieniec chwali urodę ukochanej i porównuje ją do ogrodu z wonnymi roślinami.$lektury$, $lektury${"nr":7,"miejsce":"Pnp 4,1–15","kto":["Oblubieniec","Oblubienica"],"gdzie":"wypowiedź z obrazami gór, roślin i źródła","opis":"Oblubieniec chwali urodę ukochanej i porównuje ją do ogrodu z wonnymi roślinami."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
  ($lektury$piesn-nad-piesniami$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$Pnp 4,16–5,1$lektury$, $lektury$Pnp 4,16–5,1. Oblubienica, Oblubieniec. ogród w obrazach pieśni. Oblubienica zaprasza ukochanego do ogrodu, a on odpowiada opisem wejścia do niego i korzystania z jego darów.$lektury$, $lektury${"nr":8,"miejsce":"Pnp 4,16–5,1","kto":["Oblubienica","Oblubieniec"],"gdzie":"ogród w obrazach pieśni","opis":"Oblubienica zaprasza ukochanego do ogrodu, a on odpowiada opisem wejścia do niego i korzystania z jego darów."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
  ($lektury$piesn-nad-piesniami$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$Pnp 5,2–6$lektury$, $lektury$Pnp 5,2–6. Oblubienica, Oblubieniec. próg domu oblubienicy nocą. Oblubieniec puka do drzwi, a kiedy oblubienica po chwili otwiera, jego już tam nie ma.$lektury$, $lektury${"nr":9,"miejsce":"Pnp 5,2–6","kto":["Oblubienica","Oblubieniec"],"gdzie":"próg domu oblubienicy nocą","opis":"Oblubieniec puka do drzwi, a kiedy oblubienica po chwili otwiera, jego już tam nie ma."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
