  ($lektury$piesn-nad-piesniami$lektury$, $lektury$utwor$lektury$, 4, $lektury$Pnp 5,2–6,10$lektury$, $lektury$Pieśń czwarta. Zniknięcie ukochanego, poszukiwanie oraz pochwały wyglądu obojga.$lektury$, $lektury${"tytul":"Pieśń czwarta","miejsce":"Pnp 5,2–6,10","opis":"Zniknięcie ukochanego, poszukiwanie oraz pochwały wyglądu obojga."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
  ($lektury$piesn-nad-piesniami$lektury$, $lektury$utwor$lektury$, 5, $lektury$Pnp 6,11–8,4$lektury$, $lektury$Pieśń piąta. Chóralna i indywidualna pochwała urody oblubienicy oraz jej zaproszenie do winnic.$lektury$, $lektury${"tytul":"Pieśń piąta","miejsce":"Pnp 6,11–8,4","opis":"Chóralna i indywidualna pochwała urody oblubienicy oraz jej zaproszenie do winnic."}$lektury$::jsonb, $lektury$https://biblia.deon.pl/ksiega.php?id=26$lektury$),
