insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$poetyka$lektury$, $lektury$motyw$lektury$, 1, $lektury$rozdz. I–V (wstęp; streszczenie tłumacza)$lektury$, $lektury$mimesis – naśladowanie jako źródło poezji. Arystoteles wywodzi poezję z wrodzonego instynktu naśladowania i z poczucia rytmu i harmonii; poezja różni się środkami, przedmiotem i sposobem naśladowania. rozdz. I–V (wstęp; streszczenie tłumacza). $lektury$, $lektury${"motyw":"mimesis – naśladowanie jako źródło poezji","przyklad":"Arystoteles wywodzi poezję z wrodzonego instynktu naśladowania i z poczucia rytmu i harmonii; poezja różni się środkami, przedmiotem i sposobem naśladowania.","miejsce":"rozdz. I–V (wstęp; streszczenie tłumacza)"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$motyw$lektury$, 2, $lektury$rozdz. VI$lektury$, $lektury$definicja tragedii. Tragedia to naśladowanie poważnej, skończonej akcji przez działające osoby (a nie przez opowiadanie), które budząc litość i trwogę dokonuje oczyszczenia (ukojenia i zrównoważenia) tych uczuć. rozdz. VI. Jest zatem tragedia naśladowaniem akcji poważnej i w sobie skończonej$lektury$, $lektury${"motyw":"definicja tragedii","przyklad":"Tragedia to naśladowanie poważnej, skończonej akcji przez działające osoby (a nie przez opowiadanie), które budząc litość i trwogę dokonuje oczyszczenia (ukojenia i zrównoważenia) tych uczuć.","miejsce":"rozdz. VI","cytat":"Jest zatem tragedia naśladowaniem akcji poważnej i w sobie skończonej"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$motyw$lektury$, 3, $lektury$rozdz. VI$lektury$, $lektury$katharsis – ukojenie i zrównoważenie uczuć. W definicji tragedii skutkiem oglądania cierpienia na scenie jest „ukojenie i zrównoważenie” litości i trwogi (w przekładzie Siedleckiego). rozdz. VI. dokonywająca ukojenia i zrównoważenia uczuć tego rodzaju$lektury$, $lektury${"motyw":"katharsis – ukojenie i zrównoważenie uczuć","przyklad":"W definicji tragedii skutkiem oglądania cierpienia na scenie jest „ukojenie i zrównoważenie” litości i trwogi (w przekładzie Siedleckiego).","miejsce":"rozdz. VI","cytat":"dokonywająca ukojenia i zrównoważenia uczuć tego rodzaju"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$motyw$lektury$, 4, $lektury$rozdz. VII–IX$lektury$, $lektury$fabuła jako najważniejsza część tragedii. Fabuła ma mieć początek, środek i koniec, być jednością czynności (nie jedności osoby czy czasu) i opierać się na prawdopodobieństwie lub konieczności. rozdz. VII–IX. $lektury$, $lektury${"motyw":"fabuła jako najważniejsza część tragedii","przyklad":"Fabuła ma mieć początek, środek i koniec, być jednością czynności (nie jedności osoby czy czasu) i opierać się na prawdopodobieństwie lub konieczności.","miejsce":"rozdz. VII–IX"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$motyw$lektury$, 5, $lektury$rozdz. IX$lektury$, $lektury$poezja a historia – prawda ogólna. Zadaniem poety nie jest opowiadanie zdarzeń, które zaszły, lecz takich, które mogły zajść; dlatego poezja jest według Arystotelesa bardziej filozoficzna od historii. rozdz. IX. poezja bardziej filozoficzna i głębsza niż historia$lektury$, $lektury${"motyw":"poezja a historia – prawda ogólna","przyklad":"Zadaniem poety nie jest opowiadanie zdarzeń, które zaszły, lecz takich, które mogły zajść; dlatego poezja jest według Arystotelesa bardziej filozoficzna od historii.","miejsce":"rozdz. IX","cytat":"poezja bardziej filozoficzna i głębsza niż historia"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$motyw$lektury$, 6, $lektury$rozdz. XI$lektury$, $lektury$przełom i rozpoznanie. Przełom to przejście do czegoś przeciwnego, np. w „Edypie” posłaniec, który chce uspokoić króla, sprawia skutek odwrotny; rozpoznanie to przejście z niewiedzy w poznanie, najpiękniejsze, gdy zbiega się z przełomem, jak w „Edypie”. rozdz. XI. przejście z niewiedzy w poznanie$lektury$, $lektury${"motyw":"przełom i rozpoznanie","przyklad":"Przełom to przejście do czegoś przeciwnego, np. w „Edypie” posłaniec, który chce uspokoić króla, sprawia skutek odwrotny; rozpoznanie to przejście z niewiedzy w poznanie, najpiękniejsze, gdy zbiega się z przełomem, jak w „Edypie”.","miejsce":"rozdz. XI","cytat":"przejście z niewiedzy w poznanie"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$motyw$lektury$, 7, $lektury$rozdz. XIII$lektury$, $lektury$bohater tragiczny i błąd tragiczny. Najlepszy bohater tragedii to człowiek ani zupełnie cnotliwy, ani niegodziwy, który przechodzi ze szczęścia w nieszczęście przez błąd wielki, a nie przez niegodziwość; takie przejście budzi litość i trwogę. rozdz. XIII. przez błąd wielki człowieka$lektury$, $lektury${"motyw":"bohater tragiczny i błąd tragiczny","przyklad":"Najlepszy bohater tragedii to człowiek ani zupełnie cnotliwy, ani niegodziwy, który przechodzi ze szczęścia w nieszczęście przez błąd wielki, a nie przez niegodziwość; takie przejście budzi litość i trwogę.","miejsce":"rozdz. XIII","cytat":"przez błąd wielki człowieka"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$motyw$lektury$, 8, $lektury$rozdz. XIV$lektury$, $lektury$litość i trwoga wywołane samą kompozycją. Arystoteles uważa za lepsze wywołanie litości i trwogi samym układem zdarzeń niż efektami sceny; tego dozna każdy, słuchając opowieści o Edypie. rozdz. XIV. $lektury$, $lektury${"motyw":"litość i trwoga wywołane samą kompozycją","przyklad":"Arystoteles uważa za lepsze wywołanie litości i trwogi samym układem zdarzeń niż efektami sceny; tego dozna każdy, słuchając opowieści o Edypie.","miejsce":"rozdz. XIV"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$motyw$lektury$, 9, $lektury$rozdz. XV (streszczenie tłumacza)$lektury$, $lektury$charaktery w tragedii. Charaktery powinny być szlachetne, zgodne z istotą rzeczy, wierne i jednostajne, a bohaterów warto idealizować, jak Homer Achillesa. rozdz. XV (streszczenie tłumacza). $lektury$, $lektury${"motyw":"charaktery w tragedii","przyklad":"Charaktery powinny być szlachetne, zgodne z istotą rzeczy, wierne i jednostajne, a bohaterów warto idealizować, jak Homer Achillesa.","miejsce":"rozdz. XV (streszczenie tłumacza)"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$motyw$lektury$, 10, $lektury$rozdz. XXVI$lektury$, $lektury$tragedia wyższa od epopei. Po porównaniu obu gatunków Arystoteles przyznaje wyższość tragedii. rozdz. XXVI. $lektury$, $lektury${"motyw":"tragedia wyższa od epopei","przyklad":"Po porównaniu obu gatunków Arystoteles przyznaje wyższość tragedii.","miejsce":"rozdz. XXVI"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$utwor$lektury$, 1, $lektury$rozdz. I–V$lektury$, $lektury$Rozdz. I–V: o naśladowaniu i źródłach poezji. Podział poezji według środków (mowa, rytm, melodia), przedmiotu (szlachetniejsze albo pośledniejsze charaktery) i sposobu naśladowania; dwa źródła poezji: instynkt naśladowania i zmysł rytmu; krótka historia rozwoju tragedii i komedii.$lektury$, $lektury${"tytul":"Rozdz. I–V: o naśladowaniu i źródłach poezji","miejsce":"rozdz. I–V","opis":"Podział poezji według środków (mowa, rytm, melodia), przedmiotu (szlachetniejsze albo pośledniejsze charaktery) i sposobu naśladowania; dwa źródła poezji: instynkt naśladowania i zmysł rytmu; krótka historia rozwoju tragedii i komedii."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$utwor$lektury$, 2, $lektury$rozdz. VI$lektury$, $lektury$Rozdz. VI: definicja tragedii i jej części. Słynna definicja tragedii jako naśladowania poważnej, skończonej akcji budzącej litość i trwogę oraz wyliczenie sześciu części: fabuła, charaktery, sposób rozwijania myśli, wysłowienie, melodia i wystawa sceniczna.$lektury$, $lektury${"tytul":"Rozdz. VI: definicja tragedii i jej części","miejsce":"rozdz. VI","opis":"Słynna definicja tragedii jako naśladowania poważnej, skończonej akcji budzącej litość i trwogę oraz wyliczenie sześciu części: fabuła, charaktery, sposób rozwijania myśli, wysłowienie, melodia i wystawa sceniczna."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$utwor$lektury$, 3, $lektury$rozdz. VII–IX$lektury$, $lektury$Rozdz. VII–IX: fabuła, jedność akcji, prawdopodobieństwo. Fabuła jako całość z początkiem, środkiem i końcem oraz jednością czynności; opis różnicy między poetą a historykiem (rozdz. IX).$lektury$, $lektury${"tytul":"Rozdz. VII–IX: fabuła, jedność akcji, prawdopodobieństwo","miejsce":"rozdz. VII–IX","opis":"Fabuła jako całość z początkiem, środkiem i końcem oraz jednością czynności; opis różnicy między poetą a historykiem (rozdz. IX)."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$utwor$lektury$, 4, $lektury$rozdz. X–XI$lektury$, $lektury$Rozdz. X–XI: fabuła prosta i splątana, przełom i rozpoznanie. Przełom, rozpoznanie i pathos jako elementy fabuły zawikłanej; przykład „Edypa”.$lektury$, $lektury${"tytul":"Rozdz. X–XI: fabuła prosta i splątana, przełom i rozpoznanie","miejsce":"rozdz. X–XI","opis":"Przełom, rozpoznanie i pathos jako elementy fabuły zawikłanej; przykład „Edypa”."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$utwor$lektury$, 5, $lektury$rozdz. XIII–XIV$lektury$, $lektury$Rozdz. XIII–XIV: jaki bohater i jakie zdarzenia budzą litość i trwogę. Najlepszy bohater tragedii: człowiek pośredni, który popełnia wielki błąd; najlepsze efekty osiąga się samą kompozycją, a nie wystawą sceniczną.$lektury$, $lektury${"tytul":"Rozdz. XIII–XIV: jaki bohater i jakie zdarzenia budzą litość i trwogę","miejsce":"rozdz. XIII–XIV","opis":"Najlepszy bohater tragedii: człowiek pośredni, który popełnia wielki błąd; najlepsze efekty osiąga się samą kompozycją, a nie wystawą sceniczną."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$utwor$lektury$, 6, $lektury$rozdz. XV–XVIII$lektury$, $lektury$Rozdz. XV–XVIII: charaktery, rodzaje rozpoznania i rady dla poetów. Wymagania wobec charakterów; w rozdz. XVI rodzaje rozpoznania (ze znamion zewnętrznych, umyślnie stworzone przez poetę, przez wspomnienie, przez rozumowanie, z mylnego wniosku; najlepsze wynika z samych zdarzeń); praktyczne rady: przenosić się w sytuację widzów, najpierw szkicować osnowę, starannie prowadzić zawiązanie i rozwiązanie.$lektury$, $lektury${"tytul":"Rozdz. XV–XVIII: charaktery, rodzaje rozpoznania i rady dla poetów","miejsce":"rozdz. XV–XVIII","opis":"Wymagania wobec charakterów; w rozdz. XVI rodzaje rozpoznania (ze znamion zewnętrznych, umyślnie stworzone przez poetę, przez wspomnienie, przez rozumowanie, z mylnego wniosku; najlepsze wynika z samych zdarzeń); praktyczne rady: przenosić się w sytuację widzów, najpierw szkicować osnowę, starannie prowadzić zawiązanie i rozwiązanie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$utwor$lektury$, 7, $lektury$rozdz. XIX–XXII$lektury$, $lektury$Rozdz. XIX–XXII: myśl i wysłowienie. Uwagi o sposobie rozwijania myśli (odesłanie do Retoryki) oraz o wysłowieniu, gramatyce i stylu.$lektury$, $lektury${"tytul":"Rozdz. XIX–XXII: myśl i wysłowienie","miejsce":"rozdz. XIX–XXII","opis":"Uwagi o sposobie rozwijania myśli (odesłanie do Retoryki) oraz o wysłowieniu, gramatyce i stylu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$utwor$lektury$, 8, $lektury$rozdz. XXIII–XXVI$lektury$, $lektury$Rozdz. XXIII–XXVI: epopeja i porównanie z tragedią. Podobieństwa i różnice między epopeją a tragedią, rozwiązania zarzutów wobec poetów i w końcu uznanie wyższości tragedii.$lektury$, $lektury${"tytul":"Rozdz. XXIII–XXVI: epopeja i porównanie z tragedią","miejsce":"rozdz. XXIII–XXVI","opis":"Podobieństwa i różnice między epopeją a tragedią, rozwiązania zarzutów wobec poetów i w końcu uznanie wyższości tragedii."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pobrany cały tekst (tłum. Stanisław Siedlecki, domena publiczna według noty WL); przeczytane streszczenie tłumacza, rozdz. VI, IX, XI, XIII, XIV w całości lub w dużej części; cytaty sprawdzone w tekście.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/","rodzaj":"utwór","co":"Pobrany cały tekst (tłum. Stanisław Siedlecki, domena publiczna według noty WL); przeczytane streszczenie tłumacza, rozdz. VI, IX, XI, XIII, XIV w całości lub w dużej części; cytaty sprawdzone w tekście."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Katalog podaje „Fragmenty” bez wykazu; zakres wymaganych na maturze rozdziałów nie został sprawdzony w źródle CKE; podano wszystkie rozdziały zachowanego tekstu.$lektury$, $lektury${"tekst":"Katalog podaje „Fragmenty” bez wykazu; zakres wymaganych na maturze rozdziałów nie został sprawdzony w źródle CKE; podano wszystkie rozdziały zachowanego tekstu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Rozdz. XV–XVIII i XXIII–XXVI opisane na podstawie streszczenia tłumacza, nie pełnego tekstu.$lektury$, $lektury${"tekst":"Rozdz. XV–XVIII i XXIII–XXVI opisane na podstawie streszczenia tłumacza, nie pełnego tekstu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Pojęcie „katharsis” w przekładzie Siedleckiego występuje jako „ukojenie i zrównoważenie uczuć”; polska tradycja używa „oczyszczenie” (wiedza ogólna, nie sprawdzona tu w źródle).$lektury$, $lektury${"tekst":"Pojęcie „katharsis” w przekładzie Siedleckiego występuje jako „ukojenie i zrównoważenie uczuć”; polska tradycja używa „oczyszczenie” (wiedza ogólna, nie sprawdzona tu w źródle)."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$),
  ($lektury$poetyka$lektury$, $lektury$weryfikacja$lektury$, 4, $lektury$$lektury$, $lektury$Tekst jest zachowany niecały (tylko pierwsza z dwóch ksiąg, według uwag tłumacza).$lektury$, $lektury${"tekst":"Tekst jest zachowany niecały (tylko pierwsza z dwóch ksiąg, według uwag tłumacza)."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/arystoteles-poetyka/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$poezja-baroku$lektury$, $lektury$motyw$lektury$, 1, $lektury$Krótkość żywota$lektury$, $lektury$przemijanie i krótkość życia. Naborowski zestawia życie ludzkie z dźwiękiem, cieniem, dymem, wiatrem i błyskiem; wiele ludzi ma kolebkę równą grobowi. Krótkość żywota. $lektury$, $lektury${"motyw":"przemijanie i krótkość życia","przyklad":"Naborowski zestawia życie ludzkie z dźwiękiem, cieniem, dymem, wiatrem i błyskiem; wiele ludzi ma kolebkę równą grobowi.","miejsce":"Krótkość żywota"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$motyw$lektury$, 2, $lektury$Krótkość żywota$lektury$, $lektury$upływ czasu. Pierwszy wers wprowadza obraz godzin, które nieustannie mijają, a po nich przychodzi kolejne pokolenie. Krótkość żywota. $lektury$, $lektury${"motyw":"upływ czasu","przyklad":"Pierwszy wers wprowadza obraz godzin, które nieustannie mijają, a po nich przychodzi kolejne pokolenie.","miejsce":"Krótkość żywota"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$motyw$lektury$, 3, $lektury$Do trupa$lektury$, $lektury$śmierć miłosna i paradoks. Mówiący utożsamia się z trupem, bo „zabity” jest strzałą miłości, a nie śmierci. Do trupa. $lektury$, $lektury${"motyw":"śmierć miłosna i paradoks","przyklad":"Mówiący utożsamia się z trupem, bo „zabity” jest strzałą miłości, a nie śmierci.","miejsce":"Do trupa"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$motyw$lektury$, 4, $lektury$Do trupa$lektury$, $lektury$antyteza i koncept. Cały sonet buduje przeciwstawienia: strzała śmierci — strzała miłości, lód — piekielna śreżoga, proch — popiół. Do trupa. $lektury$, $lektury${"motyw":"antyteza i koncept","przyklad":"Cały sonet buduje przeciwstawienia: strzała śmierci — strzała miłości, lód — piekielna śreżoga, proch — popiół.","miejsce":"Do trupa"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$motyw$lektury$, 5, $lektury$Do trupa$lektury$, $lektury$miłość jako cierpienie. Cierpienie zakochanego jest dłuższe niż śmierć, bo ogień miłości nie pozwala rozsypać się w popiół. Do trupa. $lektury$, $lektury${"motyw":"miłość jako cierpienie","przyklad":"Cierpienie zakochanego jest dłuższe niż śmierć, bo ogień miłości nie pozwala rozsypać się w popiół.","miejsce":"Do trupa"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$utwor$lektury$, 1, $lektury$Daniel Naborowski, Krótkość żywota$lektury$, $lektury$Krótkość żywota. Dwunastowersowy wiersz o przemijaniu: godzina za godziną mija, życie ludzkie porównane jest do dźwięku, cienia, dymu, wiatru. Między narodzinami a śmiercią mieści się ledwie czwarta część mgnienia, a wielu ludzi miało kolebkę równą grobowi. Typowy barokowy motyw vanitas i krótkości życia.$lektury$, $lektury${"tytul":"Krótkość żywota","miejsce":"Daniel Naborowski, Krótkość żywota","opis":"Dwunastowersowy wiersz o przemijaniu: godzina za godziną mija, życie ludzkie porównane jest do dźwięku, cienia, dymu, wiatru. Między narodzinami a śmiercią mieści się ledwie czwarta część mgnienia, a wielu ludzi miało kolebkę równą grobowi. Typowy barokowy motyw vanitas i krótkości życia."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$utwor$lektury$, 2, $lektury$Jan Andrzej Morsztyn, Do trupa$lektury$, $lektury$Do trupa. Sonet z konceptem: mówiący zestawia siebie, zabitego strzałą miłości, z trupem, zabitym strzałą śmierci. Wylicza podobieństwa i różnice (płomień skryty — świece jawne, rozum w łańcuchu — związane ręce) i kończy, że trup się rozsypie prochem, a on sam, „stawszy się żywiołem”, nie może rozsypać się popiołem. Utwór pokazuje barokową grę paradoksów i hiperbol.$lektury$, $lektury${"tytul":"Do trupa","miejsce":"Jan Andrzej Morsztyn, Do trupa","opis":"Sonet z konceptem: mówiący zestawia siebie, zabitego strzałą miłości, z trupem, zabitym strzałą śmierci. Wylicza podobieństwa i różnice (płomień skryty — świece jawne, rozum w łańcuchu — związane ręce) i kończy, że trup się rozsypie prochem, a on sam, „stawszy się żywiołem”, nie może rozsypać się popiołem. Utwór pokazuje barokową grę paradoksów i hiperbol."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pełny tekst wiersza; cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/","rodzaj":"utwór","co":"Pełny tekst wiersza; cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Pełny tekst sonetu; cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/do-trupa/","rodzaj":"utwór","co":"Pełny tekst sonetu; cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/do-trupa/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Katalog podaje dwa wiersze jako przykłady (Naborowski, Krótkość żywota; Morsztyn, Do trupa); brak listy wymaganych utworów w podstawie z 2024 r. — nie opracowano innych (np. Sęp Szarzyński, Hieronim Morsztyn).$lektury$, $lektury${"tekst":"Katalog podaje dwa wiersze jako przykłady (Naborowski, Krótkość żywota; Morsztyn, Do trupa); brak listy wymaganych utworów w podstawie z 2024 r. — nie opracowano innych (np. Sęp Szarzyński, Hieronim Morsztyn)."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Gatunek („Do trupa” jako sonet) wynika z układu tekstu (14 wersów); zaliczenie do konceptyzmu i vanitas to interpretacja, nie sprawdzona w opracowaniu.$lektury$, $lektury${"tekst":"Gatunek („Do trupa” jako sonet) wynika z układu tekstu (14 wersów); zaliczenie do konceptyzmu i vanitas to interpretacja, nie sprawdzona w opracowaniu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$),
  ($lektury$poezja-baroku$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Autorstwo i data powstania obu wierszy nie były sprawdzane w źródle poza nagłówkami Wolnych Lektur.$lektury$, $lektury${"tekst":"Autorstwo i data powstania obu wierszy nie były sprawdzane w źródle poza nagłówkami Wolnych Lektur."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/naborowski-krotkosc-zywota/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$polikarp$lektury$, $lektury$postac$lektury$, 1, $lektury$prolog$lektury$, $lektury$Mistrz Polikarp. Polikarp, Polikarpa, Polikarpowi, Polikarpem, mistrz, mistrza. uczony mistrz, który prosi Boga o ujrzenie śmierci rozmawia ze Śmiercią i przeraża się jej widoku prolog; ukazanie się Śmierci; rozmowa ze Śmiercią$lektury$, $lektury${"imie":"Mistrz Polikarp","odmiany":["Polikarp","Polikarpa","Polikarpowi","Polikarpem","mistrz","mistrza"],"rola":"uczony mistrz, który prosi Boga o ujrzenie śmierci","relacje":"rozmawia ze Śmiercią i przeraża się jej widoku","miejsca":["prolog","ukazanie się Śmierci","rozmowa ze Śmiercią"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/rozmowa-mistrza-polikarpa-ze-smiercia/$lektury$),
  ($lektury$polikarp$lektury$, $lektury$postac$lektury$, 2, $lektury$ukazanie się Śmierci$lektury$, $lektury$Śmierć. Śmierć, Śmierci, Śmiercią, Śmirci. postać alegoryczna ukazana jako nagi, chudy, blady szkielet z kosą rozmawia z Polikarpem i zapowiada, że zbawi życia wszystkich ukazanie się Śmierci; mowa Śmierci$lektury$, $lektury${"imie":"Śmierć","odmiany":["Śmierć","Śmierci","Śmiercią","Śmirci"],"rola":"postać alegoryczna ukazana jako nagi, chudy, blady szkielet z kosą","relacje":"rozmawia z Polikarpem i zapowiada, że zbawi życia wszystkich","miejsca":["ukazanie się Śmierci","mowa Śmierci"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/rozmowa-mistrza-polikarpa-ze-smiercia/$lektury$),
  ($lektury$polikarp$lektury$, $lektury$postac$lektury$, 3, $lektury$prolog$lektury$, $lektury$Bóg. Bóg, Boga, Bogu, Gospodzin. adresat prologu i prośby Polikarpa zgadza się, by Śmierć ukazała się mistrzowi prolog$lektury$, $lektury${"imie":"Bóg","odmiany":["Bóg","Boga","Bogu","Gospodzin"],"rola":"adresat prologu i prośby Polikarpa","relacje":"zgadza się, by Śmierć ukazała się mistrzowi","miejsca":["prolog"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/rozmowa-mistrza-polikarpa-ze-smiercia/$lektury$),
  ($lektury$polikarp$lektury$, $lektury$motyw$lektury$, 1, $lektury$prolog; mowa Śmierci$lektury$, $lektury$śmierć nie omija nikogo. Prolog mówi, że żaden człowiek, stary ani młody, nie ujdzie śmiertelnej szkody, a Śmierć mówi, że przed jej kosą nikt nie uciecze. prolog; mowa Śmierci. Kogo koli śmierć udusi,$lektury$, $lektury${"motyw":"śmierć nie omija nikogo","przyklad":"Prolog mówi, że żaden człowiek, stary ani młody, nie ujdzie śmiertelnej szkody, a Śmierć mówi, że przed jej kosą nikt nie uciecze.","miejsce":"prolog; mowa Śmierci","cytat":"Kogo koli śmierć udusi,"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/rozmowa-mistrza-polikarpa-ze-smiercia/$lektury$),
  ($lektury$polikarp$lektury$, $lektury$motyw$lektury$, 2, $lektury$ukazanie się Śmierci$lektury$, $lektury$memento mori i okrutność śmierci. Śmierć ukazuje się jako chuda, blada postać z kosą, bez warg, z odsłoniętymi zębami, i przeraża Polikarpa tak, że ten pada na ziemię. ukazanie się Śmierci. $lektury$, $lektury${"motyw":"memento mori i okrutność śmierci","przyklad":"Śmierć ukazuje się jako chuda, blada postać z kosą, bez warg, z odsłoniętymi zębami, i przeraża Polikarpa tak, że ten pada na ziemię.","miejsce":"ukazanie się Śmierci"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/rozmowa-mistrza-polikarpa-ze-smiercia/$lektury$),
  ($lektury$polikarp$lektury$, $lektury$motyw$lektury$, 3, $lektury$mowa Śmierci$lektury$, $lektury$śmierć i godności ziemskie. Śmierć zapowiada, że z króla zdejmie koronę, a jej kosa siecze doktorów i mistrzów. mowa Śmierci. Siekę doktory i mistrze,$lektury$, $lektury${"motyw":"śmierć i godności ziemskie","przyklad":"Śmierć zapowiada, że z króla zdejmie koronę, a jej kosa siecze doktorów i mistrzów.","miejsce":"mowa Śmierci","cytat":"Siekę doktory i mistrze,"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/rozmowa-mistrza-polikarpa-ze-smiercia/$lektury$),
  ($lektury$polikarp$lektury$, $lektury$motyw$lektury$, 4, $lektury$rozmowa ze Śmiercią (o pochodzeniu)$lektury$, $lektury$pochodzenie śmierci i grzech pierworodny. Śmierć opowiada, że Bóg stworzył człowieka, aby żył wiecznie, ale zakazał mu jedzenia z drzewa; po upadku Adama pojawiła się śmierć. rozmowa ze Śmiercią (o pochodzeniu). $lektury$, $lektury${"motyw":"pochodzenie śmierci i grzech pierworodny","przyklad":"Śmierć opowiada, że Bóg stworzył człowieka, aby żył wiecznie, ale zakazał mu jedzenia z drzewa; po upadku Adama pojawiła się śmierć.","miejsce":"rozmowa ze Śmiercią (o pochodzeniu)"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/rozmowa-mistrza-polikarpa-ze-smiercia/$lektury$),
  ($lektury$polikarp$lektury$, $lektury$motyw$lektury$, 5, $lektury$rozmowa ze Śmiercią$lektury$, $lektury$lęk i bezradność człowieka wobec śmierci. Mistrz drży i błaga Śmierć, żeby odłożyła kosę, ale ona odmawia. rozmowa ze Śmiercią. Ma kosa wisz, trawę siecze,$lektury$, $lektury${"motyw":"lęk i bezradność człowieka wobec śmierci","przyklad":"Mistrz drży i błaga Śmierć, żeby odłożyła kosę, ale ona odmawia.","miejsce":"rozmowa ze Śmiercią","cytat":"Ma kosa wisz, trawę siecze,"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/rozmowa-mistrza-polikarpa-ze-smiercia/$lektury$),
  ($lektury$polikarp$lektury$, $lektury$motyw$lektury$, 6, $lektury$mowa Śmierci$lektury$, $lektury$krytyka stanów i grzechów. Śmierć wymienia, kogo będzie karać, między innymi karczmarzy, którzy źle nalewają piwo. mowa Śmierci. $lektury$, $lektury${"motyw":"krytyka stanów i grzechów","przyklad":"Śmierć wymienia, kogo będzie karać, między innymi karczmarzy, którzy źle nalewają piwo.","miejsce":"mowa Śmierci"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/rozmowa-mistrza-polikarpa-ze-smiercia/$lektury$),
  ($lektury$polikarp$lektury$, $lektury$motyw$lektury$, 7, $lektury$cały utwór$lektury$, $lektury$alegoria i dialog ze Śmiercią. Utwór ma formę rozmowy mistrza i Śmierci, każdą wypowiedź poprzedzają łacińskie wskazania mówiącego (Mors dicit, Magister dicit). cały utwór. $lektury$, $lektury${"motyw":"alegoria i dialog ze Śmiercią","przyklad":"Utwór ma formę rozmowy mistrza i Śmierci, każdą wypowiedź poprzedzają łacińskie wskazania mówiącego (Mors dicit, Magister dicit).","miejsce":"cały utwór"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/rozmowa-mistrza-polikarpa-ze-smiercia/$lektury$),
