insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$potop$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$t. I, Wstęp$lektury$, $lektury$t. I, Wstęp. Billewiczowie, Wołodyjowski. Laudańszczyzna na Żmudzi. Narrator przedstawia ród Billewiczów z Żmudzi i ich zaścianki oraz wspomina dowódcę laudańskiej chorągwi Herakliusza Billewicza.$lektury$, $lektury${"nr":1,"miejsce":"t. I, Wstęp","kto":["Billewiczowie","Wołodyjowski"],"gdzie":"Laudańszczyzna na Żmudzi","opis":"Narrator przedstawia ród Billewiczów z Żmudzi i ich zaścianki oraz wspomina dowódcę laudańskiej chorągwi Herakliusza Billewicza."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/potop-tom-pierwszy/$lektury$),
  ($lektury$potop$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$t. I, rozdz. I$lektury$, $lektury$t. I, rozdz. I. Aleksandra Billewiczówna, czeladź. dwór w Wodoktach, izba czeladna. Panna Aleksandra (Oleńka) spędza wieczór z czeladzią i dziewczętami dworskimi, według dawnego zwyczaju Billewiczów.$lektury$, $lektury${"nr":2,"miejsce":"t. I, rozdz. I","kto":["Aleksandra Billewiczówna","czeladź"],"gdzie":"dwór w Wodoktach, izba czeladna","opis":"Panna Aleksandra (Oleńka) spędza wieczór z czeladzią i dziewczętami dworskimi, według dawnego zwyczaju Billewiczów."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/potop-tom-pierwszy/$lektury$),
  ($lektury$potop$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$t. I, rozdz. II–IV$lektury$, $lektury$t. I, rozdz. II–IV. Billewiczowie, Olenka, Kmicic. Wodokty, Mitruny. Krewni Oleńki biesiadują i planują wizyty; przybywają goście, którzy dopytują o pana Kmicica, a Oleńka przyjmuje ich i wypytywana milczy o nim.$lektury$, $lektury${"nr":3,"miejsce":"t. I, rozdz. II–IV","kto":["Billewiczowie","Olenka","Kmicic"],"gdzie":"Wodokty, Mitruny","opis":"Krewni Oleńki biesiadują i planują wizyty; przybywają goście, którzy dopytują o pana Kmicica, a Oleńka przyjmuje ich i wypytywana milczy o nim."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/potop-tom-pierwszy/$lektury$),
  ($lektury$potop$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$t. I, rozdz. V–VI$lektury$, $lektury$t. I, rozdz. V–VI. Kmicic, Butrymowie, Oleńka. Butrymy, Wodokty. Kmicic, który zdziczał w ciągłych podjazdach i walkach, najeżdża Butrymów; niedobitki rodu uciekają do Wodoktów, a Oleńka oddaje im Mitruny na schronienie.$lektury$, $lektury${"nr":4,"miejsce":"t. I, rozdz. V–VI","kto":["Kmicic","Butrymowie","Oleńka"],"gdzie":"Butrymy, Wodokty","opis":"Kmicic, który zdziczał w ciągłych podjazdach i walkach, najeżdża Butrymów; niedobitki rodu uciekają do Wodoktów, a Oleńka oddaje im Mitruny na schronienie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/potop-tom-pierwszy/$lektury$),
  ($lektury$potop$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$t. I, rozdz. VII–IX$lektury$, $lektury$t. I, rozdz. VII–IX. Wołodyjowski, Kmicic. Pacunele, dom Kmicica. Pan Wołodyjowski przebywa w Pacunelach u Gasztowta; później odwiedza chorego Kmicica, który z początku blednie na jego widok, ale podaje mu rękę.$lektury$, $lektury${"nr":5,"miejsce":"t. I, rozdz. VII–IX","kto":["Wołodyjowski","Kmicic"],"gdzie":"Pacunele, dom Kmicica","opis":"Pan Wołodyjowski przebywa w Pacunelach u Gasztowta; później odwiedza chorego Kmicica, który z początku blednie na jego widok, ale podaje mu rękę."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/potop-tom-pierwszy/$lektury$),
  ($lektury$potop$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$t. I, rozdz. X$lektury$, $lektury$t. I, rozdz. X. Szlachta, Szwedzi. Litwa. Po wsiach i miastach krąży wieść o zbliżającej się nawałnicy szwedzkiej mimo rozejmu.$lektury$, $lektury${"nr":6,"miejsce":"t. I, rozdz. X","kto":["Szlachta","Szwedzi"],"gdzie":"Litwa","opis":"Po wsiach i miastach krąży wieść o zbliżającej się nawałnicy szwedzkiej mimo rozejmu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/potop-tom-pierwszy/$lektury$),
  ($lektury$potop$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$t. I, rozdz. XI–XIII$lektury$, $lektury$t. I, rozdz. XI–XIII. Kmicic, Radziwiłł, Harasimowicz. Kiejdany, Tykocin. Szlachta pod komendą Radziwiłła szykuje się do wojny; Harasimowicz opowiada, że wozy ze skarbem pójdą do Tykocina, bo kiejdański zamek jest niebezpieczny.$lektury$, $lektury${"nr":7,"miejsce":"t. I, rozdz. XI–XIII","kto":["Kmicic","Radziwiłł","Harasimowicz"],"gdzie":"Kiejdany, Tykocin","opis":"Szlachta pod komendą Radziwiłła szykuje się do wojny; Harasimowicz opowiada, że wozy ze skarbem pójdą do Tykocina, bo kiejdański zamek jest niebezpieczny."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/potop-tom-pierwszy/$lektury$),
  ($lektury$potop$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$t. I, rozdz. XIV–XVIII$lektury$, $lektury$t. I, rozdz. XIV–XVIII. Janusz Radziwiłł, Kmicic, Wołodyjowski, Zagłoba. Litwa, Kiejdany. Radziwiłł każe aresztować opornych pułkowników, a Kmicic wraca ranny i zakrwawiony z węgierską banderią i staje przed hetmanem; Wołodyjowski i inni stają po stronie przeciwnej.$lektury$, $lektury${"nr":8,"miejsce":"t. I, rozdz. XIV–XVIII","kto":["Janusz Radziwiłł","Kmicic","Wołodyjowski","Zagłoba"],"gdzie":"Litwa, Kiejdany","opis":"Radziwiłł każe aresztować opornych pułkowników, a Kmicic wraca ranny i zakrwawiony z węgierską banderią i staje przed hetmanem; Wołodyjowski i inni stają po stronie przeciwnej."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/potop-tom-pierwszy/$lektury$),
