insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$prosze-panstwa-do-gazu$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$początek opowiadania (blok na lagrze)$lektury$, $lektury$początek opowiadania (blok na lagrze). narrator, Henri, marsylczyk. obóz Birkenau, blok, odcinek B II. W upalny dzień więźniowie w obozie chodzą nago po odwszeniu; narrator razem z francuskimi kolegami je na pryczy chleb, boczek i konserwy z paczek, a Henri marzy o winie i obiecuje przynieść coś z rampy.$lektury$, $lektury${"nr":1,"miejsce":"początek opowiadania (blok na lagrze)","kto":["narrator","Henri","marsylczyk"],"gdzie":"obóz Birkenau, blok, odcinek B II","opis":"W upalny dzień więźniowie w obozie chodzą nago po odwszeniu; narrator razem z francuskimi kolegami je na pryczy chleb, boczek i konserwy z paczek, a Henri marzy o winie i obiecuje przynieść coś z rampy."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/borowski-prosze-panstwa-do-gazu/$lektury$),
  ($lektury$prosze-panstwa-do-gazu$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$początek opowiadania (blok na lagrze)$lektury$, $lektury$początek opowiadania (blok na lagrze). narrator, Henri, marsylczyk. blok. Więźniowie spierają się, czy transporty do krematorium ustały, i wymieniają uwagi o paczkach i głodzie wśród innych narodowości; marsylczyk komentuje religię jako opium dla narodu.$lektury$, $lektury${"nr":2,"miejsce":"początek opowiadania (blok na lagrze)","kto":["narrator","Henri","marsylczyk"],"gdzie":"blok","opis":"Więźniowie spierają się, czy transporty do krematorium ustały, i wymieniają uwagi o paczkach i głodzie wśród innych narodowości; marsylczyk komentuje religię jako opium dla narodu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/borowski-prosze-panstwa-do-gazu/$lektury$),
  ($lektury$prosze-panstwa-do-gazu$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$alarm i wymarsz na rampę$lektury$, $lektury$alarm i wymarsz na rampę. narrator, Henri, Kanada. blok, brama obozu. Do bloku wpada wołanie „Kanada, antreten, transport przychodzi”; Henri zabiera narratora do komanda, które rozładowuje transport, a narrator prosi o buty.$lektury$, $lektury${"nr":3,"miejsce":"alarm i wymarsz na rampę","kto":["narrator","Henri","Kanada"],"gdzie":"blok, brama obozu","opis":"Do bloku wpada wołanie „Kanada, antreten, transport przychodzi”; Henri zabiera narratora do komanda, które rozładowuje transport, a narrator prosi o buty."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/borowski-prosze-panstwa-do-gazu/$lektury$),
  ($lektury$prosze-panstwa-do-gazu$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$marsz na rampę$lektury$, $lektury$marsz na rampę. narrator, komando Kanada, posty SS. obóz II B, droga na rampę. Grupa maszeruje szybko pod bramę, gdzie ktoś liczy ich do stu, i przechodzi przez kolejne odcinki obozu między drzewami do rampy.$lektury$, $lektury${"nr":4,"miejsce":"marsz na rampę","kto":["narrator","komando Kanada","posty SS"],"gdzie":"obóz II B, droga na rampę","opis":"Grupa maszeruje szybko pod bramę, gdzie ktoś liczy ich do stu, i przechodzi przez kolejne odcinki obozu między drzewami do rampy."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/borowski-prosze-panstwa-do-gazu/$lektury$),
  ($lektury$prosze-panstwa-do-gazu$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$rampa przed transportem$lektury$, $lektury$rampa przed transportem. narrator, Henri, wartownik SS, Grecy. rampa, zielony plac przy torach. Rampa wygląda sielankowo; więźniowie czekają, esesman żartobliwie handluje z Henrim wodą, a Grecy pytają, co mają robić, i słyszą, że transport idzie do krematorium.$lektury$, $lektury${"nr":5,"miejsce":"rampa przed transportem","kto":["narrator","Henri","wartownik SS","Grecy"],"gdzie":"rampa, zielony plac przy torach","opis":"Rampa wygląda sielankowo; więźniowie czekają, esesman żartobliwie handluje z Henrim wodą, a Grecy pytają, co mają robić, i słyszą, że transport idzie do krematorium."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/borowski-prosze-panstwa-do-gazu/$lektury$),
  ($lektury$prosze-panstwa-do-gazu$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$rozładunek transportu Sosnowiec–Będzin$lektury$, $lektury$rozładunek transportu Sosnowiec–Będzin. narrator, esesmani, przybyli Żydzi. rampa. Do rampy podjeżdża transport; ludzie wysiadają z wagonów pytając, dokąd jadą, rzeczy są zbierane na stos, a esesman z notatnikiem liczy auta odjeżdżające do krematorium.$lektury$, $lektury${"nr":6,"miejsce":"rozładunek transportu Sosnowiec–Będzin","kto":["narrator","esesmani","przybyli Żydzi"],"gdzie":"rampa","opis":"Do rampy podjeżdża transport; ludzie wysiadają z wagonów pytając, dokąd jadą, rzeczy są zbierane na stos, a esesman z notatnikiem liczy auta odjeżdżające do krematorium."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/borowski-prosze-panstwa-do-gazu/$lektury$),
  ($lektury$prosze-panstwa-do-gazu$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$rozładunek transportu$lektury$, $lektury$rozładunek transportu. narrator, Henri. rampa. Narrator wybucha, że kobiety uciekają przed niemowlętami, a potem pyta Henriego, czy są ludźmi dobrymi; Henri odpowiada, że wszystko to jest normalne i przewidziane.$lektury$, $lektury${"nr":7,"miejsce":"rozładunek transportu","kto":["narrator","Henri"],"gdzie":"rampa","opis":"Narrator wybucha, że kobiety uciekają przed niemowlętami, a potem pyta Henriego, czy są ludźmi dobrymi; Henri odpowiada, że wszystko to jest normalne i przewidziane."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/borowski-prosze-panstwa-do-gazu/$lektury$),
  ($lektury$prosze-panstwa-do-gazu$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$scena z kobietą i dzieckiem$lektury$, $lektury$scena z kobietą i dzieckiem. młoda kobieta, dziecko, Andrej, esesman. rampa. Młoda kobieta, chcąc wmieszać się między tych, którzy pójdą pieszo, wypiera się własnego dziecka; Andrej, marynarz z Sewastopola, zbija ją, wrzuca na auto i rzuca jej dziecko pod nogi, a esesman to pochwala.$lektury$, $lektury${"nr":8,"miejsce":"scena z kobietą i dzieckiem","kto":["młoda kobieta","dziecko","Andrej","esesman"],"gdzie":"rampa","opis":"Młoda kobieta, chcąc wmieszać się między tych, którzy pójdą pieszo, wypiera się własnego dziecka; Andrej, marynarz z Sewastopola, zbija ją, wrzuca na auto i rzuca jej dziecko pod nogi, a esesman to pochwala."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/borowski-prosze-panstwa-do-gazu/$lektury$),
  ($lektury$prosze-panstwa-do-gazu$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$scena z dziewczyną$lektury$, $lektury$scena z dziewczyną. narrator, dziewczyna. rampa. Jasnowłosa dziewczyna w letniej bluzce zeskakuje z wagonu i patrzy narratorowi w twarz, czekając na odpowiedź; on milczy, ona dochodzi do własnych wniosków i sama wsiada na ciężarówkę.$lektury$, $lektury${"nr":9,"miejsce":"scena z dziewczyną","kto":["narrator","dziewczyna"],"gdzie":"rampa","opis":"Jasnowłosa dziewczyna w letniej bluzce zeskakuje z wagonu i patrzy narratorowi w twarz, czekając na odpowiedź; on milczy, ona dochodzi do własnych wniosków i sama wsiada na ciężarówkę."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/borowski-prosze-panstwa-do-gazu/$lektury$),
