insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$prolog$lektury$, $lektury$prolog. chór. Werona. Prolog zapowiada, że z dwóch zwaśnionych rodów w Weronie rodzi się dwoje kochanków, których śmierć zakończy wrogość ojców.$lektury$, $lektury${"nr":1,"miejsce":"prolog","kto":["chór"],"gdzie":"Werona","opis":"Prolog zapowiada, że z dwóch zwaśnionych rodów w Weronie rodzi się dwoje kochanków, których śmierć zakończy wrogość ojców."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$akt I, sc. 1$lektury$, $lektury$akt I, sc. 1. Samson, Grzegorz, Abraham, Benwolio, Tybalt, Eskalus. Werona, plac publiczny. Słudzy Kapuletów i Montekich zaczepiają się na placu, Benwolio chce ich rozdzielić, ale Tybalt dołącza do bójki; książę Eskalus grozi śmiercią każdemu, kto jeszcze zakłóci spokój.$lektury$, $lektury${"nr":2,"miejsce":"akt I, sc. 1","kto":["Samson","Grzegorz","Abraham","Benwolio","Tybalt","Eskalus"],"gdzie":"Werona, plac publiczny","opis":"Słudzy Kapuletów i Montekich zaczepiają się na placu, Benwolio chce ich rozdzielić, ale Tybalt dołącza do bójki; książę Eskalus grozi śmiercią każdemu, kto jeszcze zakłóci spokój."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$akt I, sc. 1$lektury$, $lektury$akt I, sc. 1. Benwolio, Monteki, Romeo. Werona. Benwolio opowiada Montekiemu o zajściu, a rodzice martwią się smutkiem Romea, który wzdycha do Rozaliny.$lektury$, $lektury${"nr":3,"miejsce":"akt I, sc. 1","kto":["Benwolio","Monteki","Romeo"],"gdzie":"Werona","opis":"Benwolio opowiada Montekiemu o zajściu, a rodzice martwią się smutkiem Romea, który wzdycha do Rozaliny."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$akt I, sc. 2$lektury$, $lektury$akt I, sc. 2. Kapulet, Parys, Służący. Werona, ulica. Parys prosi Kapuleta o rękę Julii; Kapulet zaprasza go na bal, a służący z listą gości prosi Romea o odczytanie jej.$lektury$, $lektury${"nr":4,"miejsce":"akt I, sc. 2","kto":["Kapulet","Parys","Służący"],"gdzie":"Werona, ulica","opis":"Parys prosi Kapuleta o rękę Julii; Kapulet zaprasza go na bal, a służący z listą gości prosi Romea o odczytanie jej."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$akt I, sc. 2$lektury$, $lektury$akt I, sc. 2. Romeo, Benwolio, Służący. Werona, ulica. Romeo z listy dowiaduje się, że na balu u Kapuletów będzie Rozalina, i postanawia pójść na bal w masce.$lektury$, $lektury${"nr":5,"miejsce":"akt I, sc. 2","kto":["Romeo","Benwolio","Służący"],"gdzie":"Werona, ulica","opis":"Romeo z listy dowiaduje się, że na balu u Kapuletów będzie Rozalina, i postanawia pójść na bal w masce."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$akt I, sc. 3$lektury$, $lektury$akt I, sc. 3. Pani Kapulet, Marta, Julia. dom Kapuletów. Pani Kapulet rozmawia z Julią o małżeństwie z Parysem, a mamka Marta wspomina dzieciństwo Julii, która ma prawie czternaście lat.$lektury$, $lektury${"nr":6,"miejsce":"akt I, sc. 3","kto":["Pani Kapulet","Marta","Julia"],"gdzie":"dom Kapuletów","opis":"Pani Kapulet rozmawia z Julią o małżeństwie z Parysem, a mamka Marta wspomina dzieciństwo Julii, która ma prawie czternaście lat."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$akt I, sc. 4$lektury$, $lektury$akt I, sc. 4. Romeo, Merkucjo, Benwolio. ulica w Weronie. Romeo, Merkucjo i Benwolio w maskach idą na bal; Merkucjo opowiada o królowej Mab, a Romeo ma złe przeczucia.$lektury$, $lektury${"nr":7,"miejsce":"akt I, sc. 4","kto":["Romeo","Merkucjo","Benwolio"],"gdzie":"ulica w Weronie","opis":"Romeo, Merkucjo i Benwolio w maskach idą na bal; Merkucjo opowiada o królowej Mab, a Romeo ma złe przeczucia."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$akt I, sc. 5$lektury$, $lektury$akt I, sc. 5. Romeo, Julia, Tybalt, Kapulet. sala w domu Kapuletów. Na balu Romeo widzi Julię i zakochuje się; Tybalt rozpoznaje go po głosie, ale Kapulet zakazuje mu bójki.$lektury$, $lektury${"nr":8,"miejsce":"akt I, sc. 5","kto":["Romeo","Julia","Tybalt","Kapulet"],"gdzie":"sala w domu Kapuletów","opis":"Na balu Romeo widzi Julię i zakochuje się; Tybalt rozpoznaje go po głosie, ale Kapulet zakazuje mu bójki."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$akt I, sc. 5$lektury$, $lektury$akt I, sc. 5. Romeo, Julia, Marta. sala w domu Kapuletów. Romeo i Julia całują się, a potem oboje dowiadują się od Marty, że są z rodów wrogich.$lektury$, $lektury${"nr":9,"miejsce":"akt I, sc. 5","kto":["Romeo","Julia","Marta"],"gdzie":"sala w domu Kapuletów","opis":"Romeo i Julia całują się, a potem oboje dowiadują się od Marty, że są z rodów wrogich."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$akt II, sc. 1–2$lektury$, $lektury$akt II, sc. 1–2. Romeo, Julia. ogród Kapuletów. Romeo wskakuje do ogrodu i słyszy Julię na balkonie; wyznają sobie miłość, a Julia mówi, że imię nie ma znaczenia, i umawiają się na ślub.$lektury$, $lektury${"nr":10,"miejsce":"akt II, sc. 1–2","kto":["Romeo","Julia"],"gdzie":"ogród Kapuletów","opis":"Romeo wskakuje do ogrodu i słyszy Julię na balkonie; wyznają sobie miłość, a Julia mówi, że imię nie ma znaczenia, i umawiają się na ślub."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 11, $lektury$akt II, sc. 3$lektury$, $lektury$akt II, sc. 3. Romeo, Ojciec Laurenty. cela Ojca Laurentego. Romeo prosi franciszkanina Laurentego o ślub z Julią; Laurenty zgadza się, licząc, że małżeństwo pogodzi oba rody.$lektury$, $lektury${"nr":11,"miejsce":"akt II, sc. 3","kto":["Romeo","Ojciec Laurenty"],"gdzie":"cela Ojca Laurentego","opis":"Romeo prosi franciszkanina Laurentego o ślub z Julią; Laurenty zgadza się, licząc, że małżeństwo pogodzi oba rody."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
  ($lektury$romeo-i-julia$lektury$, $lektury$wydarzenie$lektury$, 12, $lektury$akt II, sc. 4–5$lektury$, $lektury$akt II, sc. 4–5. Marta, Romeo, Julia, Merkucjo, Benwolio. ulica i ogród Kapuletów. Romeo przez Martę przekazuje Julii, by przyszła do celi Laurentego; Julia niecierpliwie czeka na wieści od mamki.$lektury$, $lektury${"nr":12,"miejsce":"akt II, sc. 4–5","kto":["Marta","Romeo","Julia","Merkucjo","Benwolio"],"gdzie":"ulica i ogród Kapuletów","opis":"Romeo przez Martę przekazuje Julii, by przyszła do celi Laurentego; Julia niecierpliwie czeka na wieści od mamki."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/romeo-i-julia/$lektury$),
