insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$początek noweli (opis krajobrazu)$lektury$, $lektury$początek noweli (opis krajobrazu). narrator. płaska, pusta okolica pod Nasielskiem, jesienią po klęsce powstania. Narrator opisuje deszczowy, ponury poranek i pusty, rozmokły krajobraz.$lektury$, $lektury${"nr":1,"miejsce":"początek noweli (opis krajobrazu)","kto":["narrator"],"gdzie":"płaska, pusta okolica pod Nasielskiem, jesienią po klęsce powstania","opis":"Narrator opisuje deszczowy, ponury poranek i pusty, rozmokły krajobraz."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$początek noweli$lektury$, $lektury$początek noweli. Andrzej Borycki (Szymon Winrych). okolice Nasielska, od strony pagórków rajgórskich. Andrzej Borycki, znany jako Szymon Winrych, wiezie wozem broń (karabinki i pałasze) dla oddziału powstańczego; od dwóch nocy nie spał, jest przemoczony i głodny.$lektury$, $lektury${"nr":2,"miejsce":"początek noweli","kto":["Andrzej Borycki (Szymon Winrych)"],"gdzie":"okolice Nasielska, od strony pagórków rajgórskich","opis":"Andrzej Borycki, znany jako Szymon Winrych, wiezie wozem broń (karabinki i pałasze) dla oddziału powstańczego; od dwóch nocy nie spał, jest przemoczony i głodny."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$myśli Winrycha$lektury$, $lektury$myśli Winrycha. Szymon Winrych. okolice Nasielska. Winrych przypomina sobie, że był kiedyś wesołym prezesem warszawskiej konfraterni, a teraz, gdy powstanie upada, jest już prawie sam i zaciekle upiera się przy walce.$lektury$, $lektury${"nr":3,"miejsce":"myśli Winrycha","kto":["Szymon Winrych"],"gdzie":"okolice Nasielska","opis":"Winrych przypomina sobie, że był kiedyś wesołym prezesem warszawskiej konfraterni, a teraz, gdy powstanie upada, jest już prawie sam i zaciekle upiera się przy walce."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$spotkanie z Rosjanami$lektury$, $lektury$spotkanie z Rosjanami. Szymon Winrych, oddział ułanów rosyjskich. okolice Nasielska. Winrych zauważa przez mgłę rosyjskie wojsko, zawraca wóz i ucieka, ale oddział wysyła za nim ośmiu jeźdźców, którzy go doganiają.$lektury$, $lektury${"nr":4,"miejsce":"spotkanie z Rosjanami","kto":["Szymon Winrych","oddział ułanów rosyjskich"],"gdzie":"okolice Nasielska","opis":"Winrych zauważa przez mgłę rosyjskie wojsko, zawraca wóz i ucieka, ale oddział wysyła za nim ośmiu jeźdźców, którzy go doganiają."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$spotkanie z Rosjanami$lektury$, $lektury$spotkanie z Rosjanami. Szymon Winrych, ułani rosyjscy. okolice Nasielska. Ułani znajdują w wozie karabinki, pytają, do czyjej partii wiózł broń, a Winrych odpowiada tylko „Głupiś!”.$lektury$, $lektury${"nr":5,"miejsce":"spotkanie z Rosjanami","kto":["Szymon Winrych","ułani rosyjscy"],"gdzie":"okolice Nasielska","opis":"Ułani znajdują w wozie karabinki, pytają, do czyjej partii wiózł broń, a Winrych odpowiada tylko „Głupiś!”."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$śmierć Winrycha$lektury$, $lektury$śmierć Winrycha. Szymon Winrych, ułani rosyjscy. okolice Nasielska. Ułani przebijają Winrycha lancami; on prosi, by go nie zabijali; trzeci ułan celuje mu w głowę, lecz kula trafia i zabija jednego z koni.$lektury$, $lektury${"nr":6,"miejsce":"śmierć Winrycha","kto":["Szymon Winrych","ułani rosyjscy"],"gdzie":"okolice Nasielska","opis":"Ułani przebijają Winrycha lancami; on prosi, by go nie zabijali; trzeci ułan celuje mu w głowę, lecz kula trafia i zabija jednego z koni."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$śmierć Winrycha$lektury$, $lektury$śmierć Winrycha. Szymon Winrych, ułani rosyjscy. okolice Nasielska. Ułani rewidują kieszenie powstańca i odjeżdżają, biorąc kilka pałaszy, a bronie w wozie zostawiają; Winrych wymawia w deszczu słowa modlitwy „Ojcze nasz” i umiera.$lektury$, $lektury${"nr":7,"miejsce":"śmierć Winrycha","kto":["Szymon Winrych","ułani rosyjscy"],"gdzie":"okolice Nasielska","opis":"Ułani rewidują kieszenie powstańca i odjeżdżają, biorąc kilka pałaszy, a bronie w wozie zostawiają; Winrych wymawia w deszczu słowa modlitwy „Ojcze nasz” i umiera."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$los konia$lektury$, $lektury$los konia. koń Winrycha. okolice Nasielska. Drugi koń z zaprzęgu szamoce się, łamie nogę między szprychami koła i zostaje uwięziony przy wozie.$lektury$, $lektury${"nr":8,"miejsce":"los konia","kto":["koń Winrycha"],"gdzie":"okolice Nasielska","opis":"Drugi koń z zaprzęgu szamoce się, łamie nogę między szprychami koła i zostaje uwięziony przy wozie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$nazajutrz: kruki i wrony$lektury$, $lektury$nazajutrz: kruki i wrony. wrony, koń Winrycha. okolice Nasielska. Nazajutrz nad padliną zlatują się kruki i wrony; ranny koń woła do ludzi, a wrony zaczynają dziobać martwego konia i ciało Winrycha.$lektury$, $lektury${"nr":9,"miejsce":"nazajutrz: kruki i wrony","kto":["wrony","koń Winrycha"],"gdzie":"okolice Nasielska","opis":"Nazajutrz nad padliną zlatują się kruki i wrony; ranny koń woła do ludzi, a wrony zaczynają dziobać martwego konia i ciało Winrycha."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$chłop zabiera łupy$lektury$, $lektury$chłop zabiera łupy. chłop z pobliskiej wsi, wrony. okolice Nasielska. Przybywa chłop z pobliskiej wsi, odpędza wrony, modli się nad zwłokami, a potem zabiera Winrychowi sukmanę, buty i broń z wozu.$lektury$, $lektury${"nr":10,"miejsce":"chłop zabiera łupy","kto":["chłop z pobliskiej wsi","wrony"],"gdzie":"okolice Nasielska","opis":"Przybywa chłop z pobliskiej wsi, odpędza wrony, modli się nad zwłokami, a potem zabiera Winrychowi sukmanę, buty i broń z wozu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 11, $lektury$chłop zabiera łupy$lektury$, $lektury$chłop zabiera łupy. chłop z pobliskiej wsi, koń Winrycha. okolice Nasielska. Chłop wyprzęga ranną szkapę, próbuje ją udusić, ale z obrzydzenia odwiązuje linkę; zdejmuje skórę z konia zabitego przez ułanów, a rannego zostawia, bo nie chce się „paprać”.$lektury$, $lektury${"nr":11,"miejsce":"chłop zabiera łupy","kto":["chłop z pobliskiej wsi","koń Winrycha"],"gdzie":"okolice Nasielska","opis":"Chłop wyprzęga ranną szkapę, próbuje ją udusić, ale z obrzydzenia odwiązuje linkę; zdejmuje skórę z konia zabitego przez ułanów, a rannego zostawia, bo nie chce się „paprać”."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 12, $lektury$pochowanie zwłok$lektury$, $lektury$pochowanie zwłok. chłop z pobliskiej wsi. stare doły kartoflane przy polu. Chłop wrzuca ciało Winrycha i zdartą skórę konia do starego dołu kartoflanego, zasypuje je gliną i wraca do domu, dziękując Bogu za zesłane mu żelastwo i rzemienie.$lektury$, $lektury${"nr":12,"miejsce":"pochowanie zwłok","kto":["chłop z pobliskiej wsi"],"gdzie":"stare doły kartoflane przy polu","opis":"Chłop wrzuca ciało Winrycha i zdartą skórę konia do starego dołu kartoflanego, zasypuje je gliną i wraca do domu, dziękując Bogu za zesłane mu żelastwo i rzemienie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
  ($lektury$rozdziobia-nas-kruki-wrony$lektury$, $lektury$wydarzenie$lektury$, 13, $lektury$zakończenie noweli$lektury$, $lektury$zakończenie noweli. koń Winrycha, wrony. okolice Nasielska, zmierzch. O zmroku słychać rżenie rannego konia, który stoi przy wozie, odwrócony ku grobowi Winrycha, a nad nim krążą wrony; nowela kończy się słowami o nocy, rozpaczy i śmierci.$lektury$, $lektury${"nr":13,"miejsce":"zakończenie noweli","kto":["koń Winrycha","wrony"],"gdzie":"okolice Nasielska, zmierzch","opis":"O zmroku słychać rżenie rannego konia, który stoi przy wozie, odwrócony ku grobowi Winrycha, a nad nim krążą wrony; nowela kończy się słowami o nocy, rozpaczy i śmierci."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/zeromski-rozdziobia-nas-kruki-wrony/$lektury$),
