insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$testament-moj$lektury$, $lektury$motyw$lektury$, 1, $lektury$Testament mój, strofa III$lektury$, $lektury$misja poety i służba ojczyźnie. Mówiący prosi, by powiedzieć, że oddał ojczyźnie młode lata; siedział na maszcie, gdy okręt walczył, i poszedł pod wodę, gdy okręt tonął. Testament mój, strofa III. A póki okręt walczył, siedziałem na maszcie$lektury$, $lektury${"motyw":"misja poety i służba ojczyźnie","przyklad":"Mówiący prosi, by powiedzieć, że oddał ojczyźnie młode lata; siedział na maszcie, gdy okręt walczył, i poszedł pod wodę, gdy okręt tonął.","miejsce":"Testament mój, strofa III","cytat":"A póki okręt walczył, siedziałem na maszcie"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/testament-moj/$lektury$),
  ($lektury$testament-moj$lektury$, $lektury$motyw$lektury$, 2, $lektury$Testament mój, strofa II$lektury$, $lektury$odejście i samotność twórcy. Mówiący mówi, że nie zostawił dziedzica dla swojej lutni ani imienia, a jego imię przejdzie jak błyskawica. Testament mój, strofa II. $lektury$, $lektury${"motyw":"odejście i samotność twórcy","przyklad":"Mówiący mówi, że nie zostawił dziedzica dla swojej lutni ani imienia, a jego imię przejdzie jak błyskawica.","miejsce":"Testament mój, strofa II"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/testament-moj/$lektury$),
  ($lektury$testament-moj$lektury$, $lektury$motyw$lektury$, 3, $lektury$Testament mój, strofa VII$lektury$, $lektury$testament duchowy i apel do żywych. Żywi mają nie tracić nadziei, nieść oświatę i ginąć, gdy trzeba, jak kamienie rzucane na szaniec. Testament mój, strofa VII. I przed narodem niosą oświaty kaganiec$lektury$, $lektury${"motyw":"testament duchowy i apel do żywych","przyklad":"Żywi mają nie tracić nadziei, nieść oświatę i ginąć, gdy trzeba, jak kamienie rzucane na szaniec.","miejsce":"Testament mój, strofa VII","cytat":"I przed narodem niosą oświaty kaganiec"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/testament-moj/$lektury$),
  ($lektury$testament-moj$lektury$, $lektury$motyw$lektury$, 4, $lektury$Testament mój, strofa I$lektury$, $lektury$wspólnota z towarzyszami. Pierwszy wers wspomina wspólne życie, cierpienia i łzy z odbiorcami. Testament mój, strofa I. Żyłem z wami, cierpiałem i płakałem z wami$lektury$, $lektury${"motyw":"wspólnota z towarzyszami","przyklad":"Pierwszy wers wspomina wspólne życie, cierpienia i łzy z odbiorcami.","miejsce":"Testament mój, strofa I","cytat":"Żyłem z wami, cierpiałem i płakałem z wami"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/testament-moj/$lektury$),
  ($lektury$testament-moj$lektury$, $lektury$motyw$lektury$, 5, $lektury$Testament mój, strofa X$lektury$, $lektury$siła, która trwa po śmierci. Ostatnia strofa mówi o „sile fatalnej”, która po śmierci poety będzie „gniotła” żywych, aż zmieni ich w aniołów; można odczytać to jako wiarę w trwały wpływ poezji. Testament mój, strofa X. $lektury$, $lektury${"motyw":"siła, która trwa po śmierci","przyklad":"Ostatnia strofa mówi o „sile fatalnej”, która po śmierci poety będzie „gniotła” żywych, aż zmieni ich w aniołów; można odczytać to jako wiarę w trwały wpływ poezji.","miejsce":"Testament mój, strofa X"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/testament-moj/$lektury$),
  ($lektury$testament-moj$lektury$, $lektury$utwor$lektury$, 1, $lektury$całość$lektury$, $lektury$Testament mój. Wiersz-pożegnanie Juliusza Słowackiego, w którym mówiący żegna się z towarzyszami, mówi o służbie dla ojczyzny, o samotności poety i pozostawia nakaz nadziei i oświaty. Używa obrazów okrętu, maszcie i kamieni rzuconych na szaniec.$lektury$, $lektury${"tytul":"Testament mój","miejsce":"całość","opis":"Wiersz-pożegnanie Juliusza Słowackiego, w którym mówiący żegna się z towarzyszami, mówi o służbie dla ojczyzny, o samotności poety i pozostawia nakaz nadziei i oświaty. Używa obrazów okrętu, maszcie i kamieni rzuconych na szaniec."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/testament-moj/$lektury$),
  ($lektury$testament-moj$lektury$, $lektury$utwor$lektury$, 2, $lektury$wybrany drugi wiersz (przykład z podstawy)$lektury$, $lektury$Smutno mi, Boże. Wiersz o samotności i tęsknocie osoby mówiącej, która czuje się obca na obczyźnie. Tekstu tego wiersza nie sprawdzano w tej sesji, bo Wolne Lektury w danych katalogu wskazują wyłącznie „Testament mój”.$lektury$, $lektury${"tytul":"Smutno mi, Boże","miejsce":"wybrany drugi wiersz (przykład z podstawy)","opis":"Wiersz o samotności i tęsknocie osoby mówiącej, która czuje się obca na obczyźnie. Tekstu tego wiersza nie sprawdzano w tej sesji, bo Wolne Lektury w danych katalogu wskazują wyłącznie „Testament mój”."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/testament-moj/$lektury$),
  ($lektury$testament-moj$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pełny tekst Testamentu mego; cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/testament-moj/","rodzaj":"utwór","co":"Pełny tekst Testamentu mego; cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/testament-moj/$lektury$),
  ($lektury$testament-moj$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$„Smutno mi, Boże” — tekstu i faktów (data, miejsce, adresat) nie sprawdzano w tej sesji; katalog wymienia go tylko jako przykład drugiego wiersza.$lektury$, $lektury${"tekst":"„Smutno mi, Boże” — tekstu i faktów (data, miejsce, adresat) nie sprawdzano w tej sesji; katalog wymienia go tylko jako przykład drugiego wiersza."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/testament-moj/$lektury$),
  ($lektury$testament-moj$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Numeracja strof robocza (od początku tekstu w Wolnych Lekturach).$lektury$, $lektury${"tekst":"Numeracja strof robocza (od początku tekstu w Wolnych Lekturach)."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/testament-moj/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$traktat-moralny$lektury$, $lektury$motyw$lektury$, 1, $lektury$Traktat moralny$lektury$, $lektury$odpowiedzialność twórcy i inteligencji. Poemat zwraca się do twórców i inteligencji żyjących w czasie powojennym. Traktat moralny. $lektury$, $lektury${"motyw":"odpowiedzialność twórcy i inteligencji","przyklad":"Poemat zwraca się do twórców i inteligencji żyjących w czasie powojennym.","miejsce":"Traktat moralny"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LP491JJ1BM/431/a/dowiedz-sie/D2JLVBXM7$lektury$),
  ($lektury$traktat-moralny$lektury$, $lektury$motyw$lektury$, 2, $lektury$Traktat moralny$lektury$, $lektury$moralność w czasach niemoralnych. Lekcja ZPE o „moralności w czasach niemoralnych” wskazuje, że utwór jest rozmową o etyce wobec systemu totalitarnego. Traktat moralny. $lektury$, $lektury${"motyw":"moralność w czasach niemoralnych","przyklad":"Lekcja ZPE o „moralności w czasach niemoralnych” wskazuje, że utwór jest rozmową o etyce wobec systemu totalitarnego.","miejsce":"Traktat moralny"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LP491JJ1BM/431/a/dowiedz-sie/D2JLVBXM7$lektury$),
  ($lektury$traktat-moralny$lektury$, $lektury$motyw$lektury$, 3, $lektury$Traktat moralny$lektury$, $lektury$dystans wobec systemów opartych na przemocy. Poeta obserwował z dystansu system komunistyczny i dostrzegał jego podobieństwo do innych systemów terroru. Traktat moralny. $lektury$, $lektury${"motyw":"dystans wobec systemów opartych na przemocy","przyklad":"Poeta obserwował z dystansu system komunistyczny i dostrzegał jego podobieństwo do innych systemów terroru.","miejsce":"Traktat moralny"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LP491JJ1BM/431/a/dowiedz-sie/D2JLVBXM7$lektury$),
  ($lektury$traktat-moralny$lektury$, $lektury$utwor$lektury$, 1, $lektury$poemat, USA, 1947$lektury$, $lektury$Traktat moralny (fragmenty). Poemat Czesława Miłosza napisany w 1947 r. w Stanach Zjednoczonych i opublikowany w „Twórczości”. Zwraca się do twórców, inteligencji i wszystkich ludzi żyjących w czasie powojennym; autor z dystansu obserwował system komunistyczny w Polsce i dostrzegał jego bliskość do innych systemów opartych na braku wolności i terrorze (według ZPE).$lektury$, $lektury${"tytul":"Traktat moralny (fragmenty)","miejsce":"poemat, USA, 1947","opis":"Poemat Czesława Miłosza napisany w 1947 r. w Stanach Zjednoczonych i opublikowany w „Twórczości”. Zwraca się do twórców, inteligencji i wszystkich ludzi żyjących w czasie powojennym; autor z dystansu obserwował system komunistyczny w Polsce i dostrzegał jego bliskość do innych systemów opartych na braku wolności i terrorze (według ZPE)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LP491JJ1BM/431/a/dowiedz-sie/D2JLVBXM7$lektury$),
  ($lektury$traktat-moralny$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Materiał ZPE „O moralności w czasach niemoralnych – Traktat moralny Czesława Miłosza”: okoliczności powstania.$lektury$, $lektury${"url":"https://zpe.gov.pl/watek/LP491JJ1BM/431/a/dowiedz-sie/D2JLVBXM7","rodzaj":"opracowanie","co":"Materiał ZPE „O moralności w czasach niemoralnych – Traktat moralny Czesława Miłosza”: okoliczności powstania."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LP491JJ1BM/431/a/dowiedz-sie/D2JLVBXM7$lektury$),
  ($lektury$traktat-moralny$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Ćwiczenia ZPE do Traktatu moralnego (fragmenty z zadaniami; widoczne w wynikach wyszukiwania).$lektury$, $lektury${"url":"https://zpe.gov.pl/watek/LP491JJ1BM/431/a/cwiczenia/D1HLNV3QC","rodzaj":"opracowanie","co":"Ćwiczenia ZPE do Traktatu moralnego (fragmenty z zadaniami; widoczne w wynikach wyszukiwania)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LP491JJ1BM/431/a/cwiczenia/D1HLNV3QC$lektury$),
  ($lektury$traktat-moralny$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Utwory autora są chronione prawem autorskim (zmarł w 2004 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury).$lektury$, $lektury${"tekst":"Utwory autora są chronione prawem autorskim (zmarł w 2004 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LP491JJ1BM/431/a/dowiedz-sie/D2JLVBXM7$lektury$),
  ($lektury$traktat-moralny$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Podstawa wymienia fragmenty bez zamkniętego wykazu miejsc; nie ustalono, które części wymaga CKE (np. fragmenty z ćwiczeń ZPE).$lektury$, $lektury${"tekst":"Podstawa wymienia fragmenty bez zamkniętego wykazu miejsc; nie ustalono, które części wymaga CKE (np. fragmenty z ćwiczeń ZPE)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LP491JJ1BM/431/a/dowiedz-sie/D2JLVBXM7$lektury$),
  ($lektury$traktat-moralny$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Opis okoliczności powstania z podsumowania wyników wyszukiwania; treść nie była czytana.$lektury$, $lektury${"tekst":"Opis okoliczności powstania z podsumowania wyników wyszukiwania; treść nie była czytana."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LP491JJ1BM/431/a/dowiedz-sie/D2JLVBXM7$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$treny$lektury$, $lektury$motyw$lektury$, 1, $lektury$Tren VII; Tren VIII$lektury$, $lektury$żałoba po stracie dziecka. Poeta po śmierci córki Orszulki opisuje pustkę w domu i rzeczy po dziecku, które przypominają o jej śmierci. Tren VII; Tren VIII. Wielkieś mi uczyniła pustki w domu moim,$lektury$, $lektury${"motyw":"żałoba po stracie dziecka","przyklad":"Poeta po śmierci córki Orszulki opisuje pustkę w domu i rzeczy po dziecku, które przypominają o jej śmierci.","miejsce":"Tren VII; Tren VIII","cytat":"Wielkieś mi uczyniła pustki w domu moim,"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$motyw$lektury$, 2, $lektury$Tren X$lektury$, $lektury$rozpacz i pytanie o los zmarłej. Poeta pyta córkę, gdzie jest, i prosi, by pojawiła się choćby we śnie lub jako cień. Tren X. Orszulo moja wdzięczna, gdzieś mi sie podziała?$lektury$, $lektury${"motyw":"rozpacz i pytanie o los zmarłej","przyklad":"Poeta pyta córkę, gdzie jest, i prosi, by pojawiła się choćby we śnie lub jako cień.","miejsce":"Tren X","cytat":"Orszulo moja wdzięczna, gdzieś mi sie podziała?"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$motyw$lektury$, 3, $lektury$Tren IX$lektury$, $lektury$kryzys wiary w mądrość stoicką. Poeta wymienia, co obiecuje mądrość stoicka, i przyznaje, że sam został z niej wytrącony. Tren IX. Kupić by cię, mądrości, za drogie pieniądze,$lektury$, $lektury${"motyw":"kryzys wiary w mądrość stoicką","przyklad":"Poeta wymienia, co obiecuje mądrość stoicka, i przyznaje, że sam został z niej wytrącony.","miejsce":"Tren IX","cytat":"Kupić by cię, mądrości, za drogie pieniądze,"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$motyw$lektury$, 4, $lektury$Tren XI$lektury$, $lektury$niemoc rozumu i cnoty. Powtarzając słowa Brutusa, poeta uznaje cnotę za „fraszkę”, bo nie chroni przed nieszczęściem. Tren XI. «Fraszka cnota», powiedział Brutus porażony.$lektury$, $lektury${"motyw":"niemoc rozumu i cnoty","przyklad":"Powtarzając słowa Brutusa, poeta uznaje cnotę za „fraszkę”, bo nie chroni przed nieszczęściem.","miejsce":"Tren XI","cytat":"«Fraszka cnota», powiedział Brutus porażony."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$motyw$lektury$, 5, $lektury$Tren V$lektury$, $lektury$śmierć przedwczesna jak ścięta roślina. Orszulka porównana do młodej oliwki podciętej przez sadownika. Tren V. Jako oliwka mała pod wysokim sadem$lektury$, $lektury${"motyw":"śmierć przedwczesna jak ścięta roślina","przyklad":"Orszulka porównana do młodej oliwki podciętej przez sadownika.","miejsce":"Tren V","cytat":"Jako oliwka mała pod wysokim sadem"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$motyw$lektury$, 6, $lektury$Tren XIX$lektury$, $lektury$sen i pocieszenie. We śnie matka poety przychodzi z Orszulką i tłumaczy, że dziecko jest szczęśliwe w niebie; poeta odzyskuje wewnętrzny spokój. Tren XIX. Żałość moja długo w noc oczu mi nie dała$lektury$, $lektury${"motyw":"sen i pocieszenie","przyklad":"We śnie matka poety przychodzi z Orszulką i tłumaczy, że dziecko jest szczęśliwe w niebie; poeta odzyskuje wewnętrzny spokój.","miejsce":"Tren XIX","cytat":"Żałość moja długo w noc oczu mi nie dała"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$motyw$lektury$, 7, $lektury$Tren V; Tren X$lektury$, $lektury$łączenie wątków antycznych i chrześcijańskich. W Trenie X obok nieba i czyśćca pojawiają się Charon i Wyspy Szczęśliwe; w Trenie V — Persefona. Tren V; Tren X. $lektury$, $lektury${"motyw":"łączenie wątków antycznych i chrześcijańskich","przyklad":"W Trenie X obok nieba i czyśćca pojawiają się Charon i Wyspy Szczęśliwe; w Trenie V — Persefona.","miejsce":"Tren V; Tren X"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$utwor$lektury$, 1, $lektury$Treny, V$lektury$, $lektury$Tren V. Obraz małej Orszulki jako młodej oliwki pod wysokim sadem: sadownik przycina ją, a ona mdleje i pada u stóp matki. Poeta porównuje do niej córkę, którą śmierć ścięła przed oczami rodziców. Pojawia się wezwanie do Persefony, boginii zmarłych.$lektury$, $lektury${"tytul":"Tren V","miejsce":"Treny, V","opis":"Obraz małej Orszulki jako młodej oliwki pod wysokim sadem: sadownik przycina ją, a ona mdleje i pada u stóp matki. Poeta porównuje do niej córkę, którą śmierć ścięła przed oczami rodziców. Pojawia się wezwanie do Persefony, boginii zmarłych."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$utwor$lektury$, 2, $lektury$Treny, VII$lektury$, $lektury$Tren VII. Poeta patrzy na ubiory, pasek i inne rzeczy po zmarłej córce. Mówi, że nie jest już nadziei, a matczyne dary „płone”. Ubogi wiano zastępuje dla niej grób.$lektury$, $lektury${"tytul":"Tren VII","miejsce":"Treny, VII","opis":"Poeta patrzy na ubiory, pasek i inne rzeczy po zmarłej córce. Mówi, że nie jest już nadziei, a matczyne dary „płone”. Ubogi wiano zastępuje dla niej grób."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$utwor$lektury$, 3, $lektury$Treny, VIII$lektury$, $lektury$Tren VIII. Opis pustki w domu po śmierci Orszulki. Dziecko wypełniało dom głosem i śmiechem, a po jego odejściu „pełno nas, a jakoby nikogo nie było”. Ton jest osobisty i prosty.$lektury$, $lektury${"tytul":"Tren VIII","miejsce":"Treny, VIII","opis":"Opis pustki w domu po śmierci Orszulki. Dziecko wypełniało dom głosem i śmiechem, a po jego odejściu „pełno nas, a jakoby nikogo nie było”. Ton jest osobisty i prosty."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$utwor$lektury$, 4, $lektury$Treny, IX (wymagany w podstawie)$lektury$, $lektury$Tren IX. Zwrot do mądrości (stoickiej), którą poeta chciałby kupić za drogie pieniądze. Przypisuje jej, że uczy obojętności wobec szczęścia i śmierci, po czym przyznaje, że sam zrzucony „z stopniów ostatnich” nie umie z niej skorzystać. Można odczytać jako rozczarowanie stoicyzmem.$lektury$, $lektury${"tytul":"Tren IX","miejsce":"Treny, IX (wymagany w podstawie)","opis":"Zwrot do mądrości (stoickiej), którą poeta chciałby kupić za drogie pieniądze. Przypisuje jej, że uczy obojętności wobec szczęścia i śmierci, po czym przyznaje, że sam zrzucony „z stopniów ostatnich” nie umie z niej skorzystać. Można odczytać jako rozczarowanie stoicyzmem."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$utwor$lektury$, 5, $lektury$Treny, X (wymagany w podstawie)$lektury$, $lektury$Tren X. Poeta pyta córkę, gdzie jest: czy w niebie, w raju, na Wyspach Szczęśliwych, czy w czyśćcu. Prosi, by przybyła choćby we śnie lub jako cień. Obraz odwołuje się jednocześnie do wyobrażeń chrześcijańskich i antycznych.$lektury$, $lektury${"tytul":"Tren X","miejsce":"Treny, X (wymagany w podstawie)","opis":"Poeta pyta córkę, gdzie jest: czy w niebie, w raju, na Wyspach Szczęśliwych, czy w czyśćcu. Prosi, by przybyła choćby we śnie lub jako cień. Obraz odwołuje się jednocześnie do wyobrażeń chrześcijańskich i antycznych."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$utwor$lektury$, 6, $lektury$Treny, XI (wymagany w podstawie)$lektury$, $lektury$Tren XI. Rozważanie o cnocie jako „fraszce” (słowa Brutusa) i o niemocy ludzkiego rozumu. Poeta pyta, kogo uratowała pobożność, i kończy lękiem, że straci „pociechę” i „baczenie”. Zwykle czytany jako punkt kulminacyjny kryzysu poety.$lektury$, $lektury${"tytul":"Tren XI","miejsce":"Treny, XI (wymagany w podstawie)","opis":"Rozważanie o cnocie jako „fraszce” (słowa Brutusa) i o niemocy ludzkiego rozumu. Poeta pyta, kogo uratowała pobożność, i kończy lękiem, że straci „pociechę” i „baczenie”. Zwykle czytany jako punkt kulminacyjny kryzysu poety."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$utwor$lektury$, 7, $lektury$Treny, XIX$lektury$, $lektury$Tren XIX albo Sen. We śnie poeta widzi matkę z maleńką Orszulką na ręku. Matka pociesza go, że dziecko jest w niebie i nie zaznało cierpień życia. Ten tren zamyka cykl i przynosi pocieszenie.$lektury$, $lektury${"tytul":"Tren XIX albo Sen","miejsce":"Treny, XIX","opis":"We śnie poeta widzi matkę z maleńką Orszulką na ręku. Matka pociesza go, że dziecko jest w niebie i nie zaznało cierpień życia. Ten tren zamyka cykl i przynosi pocieszenie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Wykaz trenów i podział utworu; potwierdzenie, że to cykl 19 trenów.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/treny/","rodzaj":"utwór","co":"Wykaz trenów i podział utworu; potwierdzenie, że to cykl 19 trenów."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Tekst Trenu IX.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/treny-tren-ix/","rodzaj":"utwór","co":"Tekst Trenu IX."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny-tren-ix/$lektury$),
  ($lektury$treny$lektury$, $lektury$zrodlo$lektury$, 3, $lektury$$lektury$, $lektury$Tekst Trenu X.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/treny-tren-x/","rodzaj":"utwór","co":"Tekst Trenu X."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny-tren-x/$lektury$),
