  ($lektury$treny$lektury$, $lektury$zrodlo$lektury$, 5, $lektury$$lektury$, $lektury$Tekst Trenu V.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/treny-tren-v/","rodzaj":"utwór","co":"Tekst Trenu V."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny-tren-v/$lektury$),
  ($lektury$treny$lektury$, $lektury$zrodlo$lektury$, 6, $lektury$$lektury$, $lektury$Tekst Trenu VII.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/treny-tren-vii/","rodzaj":"utwór","co":"Tekst Trenu VII."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny-tren-vii/$lektury$),
