  ($lektury$treny$lektury$, $lektury$zrodlo$lektury$, 8, $lektury$$lektury$, $lektury$Tekst Trenu XIX albo Snu (czytany wyrywkowo).$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/treny-tren-xix-albo-sen/","rodzaj":"utwór","co":"Tekst Trenu XIX albo Snu (czytany wyrywkowo)."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny-tren-xix-albo-sen/$lektury$),
  ($lektury$treny$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Okoliczności biograficzne (śmierć Orszulki, data, wiek dziecka) nie zostały sprawdzone w źródle w tej sesji — do weryfikacji w opracowaniu.$lektury$, $lektury${"tekst":"Okoliczności biograficzne (śmierć Orszulki, data, wiek dziecka) nie zostały sprawdzone w źródle w tej sesji — do weryfikacji w opracowaniu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Podstawowy zakres Trenów: IX, X, XI (wg katalogu); inne treny są opisane dodatkowo. Treny I–IV, VI, XII–XVIII nie zostały opracowane.$lektury$, $lektury${"tekst":"Podstawowy zakres Trenów: IX, X, XI (wg katalogu); inne treny są opisane dodatkowo. Treny I–IV, VI, XII–XVIII nie zostały opracowane."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$),
  ($lektury$treny$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Pisownia Wolnych Lektur zachowuje staropolskie formy (np. „sie”, „szcześliwy”); cytaty dosłowne z tego wydania.$lektury$, $lektury${"tekst":"Pisownia Wolnych Lektur zachowuje staropolskie formy (np. „sie”, „szcześliwy”); cytaty dosłowne z tego wydania."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/treny/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wesele$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$akt I, sc. 1$lektury$, $lektury$akt I, sc. 1. Czepiec, Dziennikarz. izba weselna w Bronowicach. Czepiec rozmawia z Dziennikarzem o polityce; ich dialog pokazuje różnice między wsią a gośćmi z miasta.$lektury$, $lektury${"nr":1,"miejsce":"akt I, sc. 1","kto":["Czepiec","Dziennikarz"],"gdzie":"izba weselna w Bronowicach","opis":"Czepiec rozmawia z Dziennikarzem o polityce; ich dialog pokazuje różnice między wsią a gośćmi z miasta."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$akt I, sc. 2–4$lektury$, $lektury$akt I, sc. 2–4. Dziennikarz, Zosia, Radczyni, Haneczka, Klimina. izba weselna. Goście z miasta rozmawiają z wiejskimi uczestnikami wesela, a Klimina wchodzi, witając państwa.$lektury$, $lektury${"nr":2,"miejsce":"akt I, sc. 2–4","kto":["Dziennikarz","Zosia","Radczyni","Haneczka","Klimina"],"gdzie":"izba weselna","opis":"Goście z miasta rozmawiają z wiejskimi uczestnikami wesela, a Klimina wchodzi, witając państwa."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$akt I, sc. 8–9$lektury$, $lektury$akt I, sc. 8–9. Ksiądz, Pan Młody, Panna Młoda. izba weselna. Ksiądz rozmawia z państwem młodymi; Pan Młody (z miasta) i Panna Młoda (ze wsi) rozmawiają o swoim ślubie.$lektury$, $lektury${"nr":3,"miejsce":"akt I, sc. 8–9","kto":["Ksiądz","Pan Młody","Panna Młoda"],"gdzie":"izba weselna","opis":"Ksiądz rozmawia z państwem młodymi; Pan Młody (z miasta) i Panna Młoda (ze wsi) rozmawiają o swoim ślubie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$akt I, sc. 10$lektury$, $lektury$akt I, sc. 10. Poeta, Maryna. izba weselna. Poeta flirtuje z Maryną.$lektury$, $lektury${"nr":4,"miejsce":"akt I, sc. 10","kto":["Poeta","Maryna"],"gdzie":"izba weselna","opis":"Poeta flirtuje z Maryną."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$akt I, sc. 17–21$lektury$, $lektury$akt I, sc. 17–21. Pan Młody, Żyd, Rachel, Poeta. izba weselna. Pan Młody rozmawia z Żydem, pojawia się Rachel, a w dalszych scenach rozmawia z nią Poeta.$lektury$, $lektury${"nr":5,"miejsce":"akt I, sc. 17–21","kto":["Pan Młody","Żyd","Rachel","Poeta"],"gdzie":"izba weselna","opis":"Pan Młody rozmawia z Żydem, pojawia się Rachel, a w dalszych scenach rozmawia z nią Poeta."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$akt I, sc. 24–25$lektury$, $lektury$akt I, sc. 24–25. Poeta, Gospodarz, Czepiec, Ojciec. izba weselna. Poeta opowiada Gospodarzowi, jaki dramat snuje, a Czepiec dołącza do rozmowy.$lektury$, $lektury${"nr":6,"miejsce":"akt I, sc. 24–25","kto":["Poeta","Gospodarz","Czepiec","Ojciec"],"gdzie":"izba weselna","opis":"Poeta opowiada Gospodarzowi, jaki dramat snuje, a Czepiec dołącza do rozmowy."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$akt I, sc. 28–29$lektury$, $lektury$akt I, sc. 28–29. Żyd, Ksiądz, Czepiec. izba weselna. Ksiądz rozmawia z arendarzem, a do rozmowy włącza się Czepiec.$lektury$, $lektury${"nr":7,"miejsce":"akt I, sc. 28–29","kto":["Żyd","Ksiądz","Czepiec"],"gdzie":"izba weselna","opis":"Ksiądz rozmawia z arendarzem, a do rozmowy włącza się Czepiec."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$akt I, sc. 36–38$lektury$, $lektury$akt I, sc. 36–38. Poeta, Rachel, Panna Młoda, Pan Młody. izba weselna. Poeta rozmawia z Rachel, a potem z Panną Młodą i Panem Młodym; w tych rozmowach pada wątek chochoła.$lektury$, $lektury${"nr":8,"miejsce":"akt I, sc. 36–38","kto":["Poeta","Rachel","Panna Młoda","Pan Młody"],"gdzie":"izba weselna","opis":"Poeta rozmawia z Rachel, a potem z Panną Młodą i Panem Młodym; w tych rozmowach pada wątek chochoła."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$akt II, sc. 1–3$lektury$, $lektury$akt II, sc. 1–3. Gospodyni, Isia, Klimina, Chochoł. izba weselna, noc. Gospodyni układa dzieci do snu; Chochoł pojawia się Isi i odpowiada na jej pytania.$lektury$, $lektury${"nr":9,"miejsce":"akt II, sc. 1–3","kto":["Gospodyni","Isia","Klimina","Chochoł"],"gdzie":"izba weselna, noc","opis":"Gospodyni układa dzieci do snu; Chochoł pojawia się Isi i odpowiada na jej pytania."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$akt II, sc. 4–6$lektury$, $lektury$akt II, sc. 4–6. Marysia, Wojtek, Widmo. izba weselna. Marysia rozmawia z Wojtkiem, po czym zjawia się Widmo, które mówi jej o dawnym zamiarze ślubu.$lektury$, $lektury${"nr":10,"miejsce":"akt II, sc. 4–6","kto":["Marysia","Wojtek","Widmo"],"gdzie":"izba weselna","opis":"Marysia rozmawia z Wojtkiem, po czym zjawia się Widmo, które mówi jej o dawnym zamiarze ślubu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
