  ($lektury$wesele$lektury$, $lektury$postac$lektury$, 17, $lektury$akt I, sc. 8$lektury$, $lektury$Ksiądz. Ksiądz, Księdza, Księdzu, Księdzem. duchowny na weselu rozmawia z państwem młodymi i arendarzem akt I, sc. 8; akt I, sc. 28$lektury$, $lektury${"imie":"Ksiądz","odmiany":["Ksiądz","Księdza","Księdzu","Księdzem"],"rola":"duchowny na weselu","relacje":"rozmawia z państwem młodymi i arendarzem","miejsca":["akt I, sc. 8","akt I, sc. 28"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$motyw$lektury$, 1, $lektury$akt III, sc. 37$lektury$, $lektury$chocholi taniec i niemoc narodu. Na końcu gości, znieruchomiałych ze strachu, Chochoł pobudza do tańca, który zastępuje działanie. akt III, sc. 37. Ostał ci sie ino sznur.$lektury$, $lektury${"motyw":"chocholi taniec i niemoc narodu","przyklad":"Na końcu gości, znieruchomiałych ze strachu, Chochoł pobudza do tańca, który zastępuje działanie.","miejsce":"akt III, sc. 37","cytat":"Ostał ci sie ino sznur."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$motyw$lektury$, 2, $lektury$akt III, sc. 35$lektury$, $lektury$zmarnowana szansa i zgubiony róg. Jasiek, któremu powierzono złoty róg, gubi go i zostaje mu tylko sznur; powstanie się nie zaczyna. akt III, sc. 35. Miałeś, chłopie, złoty róg,$lektury$, $lektury${"motyw":"zmarnowana szansa i zgubiony róg","przyklad":"Jasiek, któremu powierzono złoty róg, gubi go i zostaje mu tylko sznur; powstanie się nie zaczyna.","miejsce":"akt III, sc. 35","cytat":"Miałeś, chłopie, złoty róg,"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$motyw$lektury$, 3, $lektury$akt II, sc. 24$lektury$, $lektury$wizja Wernyhory. Wernyhora przekazuje Gospodarzowi złoty róg i zadanie zwołania ludzi na znak. akt II, sc. 24. Daję Waści złoty róg.$lektury$, $lektury${"motyw":"wizja Wernyhory","przyklad":"Wernyhora przekazuje Gospodarzowi złoty róg i zadanie zwołania ludzi na znak.","miejsce":"akt II, sc. 24","cytat":"Daję Waści złoty róg."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$motyw$lektury$, 4, $lektury$akt I, sc. 1; akt I, sc. 9$lektury$, $lektury$spotkanie inteligencji z chłopami. Pan Młody z miasta żeni się z chłopką, a goście z miasta rozmawiają z Czepcem i innymi o polityce i różnicach klasowych. akt I, sc. 1; akt I, sc. 9. $lektury$, $lektury${"motyw":"spotkanie inteligencji z chłopami","przyklad":"Pan Młody z miasta żeni się z chłopką, a goście z miasta rozmawiają z Czepcem i innymi o polityce i różnicach klasowych.","miejsce":"akt I, sc. 1; akt I, sc. 9"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$motyw$lektury$, 5, $lektury$akt II, sc. 7–15$lektury$, $lektury$zjawy z przeszłości i pamięć narodowa. Przed gośćmi pojawiają się Stańczyk, Rycerz Czarny, Hetman i Upiór, każdy zwraca się do wybranego uczestnika wesela. akt II, sc. 7–15. $lektury$, $lektury${"motyw":"zjawy z przeszłości i pamięć narodowa","przyklad":"Przed gośćmi pojawiają się Stańczyk, Rycerz Czarny, Hetman i Upiór, każdy zwraca się do wybranego uczestnika wesela.","miejsce":"akt II, sc. 7–15"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$motyw$lektury$, 6, $lektury$akt I, sc. 24; akt III, sc. 6$lektury$, $lektury$poezja i sztuka wobec rzeczywistości. Poeta snuje dramat, rozmawia z Rachel i Gospodarzem o twórczości, a potem jest świadkiem wydarzeń. akt I, sc. 24; akt III, sc. 6. $lektury$, $lektury${"motyw":"poezja i sztuka wobec rzeczywistości","przyklad":"Poeta snuje dramat, rozmawia z Rachel i Gospodarzem o twórczości, a potem jest świadkiem wydarzeń.","miejsce":"akt I, sc. 24; akt III, sc. 6"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$motyw$lektury$, 7, $lektury$akt I, sc. 28–29$lektury$, $lektury$stereotypy o Żydach i relacje chrześcijańsko-żydowskie. Ksiądz i Czepiec rozmawiają z arendarzem, a Rachel jest przedstawiana jako uczestniczka wesela. akt I, sc. 28–29. $lektury$, $lektury${"motyw":"stereotypy o Żydach i relacje chrześcijańsko-żydowskie","przyklad":"Ksiądz i Czepiec rozmawiają z arendarzem, a Rachel jest przedstawiana jako uczestniczka wesela.","miejsce":"akt I, sc. 28–29"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$motyw$lektury$, 8, $lektury$akt I, sc. 12$lektury$, $lektury$miłość i małżeństwo ponad podziałami. Pan Młody pyta Pannę Młodą o miłość; w rozmowie wychodzą rozbieżności ich światów. akt I, sc. 12. $lektury$, $lektury${"motyw":"miłość i małżeństwo ponad podziałami","przyklad":"Pan Młody pyta Pannę Młodą o miłość; w rozmowie wychodzą rozbieżności ich światów.","miejsce":"akt I, sc. 12"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$motyw$lektury$, 9, $lektury$akt III, sc. 32$lektury$, $lektury$brak działania i bierność. Choć do izby wchodzą chłopi z kosami, a Jasiek ma róg, w finale goście pozostają w bezruchu aż do chocholiego tańca. akt III, sc. 32. $lektury$, $lektury${"motyw":"brak działania i bierność","przyklad":"Choć do izby wchodzą chłopi z kosami, a Jasiek ma róg, w finale goście pozostają w bezruchu aż do chocholiego tańca.","miejsce":"akt III, sc. 32"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pobrany tekst dramatu; podział na akty i sceny według Wolnych Lektur; sprawdzono pełną listę scen z osobami, scenę Wernyhory (akt II, sc. 24), wręczenie rogu (sc. 26) i końcówkę dramatu (akt III, sc. 35–37) oraz cytaty.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/wesele/","rodzaj":"utwór","co":"Pobrany tekst dramatu; podział na akty i sceny według Wolnych Lektur; sprawdzono pełną listę scen z osobami, scenę Wernyhory (akt II, sc. 24), wręczenie rogu (sc. 26) i końcówkę dramatu (akt III, sc. 35–37) oraz cytaty."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Przypisanie postaci historycznym osobom z Bronowic (Pan Młody, Poeta, Dziennikarz, Gospodarz) nie jest zawarte w danych; wymaga źródła.$lektury$, $lektury${"tekst":"Przypisanie postaci historycznym osobom z Bronowic (Pan Młody, Poeta, Dziennikarz, Gospodarz) nie jest zawarte w danych; wymaga źródła."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Opisy większości scen aktu I (poza sc. 1, 24, 36–38) i aktu II (poza sc. 3, 24, 26) powstały na podstawie listy osób i nagłówków scen, nie pełnego czytania; wymagają sprawdzenia w tekście.$lektury$, $lektury${"tekst":"Opisy większości scen aktu I (poza sc. 1, 24, 36–38) i aktu II (poza sc. 3, 24, 26) powstały na podstawie listy osób i nagłówków scen, nie pełnego czytania; wymagają sprawdzenia w tekście."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Treść rozmów Poety, Dziennikarza i zjaw w akcie II i III oraz rola Czepca w akcie III są opisane ogólnie; szczegóły do uzupełnienia po czytaniu tekstu.$lektury$, $lektury${"tekst":"Treść rozmów Poety, Dziennikarza i zjaw w akcie II i III oraz rola Czepca w akcie III są opisane ogólnie; szczegóły do uzupełnienia po czytaniu tekstu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$weryfikacja$lektury$, 4, $lektury$$lektury$, $lektury$W wersji z Wolnych Lektur wiersz brzmi „Miałeś, chłopie, złoty róg”; w niektórych wydaniach używa się słowa „chamie”.$lektury$, $lektury${"tekst":"W wersji z Wolnych Lektur wiersz brzmi „Miałeś, chłopie, złoty róg”; w niektórych wydaniach używa się słowa „chamie”."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$),
  ($lektury$wesele$lektury$, $lektury$weryfikacja$lektury$, 5, $lektury$$lektury$, $lektury$Dokładny przebieg chocholiego tańca w akcie III sc. 37 nie został przeczytany do końca.$lektury$, $lektury${"tekst":"Dokładny przebieg chocholiego tańca w akcie III sc. 37 nie został przeczytany do końca."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/wesele/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-baczynskiego$lektury$, $lektury$motyw$lektury$, 1, $lektury$Elegia o… [chłopcu polskim]$lektury$, $lektury$wojna i stracone pokolenie. Mówiący opisuje chłopca, któremu wojna odebrała sny i dzieciństwo, a w końcu prowadzi go z bronią w noc. Elegia o… [chłopcu polskim]. Oddzielili cię, syneczku, od snów, co jak motyl drżą$lektury$, $lektury${"motyw":"wojna i stracone pokolenie","przyklad":"Mówiący opisuje chłopca, któremu wojna odebrała sny i dzieciństwo, a w końcu prowadzi go z bronią w noc.","miejsce":"Elegia o… [chłopcu polskim]","cytat":"Oddzielili cię, syneczku, od snów, co jak motyl drżą"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/baczynski-elegia-o-chlopcu-polskim/$lektury$),
  ($lektury$wiersze-baczynskiego$lektury$, $lektury$motyw$lektury$, 2, $lektury$Elegia o… [chłopcu polskim]$lektury$, $lektury$śmierć młodego żołnierza. Ostatnia strofa pokazuje chłopca, który przed śmiercią żegna ziemię; pytanie o kulę lub pęknięte serce zostawia wątpliwość. Elegia o… [chłopcu polskim]. Zanim padłeś, jeszcze ziemię przeżegnałeś ręką.$lektury$, $lektury${"motyw":"śmierć młodego żołnierza","przyklad":"Ostatnia strofa pokazuje chłopca, który przed śmiercią żegna ziemię; pytanie o kulę lub pęknięte serce zostawia wątpliwość.","miejsce":"Elegia o… [chłopcu polskim]","cytat":"Zanim padłeś, jeszcze ziemię przeżegnałeś ręką."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/baczynski-elegia-o-chlopcu-polskim/$lektury$),
  ($lektury$wiersze-baczynskiego$lektury$, $lektury$motyw$lektury$, 3, $lektury$Elegia o… [chłopcu polskim]$lektury$, $lektury$rozstanie z dzieciństwem. Pierwsze strofy opisują, jak dzieciństwo i sny chłopca zastąpiły krajobrazy pożóg i drzewa pełne wisielców. Elegia o… [chłopcu polskim]. $lektury$, $lektury${"motyw":"rozstanie z dzieciństwem","przyklad":"Pierwsze strofy opisują, jak dzieciństwo i sny chłopca zastąpiły krajobrazy pożóg i drzewa pełne wisielców.","miejsce":"Elegia o… [chłopcu polskim]"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/baczynski-elegia-o-chlopcu-polskim/$lektury$),
  ($lektury$wiersze-baczynskiego$lektury$, $lektury$utwor$lektury$, 1, $lektury$cały wiersz; data pod tekstem: 20 marca 1944$lektury$, $lektury$Elegia o… [chłopcu polskim]. Elegia, w której mówiący zwraca się do „synka” zniszczonego przez wojnę: oddzielono go od snów, jego świat ozdobiono obrazami krwi i szubienic, a on wychodzi „z czarną bronią w noc”. Końcowa strofa pyta, czy padł od kuli, czy pękło mu serce. Wiersz mówi o straconym pokoleniu.$lektury$, $lektury${"tytul":"Elegia o… [chłopcu polskim]","miejsce":"cały wiersz; data pod tekstem: 20 marca 1944","opis":"Elegia, w której mówiący zwraca się do „synka” zniszczonego przez wojnę: oddzielono go od snów, jego świat ozdobiono obrazami krwi i szubienic, a on wychodzi „z czarną bronią w noc”. Końcowa strofa pyta, czy padł od kuli, czy pękło mu serce. Wiersz mówi o straconym pokoleniu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/baczynski-elegia-o-chlopcu-polskim/$lektury$),
  ($lektury$wiersze-baczynskiego$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pełny tekst; cytaty i data sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/baczynski-elegia-o-chlopcu-polskim/","rodzaj":"utwór","co":"Pełny tekst; cytaty i data sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/baczynski-elegia-o-chlopcu-polskim/$lektury$),
  ($lektury$wiersze-baczynskiego$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Baczyński zmarł w 1944 r. (utwór w domenie publicznej); inne wiersze z wyboru (np. „Pokolenie”, „Niebo złote ci otworzę…”) nie zostały sprawdzone ani opisane.$lektury$, $lektury${"tekst":"Baczyński zmarł w 1944 r. (utwór w domenie publicznej); inne wiersze z wyboru (np. „Pokolenie”, „Niebo złote ci otworzę…”) nie zostały sprawdzone ani opisane."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/baczynski-elegia-o-chlopcu-polskim/$lektury$),
  ($lektury$wiersze-baczynskiego$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wybór CKE wierszy Baczyńskiego nie został sprawdzony; poza przykładem z katalogu nie ustalono listy.$lektury$, $lektury${"tekst":"Wybór CKE wierszy Baczyńskiego nie został sprawdzony; poza przykładem z katalogu nie ustalono listy."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/baczynski-elegia-o-chlopcu-polskim/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-baranczaka$lektury$, $lektury$motyw$lektury$, 1, $lektury$Wiersze Barańczaka (ogólnie)$lektury$, $lektury$poezja jako forma protestu. Według ZPE Barańczak uważał poezję za zawsze jakąś formę protestu — przeciw przemocy politycznej, ale i wobec nieuchronności śmierci. Wiersze Barańczaka (ogólnie). $lektury$, $lektury${"motyw":"poezja jako forma protestu","przyklad":"Według ZPE Barańczak uważał poezję za zawsze jakąś formę protestu — przeciw przemocy politycznej, ale i wobec nieuchronności śmierci.","miejsce":"Wiersze Barańczaka (ogólnie)"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$),
  ($lektury$wiersze-baranczaka$lektury$, $lektury$motyw$lektury$, 2, $lektury$Wiersze Barańczaka (ogólnie)$lektury$, $lektury$krytyka nowomowy i systemu. W początkach twórczości poeta pokazywał absurd systemu totalitarnego i pustkę nowomowy (Nowa Fala). Wiersze Barańczaka (ogólnie). $lektury$, $lektury${"motyw":"krytyka nowomowy i systemu","przyklad":"W początkach twórczości poeta pokazywał absurd systemu totalitarnego i pustkę nowomowy (Nowa Fala).","miejsce":"Wiersze Barańczaka (ogólnie)"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$),
  ($lektury$wiersze-baranczaka$lektury$, $lektury$motyw$lektury$, 3, $lektury$Drobnomieszczańskie cnoty$lektury$, $lektury$nonkonformizm wobec zastanych wzorów. Poeta sprzeciwiał się konwencjonalnym i zastanym postawom, także w wymiarze egzystencjalnym i społecznym. Drobnomieszczańskie cnoty. $lektury$, $lektury${"motyw":"nonkonformizm wobec zastanych wzorów","przyklad":"Poeta sprzeciwiał się konwencjonalnym i zastanym postawom, także w wymiarze egzystencjalnym i społecznym.","miejsce":"Drobnomieszczańskie cnoty"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$),
  ($lektury$wiersze-baranczaka$lektury$, $lektury$motyw$lektury$, 4, $lektury$Z okna na którymś piętrze ta aria Mozarta$lektury$, $lektury$muzyka i forma. Poeta bardzo dba o formę; Mozart i muzyka inspirują rozbudowane układy rymów. Z okna na którymś piętrze ta aria Mozarta. $lektury$, $lektury${"motyw":"muzyka i forma","przyklad":"Poeta bardzo dba o formę; Mozart i muzyka inspirują rozbudowane układy rymów.","miejsce":"Z okna na którymś piętrze ta aria Mozarta"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$),
  ($lektury$wiersze-baranczaka$lektury$, $lektury$motyw$lektury$, 5, $lektury$Z okna na którymś piętrze ta aria Mozarta$lektury$, $lektury$dobro trwałe wobec upadku historii. Aria Mozarta symbolizuje coś, co przetrwa upadające mocarstwa. Z okna na którymś piętrze ta aria Mozarta. $lektury$, $lektury${"motyw":"dobro trwałe wobec upadku historii","przyklad":"Aria Mozarta symbolizuje coś, co przetrwa upadające mocarstwa.","miejsce":"Z okna na którymś piętrze ta aria Mozarta"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$),
  ($lektury$wiersze-baranczaka$lektury$, $lektury$utwor$lektury$, 1, $lektury$przykład z katalogu$lektury$, $lektury$Drobnomieszczańskie cnoty. Wiersz wskazany w katalogu jako przykład. Zgodnie z tytułem ćwiczenia ZPE bohater wiersza odrzuca pewną postawę życiową (związaną z drobnomieszczańskimi „cnotami”) i wybiera inną. Szczegóły treści wiersza nie zostały sprawdzone — zob. do_weryfikacji.$lektury$, $lektury${"tytul":"Drobnomieszczańskie cnoty","miejsce":"przykład z katalogu","opis":"Wiersz wskazany w katalogu jako przykład. Zgodnie z tytułem ćwiczenia ZPE bohater wiersza odrzuca pewną postawę życiową (związaną z drobnomieszczańskimi „cnotami”) i wybiera inną. Szczegóły treści wiersza nie zostały sprawdzone — zob. do_weryfikacji."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$),
  ($lektury$wiersze-baranczaka$lektury$, $lektury$utwor$lektury$, 2, $lektury$przykład z materiału ZPE$lektury$, $lektury$Z okna na którymś piętrze ta aria Mozarta. Wiersz o arii Mozarta słyszanej z okna bloku w chwili, gdy „walą się mocarstwa”. Muzyka jest obietnicą trwałego dobra wobec zniszczeń historii. Utwór ma wyrafinowaną formę (powtarzające się rymy i wersy), zgodnie z opisem ZPE.$lektury$, $lektury${"tytul":"Z okna na którymś piętrze ta aria Mozarta","miejsce":"przykład z materiału ZPE","opis":"Wiersz o arii Mozarta słyszanej z okna bloku w chwili, gdy „walą się mocarstwa”. Muzyka jest obietnicą trwałego dobra wobec zniszczeń historii. Utwór ma wyrafinowaną formę (powtarzające się rymy i wersy), zgodnie z opisem ZPE."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$),
  ($lektury$wiersze-baranczaka$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Materiał ZPE „Jaką postawę życiową odrzuca, a jaką wybiera bohater wiersza Stanisława Barańczaka Drobnomieszczańskie cnoty?”: biografia poety, Nowa Fala, protest, forma, wiersz o arii Mozarta (tekst wiersza nie został skopiowany).$lektury$, $lektury${"url":"https://zpe.gov.pl/a/przeczytaj/D4il8EjHH","rodzaj":"opracowanie","co":"Materiał ZPE „Jaką postawę życiową odrzuca, a jaką wybiera bohater wiersza Stanisława Barańczaka Drobnomieszczańskie cnoty?”: biografia poety, Nowa Fala, protest, forma, wiersz o arii Mozarta (tekst wiersza nie został skopiowany)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$),
  ($lektury$wiersze-baranczaka$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Tekst „Drobnomieszczańskich cnót” nie był czytany; w materiale ZPE nie udało się odnaleźć opisu jego treści, więc opis ogranicza się do tytułu ćwiczenia — wymaga weryfikacji w pełnym materiale ZPE lub opracowaniu.$lektury$, $lektury${"tekst":"Tekst „Drobnomieszczańskich cnót” nie był czytany; w materiale ZPE nie udało się odnaleźć opisu jego treści, więc opis ogranicza się do tytułu ćwiczenia — wymaga weryfikacji w pełnym materiale ZPE lub opracowaniu."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$),
  ($lektury$wiersze-baranczaka$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Barańczak zmarł w 2014 r., jego wiersze są chronione prawem autorskim; tekstów i cytatów nie podano.$lektury$, $lektury${"tekst":"Barańczak zmarł w 2014 r., jego wiersze są chronione prawem autorskim; tekstów i cytatów nie podano."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$),
  ($lektury$wiersze-baranczaka$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony.$lektury$, $lektury${"tekst":"Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/D4il8EjHH$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-bialoszewskiego$lektury$, $lektury$motyw$lektury$, 1, $lektury$Stara pieśń na Binnarową$lektury$, $lektury$nawiązania do pieśni średniowiecznej. ZPE omawia nawiązania do dawnej pieśni religijnej i stylizację (porównanie ze stylistyką pieśni Karpińskiego). Stara pieśń na Binnarową. $lektury$, $lektury${"motyw":"nawiązania do pieśni średniowiecznej","przyklad":"ZPE omawia nawiązania do dawnej pieśni religijnej i stylizację (porównanie ze stylistyką pieśni Karpińskiego).","miejsce":"Stara pieśń na Binnarową"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/DE4524hI1$lektury$),
  ($lektury$wiersze-bialoszewskiego$lektury$, $lektury$motyw$lektury$, 2, $lektury$Stara pieśń na Binnarową$lektury$, $lektury$stylizacja i język. Wiersz stylizuje dawną pieśń; materiały ZPE zawierają interaktywny schemat jego warsztatu poetyckiego. Stara pieśń na Binnarową. $lektury$, $lektury${"motyw":"stylizacja i język","przyklad":"Wiersz stylizuje dawną pieśń; materiały ZPE zawierają interaktywny schemat jego warsztatu poetyckiego.","miejsce":"Stara pieśń na Binnarową"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/DE4524hI1$lektury$),
  ($lektury$wiersze-bialoszewskiego$lektury$, $lektury$motyw$lektury$, 3, $lektury$Stara pieśń na Binnarową$lektury$, $lektury$Podkarpacie. Cykl „Ballady rzeszowskie” wyraża podkarpackie fascynacje poety. Stara pieśń na Binnarową. $lektury$, $lektury${"motyw":"Podkarpacie","przyklad":"Cykl „Ballady rzeszowskie” wyraża podkarpackie fascynacje poety.","miejsce":"Stara pieśń na Binnarową"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/DE4524hI1$lektury$),
  ($lektury$wiersze-bialoszewskiego$lektury$, $lektury$utwor$lektury$, 1, $lektury$z tomu „Obroty rzeczy” (1956), cykl „Ballady rzeszowskie”$lektury$, $lektury$Stara pieśń na Binnarową. Według ZPE wiersz ukazał się w 1956 r. w tomie „Obroty rzeczy” i należy do cyklu „Ballad rzeszowskich”, wyrażającego podkarpackie zainteresowania poety. ZPE omawia nawiązania do kultury średniowiecza, w tym do dawnych pieśni religijnych; nazwa „Binnarowa” nie występuje na współczesnych mapach ani w źródłach średniowiecznych.$lektury$, $lektury${"tytul":"Stara pieśń na Binnarową","miejsce":"z tomu „Obroty rzeczy” (1956), cykl „Ballady rzeszowskie”","opis":"Według ZPE wiersz ukazał się w 1956 r. w tomie „Obroty rzeczy” i należy do cyklu „Ballad rzeszowskich”, wyrażającego podkarpackie zainteresowania poety. ZPE omawia nawiązania do kultury średniowiecza, w tym do dawnych pieśni religijnych; nazwa „Binnarowa” nie występuje na współczesnych mapach ani w źródłach średniowiecznych."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/DE4524hI1$lektury$),
  ($lektury$wiersze-bialoszewskiego$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Materiał ZPE „Nawiązania do kultury średniowiecza w wierszu Mirona Białoszewskiego Stara pieśń na Binnarową”.$lektury$, $lektury${"url":"https://zpe.gov.pl/a/przeczytaj/DE4524hI1","rodzaj":"opracowanie","co":"Materiał ZPE „Nawiązania do kultury średniowiecza w wierszu Mirona Białoszewskiego Stara pieśń na Binnarową”."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/DE4524hI1$lektury$),
  ($lektury$wiersze-bialoszewskiego$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Utwory autora są chronione prawem autorskim (zmarł w 1983 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury).$lektury$, $lektury${"tekst":"Utwory autora są chronione prawem autorskim (zmarł w 1983 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/DE4524hI1$lektury$),
  ($lektury$wiersze-bialoszewskiego$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów.$lektury$, $lektury${"tekst":"Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/DE4524hI1$lektury$),
  ($lektury$wiersze-bialoszewskiego$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Treść wiersza i dokładny sens stylizacji nie były czytane — opis tylko z podsumowań ZPE.$lektury$, $lektury${"tekst":"Treść wiersza i dokładny sens stylizacji nie były czytane — opis tylko z podsumowań ZPE."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/DE4524hI1$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-czechowicza$lektury$, $lektury$motyw$lektury$, 1, $lektury$Żal$lektury$, $lektury$katastrofizm. Obrazy płomieni, głodnych ludów i wieczoru „świata tego” układają się w zapowiedź zagłady. Żal. zniża się wieczór świata tego$lektury$, $lektury${"motyw":"katastrofizm","przyklad":"Obrazy płomieni, głodnych ludów i wieczoru „świata tego” układają się w zapowiedź zagłady.","miejsce":"Żal","cytat":"zniża się wieczór świata tego"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/nuta-czlowiecza-zal/$lektury$),
  ($lektury$wiersze-czechowicza$lektury$, $lektury$motyw$lektury$, 2, $lektury$Żal$lektury$, $lektury$wielość ofiar i identyfikacja. Mówiący wymienia siebie w roli oracza, jurysty, dziecka w pochodni i powieszonego podpalacza, co można odczytać jako utożsamienie z wieloma ofiarami. Żal. $lektury$, $lektury${"motyw":"wielość ofiar i identyfikacja","przyklad":"Mówiący wymienia siebie w roli oracza, jurysty, dziecka w pochodni i powieszonego podpalacza, co można odczytać jako utożsamienie z wieloma ofiarami.","miejsce":"Żal"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/nuta-czlowiecza-zal/$lektury$),
  ($lektury$wiersze-czechowicza$lektury$, $lektury$motyw$lektury$, 3, $lektury$Żal$lektury$, $lektury$zniszczenie świętych miejsc. Obraz „roztrzaskanych szybek synagog” łączy zagładę cywilizacji ze zniszczeniem miejsc kultu. Żal. roztrzaskane szybki synagog$lektury$, $lektury${"motyw":"zniszczenie świętych miejsc","przyklad":"Obraz „roztrzaskanych szybek synagog” łączy zagładę cywilizacji ze zniszczeniem miejsc kultu.","miejsce":"Żal","cytat":"roztrzaskane szybki synagog"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/nuta-czlowiecza-zal/$lektury$),
  ($lektury$wiersze-czechowicza$lektury$, $lektury$motyw$lektury$, 4, $lektury$Żal$lektury$, $lektury$nakaz iść dalej. Wiersz kończy się dwukrotnym wezwaniem do dalszej drogi mimo grozy. Żal. idźże idź dalej$lektury$, $lektury${"motyw":"nakaz iść dalej","przyklad":"Wiersz kończy się dwukrotnym wezwaniem do dalszej drogi mimo grozy.","miejsce":"Żal","cytat":"idźże idź dalej"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/nuta-czlowiecza-zal/$lektury$),
  ($lektury$wiersze-czechowicza$lektury$, $lektury$utwor$lektury$, 1, $lektury$cały wiersz$lektury$, $lektury$Żal. Wiersz bez interpunkcji i dużych liter, w którym mówiący zapisuje obrazy wojennej grozy i świata ogarniętego przemocą: płonące statki, bombę, głodne ludy i „roztrzaskane szybki synagog”. Powtarza się refren-zaklęcie „idźże idź dalej”. Można go odczytać jako wiersz katastroficzny o zbliżającej się wojnie.$lektury$, $lektury${"tytul":"Żal","miejsce":"cały wiersz","opis":"Wiersz bez interpunkcji i dużych liter, w którym mówiący zapisuje obrazy wojennej grozy i świata ogarniętego przemocą: płonące statki, bombę, głodne ludy i „roztrzaskane szybki synagog”. Powtarza się refren-zaklęcie „idźże idź dalej”. Można go odczytać jako wiersz katastroficzny o zbliżającej się wojnie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/nuta-czlowiecza-zal/$lektury$),
  ($lektury$wiersze-czechowicza$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Tekst wiersza „Żal” z tomu „Nuta człowiecza”; cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/nuta-czlowiecza-zal/","rodzaj":"utwór","co":"Tekst wiersza „Żal” z tomu „Nuta człowiecza”; cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/nuta-czlowiecza-zal/$lektury$),
  ($lektury$wiersze-czechowicza$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Czechowicz zmarł w 1939 r. (domena publiczna). Wybór wierszy w wymaganiach CKE nie został sprawdzony; poza „Żalem” nie opracowano innych.$lektury$, $lektury${"tekst":"Czechowicz zmarł w 1939 r. (domena publiczna). Wybór wierszy w wymaganiach CKE nie został sprawdzony; poza „Żalem” nie opracowano innych."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/nuta-czlowiecza-zal/$lektury$),
  ($lektury$wiersze-czechowicza$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Datowanie wiersza i tomu („nuta człowiecza”, 1939) podano z tytułu w Wolnych Lekturach; nie sprawdzono tego w opracowaniu naukowym.$lektury$, $lektury${"tekst":"Datowanie wiersza i tomu („nuta człowiecza”, 1939) podano z tytułu w Wolnych Lekturach; nie sprawdzono tego w opracowaniu naukowym."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/nuta-czlowiecza-zal/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-herberta$lektury$, $lektury$motyw$lektury$, 1, $lektury$Przesłanie Pana Cogito$lektury$, $lektury$wierność wartościom. Pan Cogito jako nauczyciel zaleca wierność niewzruszonym normom etycznym, nawet za cenę ofiar (według ZPE). Przesłanie Pana Cogito. $lektury$, $lektury${"motyw":"wierność wartościom","przyklad":"Pan Cogito jako nauczyciel zaleca wierność niewzruszonym normom etycznym, nawet za cenę ofiar (według ZPE).","miejsce":"Przesłanie Pana Cogito"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/zbigniew-herbert-przeslanie-pana-cogito/D13cLarOU$lektury$),
  ($lektury$wiersze-herberta$lektury$, $lektury$motyw$lektury$, 2, $lektury$Przesłanie Pana Cogito$lektury$, $lektury$ofiara i bezsensowna nagroda. Metafora złotego runa okazuje się „runem nicości”, czyli nagroda za wierność bywa bezwartościowa (według ZPE). Przesłanie Pana Cogito. $lektury$, $lektury${"motyw":"ofiara i bezsensowna nagroda","przyklad":"Metafora złotego runa okazuje się „runem nicości”, czyli nagroda za wierność bywa bezwartościowa (według ZPE).","miejsce":"Przesłanie Pana Cogito"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/zbigniew-herbert-przeslanie-pana-cogito/D13cLarOU$lektury$),
  ($lektury$wiersze-herberta$lektury$, $lektury$motyw$lektury$, 3, $lektury$Przesłanie Pana Cogito$lektury$, $lektury$etos rycerski. Herbert odwołuje się do ideałów rycerzy z antyku i średniowiecza, by pokazać uniwersalność zasad moralnych (według ZPE). Przesłanie Pana Cogito. $lektury$, $lektury${"motyw":"etos rycerski","przyklad":"Herbert odwołuje się do ideałów rycerzy z antyku i średniowiecza, by pokazać uniwersalność zasad moralnych (według ZPE).","miejsce":"Przesłanie Pana Cogito"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/zbigniew-herbert-przeslanie-pana-cogito/D13cLarOU$lektury$),
  ($lektury$wiersze-herberta$lektury$, $lektury$motyw$lektury$, 4, $lektury$Przesłanie Pana Cogito$lektury$, $lektury$postać Pana Cogito. Osoba mówiąca to Pan Cogito, postać-maska poety o nazwisku nawiązującym do Kartezjusza. Przesłanie Pana Cogito. $lektury$, $lektury${"motyw":"postać Pana Cogito","przyklad":"Osoba mówiąca to Pan Cogito, postać-maska poety o nazwisku nawiązującym do Kartezjusza.","miejsce":"Przesłanie Pana Cogito"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/zbigniew-herbert-przeslanie-pana-cogito/D13cLarOU$lektury$),
  ($lektury$wiersze-herberta$lektury$, $lektury$utwor$lektury$, 1, $lektury$wiersz z tomu „Pan Cogito” (1974)$lektury$, $lektury$Przesłanie Pana Cogito. Wiersz, w którym osobą mówiącą jest Pan Cogito, postać o nazwisku odwołującym się do maksymy Kartezjusza; przejmuje rolę nauczyciela i mędrca. Według ZPE wiersz zawiera zalecenie „Bądź wierny” i wyraża przekonanie, że wierność niewzruszonym normom etycznym wymaga ofiar. Metafora „złotego runa” zapowiada nagrodę, która okazuje się „runem nicości”; w wierszu pojawiają się odwołania do ideałów rycerskich.$lektury$, $lektury${"tytul":"Przesłanie Pana Cogito","miejsce":"wiersz z tomu „Pan Cogito” (1974)","opis":"Wiersz, w którym osobą mówiącą jest Pan Cogito, postać o nazwisku odwołującym się do maksymy Kartezjusza; przejmuje rolę nauczyciela i mędrca. Według ZPE wiersz zawiera zalecenie „Bądź wierny” i wyraża przekonanie, że wierność niewzruszonym normom etycznym wymaga ofiar. Metafora „złotego runa” zapowiada nagrodę, która okazuje się „runem nicości”; w wierszu pojawiają się odwołania do ideałów rycerskich."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/zbigniew-herbert-przeslanie-pana-cogito/D13cLarOU$lektury$),
  ($lektury$wiersze-herberta$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Materiał ZPE o „Przesłaniu Pana Cogito”: postać Pana Cogito, zalecenie „Bądź wierny”, złote runo (czytane jako wynik wyszukiwania).$lektury$, $lektury${"url":"https://zpe.gov.pl/a/zbigniew-herbert-przeslanie-pana-cogito/D13cLarOU","rodzaj":"opracowanie","co":"Materiał ZPE o „Przesłaniu Pana Cogito”: postać Pana Cogito, zalecenie „Bądź wierny”, złote runo (czytane jako wynik wyszukiwania)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/zbigniew-herbert-przeslanie-pana-cogito/D13cLarOU$lektury$),
  ($lektury$wiersze-herberta$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Ćwiczenia ZPE „Etos rycerski” z odniesieniem do wiersza.$lektury$, $lektury${"url":"https://zpe.gov.pl/a/sprawdz-sie/DUnS1AeYj","rodzaj":"opracowanie","co":"Ćwiczenia ZPE „Etos rycerski” z odniesieniem do wiersza."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/sprawdz-sie/DUnS1AeYj$lektury$),
  ($lektury$wiersze-herberta$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Utwory autora są chronione prawem autorskim (zmarł w 1998 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury).$lektury$, $lektury${"tekst":"Utwory autora są chronione prawem autorskim (zmarł w 1998 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/zbigniew-herbert-przeslanie-pana-cogito/D13cLarOU$lektury$),
  ($lektury$wiersze-herberta$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów.$lektury$, $lektury${"tekst":"Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/zbigniew-herbert-przeslanie-pana-cogito/D13cLarOU$lektury$),
  ($lektury$wiersze-herberta$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Interpretacje podano na podstawie fragmentów opisów ZPE widocznych w wynikach wyszukiwania; pełne strony nie zostały przeczytane.$lektury$, $lektury${"tekst":"Interpretacje podano na podstawie fragmentów opisów ZPE widocznych w wynikach wyszukiwania; pełne strony nie zostały przeczytane."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/zbigniew-herbert-przeslanie-pana-cogito/D13cLarOU$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-lesmiana$lektury$, $lektury$motyw$lektury$, 1, $lektury$Dusiołek$lektury$, $lektury$senna zmora i groza. Dusiołek, zjawa z pyskiem „żabio ślimaczym”, dusi śpiącego bohatera. Dusiołek. Szedł po świecie Bajdała$lektury$, $lektury${"motyw":"senna zmora i groza","przyklad":"Dusiołek, zjawa z pyskiem „żabio ślimaczym”, dusi śpiącego bohatera.","miejsce":"Dusiołek","cytat":"Szedł po świecie Bajdała"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/dusiolek/$lektury$),
  ($lektury$wiersze-lesmiana$lektury$, $lektury$motyw$lektury$, 2, $lektury$Dusiołek$lektury$, $lektury$humor i groteska. Opis potwora i język wiersza mieszają straszne ze śmiesznym, np. „zad tyli, co kwoka”. Dusiołek. $lektury$, $lektury${"motyw":"humor i groteska","przyklad":"Opis potwora i język wiersza mieszają straszne ze śmiesznym, np. „zad tyli, co kwoka”.","miejsce":"Dusiołek"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/dusiolek/$lektury$),
  ($lektury$wiersze-lesmiana$lektury$, $lektury$motyw$lektury$, 3, $lektury$Dusiołek$lektury$, $lektury$pytanie do Boga o zło. Końcowa strofa: Bajdała pyta Boga, czy mało mu było stworzyć jego, szkapę i wołka, że stworzył jeszcze Dusiołka. Dusiołek. Nie dość ci, żeś potworzył mnie, szkapę i wołka$lektury$, $lektury${"motyw":"pytanie do Boga o zło","przyklad":"Końcowa strofa: Bajdała pyta Boga, czy mało mu było stworzyć jego, szkapę i wołka, że stworzył jeszcze Dusiołka.","miejsce":"Dusiołek","cytat":"Nie dość ci, żeś potworzył mnie, szkapę i wołka"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/dusiolek/$lektury$),
  ($lektury$wiersze-lesmiana$lektury$, $lektury$motyw$lektury$, 4, $lektury$Dusiołek$lektury$, $lektury$ludowość i wierzenia. Bohater to prosty wędrowiec, a potwór pochodzi z wierzeń ludowych o zmorze. Dusiołek. $lektury$, $lektury${"motyw":"ludowość i wierzenia","przyklad":"Bohater to prosty wędrowiec, a potwór pochodzi z wierzeń ludowych o zmorze.","miejsce":"Dusiołek"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/dusiolek/$lektury$),
  ($lektury$wiersze-lesmiana$lektury$, $lektury$utwor$lektury$, 1, $lektury$Łąka, Ballady$lektury$, $lektury$Dusiołek. Ballada z humorem i grozą: wędrowiec Bajdała zasypia na łące między szkapą a wołem, a przychodzi Dusiołek, który siada mu na piersiach i go dusi. Bajdała budzi się i pyta zwierzęta, dlaczego go nie obroniły, a w końcu pyta Boga, po co stworzył takiego Dusiołka.$lektury$, $lektury${"tytul":"Dusiołek","miejsce":"Łąka, Ballady","opis":"Ballada z humorem i grozą: wędrowiec Bajdała zasypia na łące między szkapą a wołem, a przychodzi Dusiołek, który siada mu na piersiach i go dusi. Bajdała budzi się i pyta zwierzęta, dlaczego go nie obroniły, a w końcu pyta Boga, po co stworzył takiego Dusiołka."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/dusiolek/$lektury$),
  ($lektury$wiersze-lesmiana$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pełny tekst; cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/dusiolek/","rodzaj":"utwór","co":"Pełny tekst; cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/dusiolek/$lektury$),
  ($lektury$wiersze-lesmiana$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Leśmian zmarł w 1937 r. (domena publiczna). Pochodzenie ballady z tomu „Łąka” podane za nagłówkiem Wolnych Lektur.$lektury$, $lektury${"tekst":"Leśmian zmarł w 1937 r. (domena publiczna). Pochodzenie ballady z tomu „Łąka” podane za nagłówkiem Wolnych Lektur."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/dusiolek/$lektury$),
  ($lektury$wiersze-lesmiana$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wybór wierszy CKE nie sprawdzony; poza „Dusiołkiem” nie opracowano innych utworów.$lektury$, $lektury${"tekst":"Wybór wierszy CKE nie sprawdzony; poza „Dusiołkiem” nie opracowano innych utworów."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/dusiolek/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-milosza$lektury$, $lektury$motyw$lektury$, 1, $lektury$Piosenka o końcu świata$lektury$, $lektury$koniec świata. Koniec świata można rozumieć jako doświadczenie indywidualnej śmierci albo zagłady ludzkości (według ZPE). Piosenka o końcu świata. $lektury$, $lektury${"motyw":"koniec świata","przyklad":"Koniec świata można rozumieć jako doświadczenie indywidualnej śmierci albo zagłady ludzkości (według ZPE).","miejsce":"Piosenka o końcu świata"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LPCgxyBw7p/243/a/innego-konca-swiata-nie-bedzie---czeslaw-milosz-piosenka-o-koncu-swiata/DAf4I4rCP$lektury$),
  ($lektury$wiersze-milosza$lektury$, $lektury$motyw$lektury$, 2, $lektury$Piosenka o końcu świata$lektury$, $lektury$nawiązania do Apokalipsy. ZPE wskazuje na odwołania do Apokalipsy św. Jana. Piosenka o końcu świata. $lektury$, $lektury${"motyw":"nawiązania do Apokalipsy","przyklad":"ZPE wskazuje na odwołania do Apokalipsy św. Jana.","miejsce":"Piosenka o końcu świata"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LPCgxyBw7p/243/a/innego-konca-swiata-nie-bedzie---czeslaw-milosz-piosenka-o-koncu-swiata/DAf4I4rCP$lektury$),
  ($lektury$wiersze-milosza$lektury$, $lektury$motyw$lektury$, 3, $lektury$Piosenka o końcu świata$lektury$, $lektury$zwyczajność wobec katastrofy. ZPE zauważa, że wiersz — mimo wojennego kontekstu — odbiega od wierszy naznaczonych okrucieństwem okupacji; można odczytać to jako opis obojętnej codzienności. Piosenka o końcu świata. $lektury$, $lektury${"motyw":"zwyczajność wobec katastrofy","przyklad":"ZPE zauważa, że wiersz — mimo wojennego kontekstu — odbiega od wierszy naznaczonych okrucieństwem okupacji; można odczytać to jako opis obojętnej codzienności.","miejsce":"Piosenka o końcu świata"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LPCgxyBw7p/243/a/innego-konca-swiata-nie-bedzie---czeslaw-milosz-piosenka-o-koncu-swiata/DAf4I4rCP$lektury$),
  ($lektury$wiersze-milosza$lektury$, $lektury$utwor$lektury$, 1, $lektury$z tomu „Ocalenie” (1945), otwiera cykl „Głosy biednych ludzi”$lektury$, $lektury$Piosenka o końcu świata. Wiersz powstały w czasie wojny. Według ZPE interpretuje się go w kontekście wojennym, a jednocześnie odbiega on od wierszy naznaczonych okrucieństwem okupacji; ma nawiązania do Apokalipsy św. Jana. Koniec świata można rozumieć jako indywidualną śmierć albo zagładę ludzkości.$lektury$, $lektury${"tytul":"Piosenka o końcu świata","miejsce":"z tomu „Ocalenie” (1945), otwiera cykl „Głosy biednych ludzi”","opis":"Wiersz powstały w czasie wojny. Według ZPE interpretuje się go w kontekście wojennym, a jednocześnie odbiega on od wierszy naznaczonych okrucieństwem okupacji; ma nawiązania do Apokalipsy św. Jana. Koniec świata można rozumieć jako indywidualną śmierć albo zagładę ludzkości."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LPCgxyBw7p/243/a/innego-konca-swiata-nie-bedzie---czeslaw-milosz-piosenka-o-koncu-swiata/DAf4I4rCP$lektury$),
  ($lektury$wiersze-milosza$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Materiał ZPE o „Piosence o końcu świata”: tom Ocalenie (1945), cykl Głosy biednych ludzi, nawiązania do Apokalipsy.$lektury$, $lektury${"url":"https://zpe.gov.pl/watek/LPCgxyBw7p/243/a/innego-konca-swiata-nie-bedzie---czeslaw-milosz-piosenka-o-koncu-swiata/DAf4I4rCP","rodzaj":"opracowanie","co":"Materiał ZPE o „Piosence o końcu świata”: tom Ocalenie (1945), cykl Głosy biednych ludzi, nawiązania do Apokalipsy."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LPCgxyBw7p/243/a/innego-konca-swiata-nie-bedzie---czeslaw-milosz-piosenka-o-koncu-swiata/DAf4I4rCP$lektury$),
  ($lektury$wiersze-milosza$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Utwory autora są chronione prawem autorskim (zmarł w 2004 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury).$lektury$, $lektury${"tekst":"Utwory autora są chronione prawem autorskim (zmarł w 2004 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LPCgxyBw7p/243/a/innego-konca-swiata-nie-bedzie---czeslaw-milosz-piosenka-o-koncu-swiata/DAf4I4rCP$lektury$),
  ($lektury$wiersze-milosza$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów.$lektury$, $lektury${"tekst":"Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LPCgxyBw7p/243/a/innego-konca-swiata-nie-bedzie---czeslaw-milosz-piosenka-o-koncu-swiata/DAf4I4rCP$lektury$),
  ($lektury$wiersze-milosza$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Opis opiera się na podsumowaniu wyników wyszukiwania ZPE; treść wiersza nie była czytana.$lektury$, $lektury${"tekst":"Opis opiera się na podsumowaniu wyników wyszukiwania ZPE; treść wiersza nie była czytana."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/watek/LPCgxyBw7p/243/a/innego-konca-swiata-nie-bedzie---czeslaw-milosz-piosenka-o-koncu-swiata/DAf4I4rCP$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-norwida$lektury$, $lektury$motyw$lektury$, 1, $lektury$Nad grobem Julii Capuletti w Weronie, strofa I$lektury$, $lektury$miłość silniejsza niż rody. Nad domami zwaśnionych Kapuletich i Montekich spada łza z nieba dla Julii i Romea. Nad grobem Julii Capuletti w Weronie, strofa I. Cyprysy mówią, że to dla Juliety,$lektury$, $lektury${"motyw":"miłość silniejsza niż rody","przyklad":"Nad domami zwaśnionych Kapuletich i Montekich spada łza z nieba dla Julii i Romea.","miejsce":"Nad grobem Julii Capuletti w Weronie, strofa I","cytat":"Cyprysy mówią, że to dla Juliety,"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/norwid-nad-grobem-julii-capulleti-w-weronie/$lektury$),
  ($lektury$wiersze-norwida$lektury$, $lektury$motyw$lektury$, 2, $lektury$Nad grobem Julii Capuletti w Weronie, strofa II$lektury$, $lektury$sprzeczne wyjaśnienia świata. Cyprysy widzą łzę, a ludzie wyjaśniają, że to kamienie; można odczytać to jako spór poetyckiego odczytania z naukowym. Nad grobem Julii Capuletti w Weronie, strofa II. Że to nie łzy są, ale że kamienie$lektury$, $lektury${"motyw":"sprzeczne wyjaśnienia świata","przyklad":"Cyprysy widzą łzę, a ludzie wyjaśniają, że to kamienie; można odczytać to jako spór poetyckiego odczytania z naukowym.","miejsce":"Nad grobem Julii Capuletti w Weronie, strofa II","cytat":"Że to nie łzy są, ale że kamienie"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/norwid-nad-grobem-julii-capulleti-w-weronie/$lektury$),
  ($lektury$wiersze-norwida$lektury$, $lektury$motyw$lektury$, 3, $lektury$Nad grobem Julii Capuletti w Weronie, strofa I$lektury$, $lektury$przemijanie i ruina. Mowa o gruzach „nieprzyjaznych grodów” i o wywróconych bramach do ogrodów. Nad grobem Julii Capuletti w Weronie, strofa I. $lektury$, $lektury${"motyw":"przemijanie i ruina","przyklad":"Mowa o gruzach „nieprzyjaznych grodów” i o wywróconych bramach do ogrodów.","miejsce":"Nad grobem Julii Capuletti w Weronie, strofa I"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/norwid-nad-grobem-julii-capulleti-w-weronie/$lektury$),
  ($lektury$wiersze-norwida$lektury$, $lektury$utwor$lektury$, 1, $lektury$cały wiersz$lektury$, $lektury$Nad grobem Julii Capuletti w Weronie. Dwie strofy sześciowersowe. Nad ruinami domów Kapuletich i Montekich „oko błękitu” zrzuca gwiazdę. Cyprysy mówią, że to łza dla Julii i Romea, a „ludzie” — że to kamienie i nikt na nie nie czeka. Wiersz zestawia poetycką i „uczoną” interpretację zjawiska i można go odczytać jako polemikę wrażliwości z rozumem.$lektury$, $lektury${"tytul":"Nad grobem Julii Capuletti w Weronie","miejsce":"cały wiersz","opis":"Dwie strofy sześciowersowe. Nad ruinami domów Kapuletich i Montekich „oko błękitu” zrzuca gwiazdę. Cyprysy mówią, że to łza dla Julii i Romea, a „ludzie” — że to kamienie i nikt na nie nie czeka. Wiersz zestawia poetycką i „uczoną” interpretację zjawiska i można go odczytać jako polemikę wrażliwości z rozumem."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/norwid-nad-grobem-julii-capulleti-w-weronie/$lektury$),
  ($lektury$wiersze-norwida$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pełny tekst; cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/norwid-nad-grobem-julii-capulleti-w-weronie/","rodzaj":"utwór","co":"Pełny tekst; cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/norwid-nad-grobem-julii-capulleti-w-weronie/$lektury$),
  ($lektury$wiersze-norwida$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Norwid zmarł w 1883 r. (domena publiczna). Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony; inne wiersze (np. „Moja piosnka (II)”, „Bema pamięci żałobny rapsod”) nie zostały opracowane.$lektury$, $lektury${"tekst":"Norwid zmarł w 1883 r. (domena publiczna). Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony; inne wiersze (np. „Moja piosnka (II)”, „Bema pamięci żałobny rapsod”) nie zostały opracowane."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/norwid-nad-grobem-julii-capulleti-w-weronie/$lektury$),
  ($lektury$wiersze-norwida$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wolne Lektury podają wiersz bez daty; datowanie nie zostało sprawdzone.$lektury$, $lektury${"tekst":"Wolne Lektury podają wiersz bez daty; datowanie nie zostało sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/norwid-nad-grobem-julii-capulleti-w-weronie/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-pawlikowskiej$lektury$, $lektury$motyw$lektury$, 1, $lektury$Miłość$lektury$, $lektury$miłość jako oddychanie. Brak ukochanego porównany do braku powietrza: mówiąca jest tylko trochę bledsza i bardziej milcząca. Miłość. lecz widać można żyć bez powietrza!$lektury$, $lektury${"motyw":"miłość jako oddychanie","przyklad":"Brak ukochanego porównany do braku powietrza: mówiąca jest tylko trochę bledsza i bardziej milcząca.","miejsce":"Miłość","cytat":"lecz widać można żyć bez powietrza!"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/pawlikowska-jasnorzewska-milosc/$lektury$),
  ($lektury$wiersze-pawlikowskiej$lektury$, $lektury$motyw$lektury$, 2, $lektury$Miłość$lektury$, $lektury$autoironia i dystans. Wiersz używa lekkiego, ironicznego tonu zamiast patosu. Miłość. $lektury$, $lektury${"motyw":"autoironia i dystans","przyklad":"Wiersz używa lekkiego, ironicznego tonu zamiast patosu.","miejsce":"Miłość"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/pawlikowska-jasnorzewska-milosc/$lektury$),
  ($lektury$wiersze-pawlikowskiej$lektury$, $lektury$motyw$lektury$, 3, $lektury$Miłość$lektury$, $lektury$miniatura liryczna. Całość mieści się w czterech wersach, co jest cechą charakterystyczną twórczości autorki. Miłość. $lektury$, $lektury${"motyw":"miniatura liryczna","przyklad":"Całość mieści się w czterech wersach, co jest cechą charakterystyczną twórczości autorki.","miejsce":"Miłość"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/pawlikowska-jasnorzewska-milosc/$lektury$),
  ($lektury$wiersze-pawlikowskiej$lektury$, $lektury$utwor$lektury$, 1, $lektury$cały wiersz (cztery wersy, zbiór „Pocałunki”)$lektury$, $lektury$Miłość. Czterowersowy miniaturowy wiersz, w którym mówiąca zauważa, że od miesiąca nie widziała ukochanego, i konstatuje z ironią, że widać można żyć bez powietrza. Krótka forma i autoironia przedstawiają miłość jako konieczność jak oddychanie.$lektury$, $lektury${"tytul":"Miłość","miejsce":"cały wiersz (cztery wersy, zbiór „Pocałunki”)","opis":"Czterowersowy miniaturowy wiersz, w którym mówiąca zauważa, że od miesiąca nie widziała ukochanego, i konstatuje z ironią, że widać można żyć bez powietrza. Krótka forma i autoironia przedstawiają miłość jako konieczność jak oddychanie."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/pawlikowska-jasnorzewska-milosc/$lektury$),
  ($lektury$wiersze-pawlikowskiej$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pełny tekst; cytat sprawdzony. Wolne Lektury podają wiersz w zbiorze „Pocałunki”.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/pawlikowska-jasnorzewska-milosc/","rodzaj":"utwór","co":"Pełny tekst; cytat sprawdzony. Wolne Lektury podają wiersz w zbiorze „Pocałunki”."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/pawlikowska-jasnorzewska-milosc/$lektury$),
  ($lektury$wiersze-pawlikowskiej$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Autorka zmarła w 1945 r. (domena publiczna). Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony.$lektury$, $lektury${"tekst":"Autorka zmarła w 1945 r. (domena publiczna). Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/pawlikowska-jasnorzewska-milosc/$lektury$),
  ($lektury$wiersze-pawlikowskiej$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Opis cech twórczości (miniatura, autoironia) wynika z lektury tego jednego wiersza; wymaga potwierdzenia w opracowaniu.$lektury$, $lektury${"tekst":"Opis cech twórczości (miniatura, autoironia) wynika z lektury tego jednego wiersza; wymaga potwierdzenia w opracowaniu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/pawlikowska-jasnorzewska-milosc/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-poswiatowskiej$lektury$, $lektury$motyw$lektury$, 1, $lektury$*** (jestem Julią)$lektury$, $lektury$miłość z perspektywy kobiety. ZPE zestawia wiersz z tematem Julii i kobiecego spojrzenia na miłość. *** (jestem Julią). $lektury$, $lektury${"motyw":"miłość z perspektywy kobiety","przyklad":"ZPE zestawia wiersz z tematem Julii i kobiecego spojrzenia na miłość.","miejsce":"*** (jestem Julią)"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzanie/DQwna5d4Y$lektury$),
  ($lektury$wiersze-poswiatowskiej$lektury$, $lektury$motyw$lektury$, 2, $lektury$*** (jestem Julią)$lektury$, $lektury$literacka aluzja do Julii. Tytułowa tożsamość „Julii” nawiązuje do bohaterki Szekspira (według ZPE). *** (jestem Julią). $lektury$, $lektury${"motyw":"literacka aluzja do Julii","przyklad":"Tytułowa tożsamość „Julii” nawiązuje do bohaterki Szekspira (według ZPE).","miejsce":"*** (jestem Julią)"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzanie/DQwna5d4Y$lektury$),
  ($lektury$wiersze-poswiatowskiej$lektury$, $lektury$motyw$lektury$, 3, $lektury$*** (jestem Julią)$lektury$, $lektury$piętno choroby i krótkiego życia. Materiały podkreślają, że autorka zmarła w wieku 32 lat, a jej liryka ma tragiczne piętno choroby. *** (jestem Julią). $lektury$, $lektury${"motyw":"piętno choroby i krótkiego życia","przyklad":"Materiały podkreślają, że autorka zmarła w wieku 32 lat, a jej liryka ma tragiczne piętno choroby.","miejsce":"*** (jestem Julią)"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzanie/DQwna5d4Y$lektury$),
  ($lektury$wiersze-poswiatowskiej$lektury$, $lektury$utwor$lektury$, 1, $lektury$wiersz „(jestem Julią)”$lektury$, $lektury$*** (jestem Julią). Według ZPE wiersz jest używany obok tekstów o Szekspirowskiej Julii i kobiecym spojrzeniu na miłość; materiały zestawiają go m.in. z wierszem Pawlikowskiej-Jasnorzewskiej „Ofelia” i z wierszem Szymborskiej „Reszta”. Ostatnie słowa wiersza zawierają „odwieczną prawdę” o kobietach i miłości.$lektury$, $lektury${"tytul":"*** (jestem Julią)","miejsce":"wiersz „(jestem Julią)”","opis":"Według ZPE wiersz jest używany obok tekstów o Szekspirowskiej Julii i kobiecym spojrzeniu na miłość; materiały zestawiają go m.in. z wierszem Pawlikowskiej-Jasnorzewskiej „Ofelia” i z wierszem Szymborskiej „Reszta”. Ostatnie słowa wiersza zawierają „odwieczną prawdę” o kobietach i miłości."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzanie/DQwna5d4Y$lektury$),
  ($lektury$wiersze-poswiatowskiej$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Wprowadzenie ZPE „Jak Halina Poświatowska postrzega miłość?”.$lektury$, $lektury${"url":"https://zpe.gov.pl/a/wprowadzanie/DQwna5d4Y","rodzaj":"opracowanie","co":"Wprowadzenie ZPE „Jak Halina Poświatowska postrzega miłość?”."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzanie/DQwna5d4Y$lektury$),
  ($lektury$wiersze-poswiatowskiej$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Materiał ZPE „Miłość poza grób… Romeo i Julia” z odniesieniem do wiersza.$lektury$, $lektury${"url":"https://zpe.gov.pl/a/milosc-poza-grob-romeo-i-julia---najslynniejsi-kochankowie-swiata/D7KoH4RZN","rodzaj":"opracowanie","co":"Materiał ZPE „Miłość poza grób… Romeo i Julia” z odniesieniem do wiersza."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/milosc-poza-grob-romeo-i-julia---najslynniejsi-kochankowie-swiata/D7KoH4RZN$lektury$),
  ($lektury$wiersze-poswiatowskiej$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Utwory autora są chronione prawem autorskim (zmarł w 1967 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury).$lektury$, $lektury${"tekst":"Utwory autora są chronione prawem autorskim (zmarł w 1967 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzanie/DQwna5d4Y$lektury$),
  ($lektury$wiersze-poswiatowskiej$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów.$lektury$, $lektury${"tekst":"Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzanie/DQwna5d4Y$lektury$),
  ($lektury$wiersze-poswiatowskiej$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Treść wiersza nie była czytana; opis wynika z opisów lekcji ZPE.$lektury$, $lektury${"tekst":"Treść wiersza nie była czytana; opis wynika z opisów lekcji ZPE."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzanie/DQwna5d4Y$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-przybosia$lektury$, $lektury$motyw$lektury$, 1, $lektury$Z Tatr$lektury$, $lektury$śmierć w górach i żałoba. Wiersz powstał po śmierci ukochanej poety w Tatrach; w dedykacji jest mowa o taterniczce, która zginęła na Zamarłej Turni. Z Tatr. $lektury$, $lektury${"motyw":"śmierć w górach i żałoba","przyklad":"Wiersz powstał po śmierci ukochanej poety w Tatrach; w dedykacji jest mowa o taterniczce, która zginęła na Zamarłej Turni.","miejsce":"Z Tatr"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzenie/D6SdYAytN$lektury$),
  ($lektury$wiersze-przybosia$lektury$, $lektury$motyw$lektury$, 2, $lektury$Z Tatr$lektury$, $lektury$awangarda i poetyka obrazu. Wiersz łączy autorskie podejście do gór z poetyką awangardy (według ZPE). Z Tatr. $lektury$, $lektury${"motyw":"awangarda i poetyka obrazu","przyklad":"Wiersz łączy autorskie podejście do gór z poetyką awangardy (według ZPE).","miejsce":"Z Tatr"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzenie/D6SdYAytN$lektury$),
  ($lektury$wiersze-przybosia$lektury$, $lektury$motyw$lektury$, 3, $lektury$Z Tatr$lektury$, $lektury$zmiana podejścia do gór. W manifeście z 1926 r. Przyboś pisał o górze jako o „twórczym” przedmiocie dla turysty, inżyniera czy poety; po tragedii spojrzenie ma się zmienić (opis ZPE). Z Tatr. $lektury$, $lektury${"motyw":"zmiana podejścia do gór","przyklad":"W manifeście z 1926 r. Przyboś pisał o górze jako o „twórczym” przedmiocie dla turysty, inżyniera czy poety; po tragedii spojrzenie ma się zmienić (opis ZPE).","miejsce":"Z Tatr"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzenie/D6SdYAytN$lektury$),
  ($lektury$wiersze-przybosia$lektury$, $lektury$utwor$lektury$, 1, $lektury$przykład z katalogu; wiersz poświęcony taterniczce$lektury$, $lektury$Z Tatr. Wiersz poświęcony pamięci taterniczki, która zginęła na Zamarłej Turni; według ZPE chodzi o Marzenę Skotnicównę, ukochaną poety, która zginęła z siostrą na południowej ścianie Zamarłej Turni. Wiersz jest przykładem poetyki awangardowej, a materiał ZPE omawia w nim m.in. „ekwiwalentyzację uczuć” (wyrażanie uczuć przez obrazy). Treść wiersza nie została tu sprawdzona.$lektury$, $lektury${"tytul":"Z Tatr","miejsce":"przykład z katalogu; wiersz poświęcony taterniczce","opis":"Wiersz poświęcony pamięci taterniczki, która zginęła na Zamarłej Turni; według ZPE chodzi o Marzenę Skotnicównę, ukochaną poety, która zginęła z siostrą na południowej ścianie Zamarłej Turni. Wiersz jest przykładem poetyki awangardowej, a materiał ZPE omawia w nim m.in. „ekwiwalentyzację uczuć” (wyrażanie uczuć przez obrazy). Treść wiersza nie została tu sprawdzona."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzenie/D6SdYAytN$lektury$),
  ($lektury$wiersze-przybosia$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Wprowadzenie ZPE do wiersza „Z Tatr”: okoliczności powstania (śmierć taterniczki), cele lekcji (poetyka awangardowa, ekwiwalentyzacja uczuć).$lektury$, $lektury${"url":"https://zpe.gov.pl/a/wprowadzenie/D6SdYAytN","rodzaj":"opracowanie","co":"Wprowadzenie ZPE do wiersza „Z Tatr”: okoliczności powstania (śmierć taterniczki), cele lekcji (poetyka awangardowa, ekwiwalentyzacja uczuć)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzenie/D6SdYAytN$lektury$),
  ($lektury$wiersze-przybosia$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Przyboś zmarł w 1970 r., jego wiersze są chronione prawem autorskim; tekstu i cytatów nie podano, treść wiersza opisano tylko ogólnie na podstawie wprowadzenia ZPE.$lektury$, $lektury${"tekst":"Przyboś zmarł w 1970 r., jego wiersze są chronione prawem autorskim; tekstu i cytatów nie podano, treść wiersza opisano tylko ogólnie na podstawie wprowadzenia ZPE."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzenie/D6SdYAytN$lektury$),
  ($lektury$wiersze-przybosia$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Imię i okoliczności śmierci taterniczki (Marzena Skotnicówna, Zamarła Turnia) pochodzą ze wprowadzenia ZPE i nie były sprawdzane gdzie indziej.$lektury$, $lektury${"tekst":"Imię i okoliczności śmierci taterniczki (Marzena Skotnicówna, Zamarła Turnia) pochodzą ze wprowadzenia ZPE i nie były sprawdzane gdzie indziej."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzenie/D6SdYAytN$lektury$),
  ($lektury$wiersze-przybosia$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony.$lektury$, $lektury${"tekst":"Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/wprowadzenie/D6SdYAytN$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-rozewicza$lektury$, $lektury$motyw$lektury$, 1, $lektury$Ocalony$lektury$, $lektury$człowiek po wojnie. Bohater wiersza to ktoś, kto przeżył wojnę i próbuje żyć po katastrofie (według ZPE). Ocalony. $lektury$, $lektury${"motyw":"człowiek po wojnie","przyklad":"Bohater wiersza to ktoś, kto przeżył wojnę i próbuje żyć po katastrofie (według ZPE).","miejsce":"Ocalony"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/pdf/P13p4pPKr$lektury$),
  ($lektury$wiersze-rozewicza$lektury$, $lektury$motyw$lektury$, 2, $lektury$Ocalony$lektury$, $lektury$kryzys wartości. Wiersz stawia pytanie, czy po wojnie można odbudować wartości (według ZPE). Ocalony. $lektury$, $lektury${"motyw":"kryzys wartości","przyklad":"Wiersz stawia pytanie, czy po wojnie można odbudować wartości (według ZPE).","miejsce":"Ocalony"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/pdf/P13p4pPKr$lektury$),
  ($lektury$wiersze-rozewicza$lektury$, $lektury$motyw$lektury$, 3, $lektury$Ocalony$lektury$, $lektury$wątpliwości religijne. ZPE wskazuje na wątpliwości religijne i biblijne aluzje w wierszu. Ocalony. $lektury$, $lektury${"motyw":"wątpliwości religijne","przyklad":"ZPE wskazuje na wątpliwości religijne i biblijne aluzje w wierszu.","miejsce":"Ocalony"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/pdf/P13p4pPKr$lektury$),
  ($lektury$wiersze-rozewicza$lektury$, $lektury$utwor$lektury$, 1, $lektury$z tomu „Niepokój” (1947)$lektury$, $lektury$Ocalony. Według ZPE wiersz ukazał się w tomie „Niepokój” z 1947 r., pierwszym drukowanym zbiorze poety. Tytuł wskazuje na pojedynczego człowieka, który przeżył wojnę; wiersz porusza problematykę moralną i pytanie, czy można odbudować wartości po wojnie. Materiały podkreślają wątpliwości religijne i biblijne aluzje.$lektury$, $lektury${"tytul":"Ocalony","miejsce":"z tomu „Niepokój” (1947)","opis":"Według ZPE wiersz ukazał się w tomie „Niepokój” z 1947 r., pierwszym drukowanym zbiorze poety. Tytuł wskazuje na pojedynczego człowieka, który przeżył wojnę; wiersz porusza problematykę moralną i pytanie, czy można odbudować wartości po wojnie. Materiały podkreślają wątpliwości religijne i biblijne aluzje."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/pdf/P13p4pPKr$lektury$),
  ($lektury$wiersze-rozewicza$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Materiał ZPE „Czy można pisać poezję po Oświęcimiu? O Ocalonym Tadeusza Różewicza” (czytany jako wynik wyszukiwania).$lektury$, $lektury${"url":"https://zpe.gov.pl/pdf/P13p4pPKr","rodzaj":"opracowanie","co":"Materiał ZPE „Czy można pisać poezję po Oświęcimiu? O Ocalonym Tadeusza Różewicza” (czytany jako wynik wyszukiwania)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/pdf/P13p4pPKr$lektury$),
  ($lektury$wiersze-rozewicza$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Materiał ZPE „Jak dalej żyć? Kondycja człowieka po katastrofie wojny”.$lektury$, $lektury${"url":"https://zpe.gov.pl/a/przeczytaj/DqYv5BPbB","rodzaj":"opracowanie","co":"Materiał ZPE „Jak dalej żyć? Kondycja człowieka po katastrofie wojny”."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/DqYv5BPbB$lektury$),
  ($lektury$wiersze-rozewicza$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Utwory autora są chronione prawem autorskim (zmarł w 2014 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury).$lektury$, $lektury${"tekst":"Utwory autora są chronione prawem autorskim (zmarł w 2014 r.), więc nie podano tekstu ani cytatów; opis opiera się na materiałach ZPE (wyniki wyszukiwania i streszczenia stron, nie pełne lektury)."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/pdf/P13p4pPKr$lektury$),
  ($lektury$wiersze-rozewicza$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów.$lektury$, $lektury${"tekst":"Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/pdf/P13p4pPKr$lektury$),
  ($lektury$wiersze-rozewicza$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Szczegółowa treść wiersza nie była czytana; opis tylko z ogólnych streszczeń ZPE.$lektury$, $lektury${"tekst":"Szczegółowa treść wiersza nie była czytana; opis tylko z ogólnych streszczeń ZPE."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/pdf/P13p4pPKr$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-staffa$lektury$, $lektury$motyw$lektury$, 1, $lektury$Deszcz jesienny$lektury$, $lektury$melancholia i bezsens istnienia. Dominujący nastrój wiersza to smutek, przygnębienie i poczucie bezsensu (według ZPE). Deszcz jesienny. $lektury$, $lektury${"motyw":"melancholia i bezsens istnienia","przyklad":"Dominujący nastrój wiersza to smutek, przygnębienie i poczucie bezsensu (według ZPE).","miejsce":"Deszcz jesienny"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/Dd8dU10nQ$lektury$),
  ($lektury$wiersze-staffa$lektury$, $lektury$motyw$lektury$, 2, $lektury$Deszcz jesienny$lektury$, $lektury$onomatopeje i dźwięk deszczu. Onomatopeje i powtórzenia naśladują brzmienie deszczu (według ZPE). Deszcz jesienny. $lektury$, $lektury${"motyw":"onomatopeje i dźwięk deszczu","przyklad":"Onomatopeje i powtórzenia naśladują brzmienie deszczu (według ZPE).","miejsce":"Deszcz jesienny"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/Dd8dU10nQ$lektury$),
  ($lektury$wiersze-staffa$lektury$, $lektury$motyw$lektury$, 3, $lektury$Deszcz jesienny$lektury$, $lektury$dekadentyzm Młodej Polski. Wiersz pochodzi z wczesnej twórczości Staffa, naznaczonej dekadentyzmem Młodej Polski. Deszcz jesienny. $lektury$, $lektury${"motyw":"dekadentyzm Młodej Polski","przyklad":"Wiersz pochodzi z wczesnej twórczości Staffa, naznaczonej dekadentyzmem Młodej Polski.","miejsce":"Deszcz jesienny"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/Dd8dU10nQ$lektury$),
  ($lektury$wiersze-staffa$lektury$, $lektury$motyw$lektury$, 4, $lektury$Deszcz jesienny$lektury$, $lektury$kolor, obraz i oniryzm. ZPE ćwiczy m.in. analizę koloru, obrazów i elementów oniryzmu w wierszu. Deszcz jesienny. $lektury$, $lektury${"motyw":"kolor, obraz i oniryzm","przyklad":"ZPE ćwiczy m.in. analizę koloru, obrazów i elementów oniryzmu w wierszu.","miejsce":"Deszcz jesienny"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/Dd8dU10nQ$lektury$),
  ($lektury$wiersze-staffa$lektury$, $lektury$utwor$lektury$, 1, $lektury$z tomu „Dzień duszy” (1903)$lektury$, $lektury$Deszcz jesienny. Według ZPE wiersz pochodzi z drugiego tomu poezji Staffa „Dzień duszy” z 1903 r. i wyraża wpływ dekadentyzmu Młodej Polski. Dominujący nastrój to smutek, przygnębienie, melancholia i poczucie bezsensu istnienia; w warstwie brzmieniowej pojawiają się onomatopeje i powtórzenia naśladujące deszcz. ZPE zestawia wiersz z jesiennym wierszem Verlaine'a.$lektury$, $lektury${"tytul":"Deszcz jesienny","miejsce":"z tomu „Dzień duszy” (1903)","opis":"Według ZPE wiersz pochodzi z drugiego tomu poezji Staffa „Dzień duszy” z 1903 r. i wyraża wpływ dekadentyzmu Młodej Polski. Dominujący nastrój to smutek, przygnębienie, melancholia i poczucie bezsensu istnienia; w warstwie brzmieniowej pojawiają się onomatopeje i powtórzenia naśladujące deszcz. ZPE zestawia wiersz z jesiennym wierszem Verlaine'a."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/Dd8dU10nQ$lektury$),
  ($lektury$wiersze-staffa$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Materiał ZPE „Motywy antyczne i chrześcijańskie w twórczości Leopolda Staffa”.$lektury$, $lektury${"url":"https://zpe.gov.pl/a/przeczytaj/Dd8dU10nQ","rodzaj":"opracowanie","co":"Materiał ZPE „Motywy antyczne i chrześcijańskie w twórczości Leopolda Staffa”."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/Dd8dU10nQ$lektury$),
  ($lektury$wiersze-staffa$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Ćwiczenia ZPE „Wpływ rytmu i melodii wiersza na jego znaczenie”.$lektury$, $lektury${"url":"https://zpe.gov.pl/a/sprawdz-sie/DM1mCqM5i","rodzaj":"opracowanie","co":"Ćwiczenia ZPE „Wpływ rytmu i melodii wiersza na jego znaczenie”."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/sprawdz-sie/DM1mCqM5i$lektury$),
  ($lektury$wiersze-staffa$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Staff zmarł w 1957 r., więc jego twórczość jest chroniona prawem autorskim do końca 2027 r. (70 lat po śmierci); nie podano tekstu ani cytatów.$lektury$, $lektury${"tekst":"Staff zmarł w 1957 r., więc jego twórczość jest chroniona prawem autorskim do końca 2027 r. (70 lat po śmierci); nie podano tekstu ani cytatów."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/Dd8dU10nQ$lektury$),
  ($lektury$wiersze-staffa$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów.$lektury$, $lektury${"tekst":"Wybór wierszy w wymaganiach CKE poza przykładem z katalogu nie został sprawdzony; nie opracowano innych utworów."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/Dd8dU10nQ$lektury$),
  ($lektury$wiersze-staffa$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Opis oparty tylko na podsumowaniach wyników wyszukiwania ZPE; nie sprawdzono, które dokładnie wiersze zawiera materiał.$lektury$, $lektury${"tekst":"Opis oparty tylko na podsumowaniach wyników wyszukiwania ZPE; nie sprawdzono, które dokładnie wiersze zawiera materiał."}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/przeczytaj/Dd8dU10nQ$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-szymborskiej$lektury$, $lektury$motyw$lektury$, 1, $lektury$Nic dwa razy$lektury$, $lektury$przemijanie i jednorazowość życia. Wiersz podkreśla przemijalność życia i jednorazowość chwil (według ZPE). Nic dwa razy. $lektury$, $lektury${"motyw":"przemijanie i jednorazowość życia","przyklad":"Wiersz podkreśla przemijalność życia i jednorazowość chwil (według ZPE).","miejsce":"Nic dwa razy"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/nic-dwa-razy-o-poezji-wislawy-szymborskiej/DbyoJxpeR$lektury$),
  ($lektury$wiersze-szymborskiej$lektury$, $lektury$motyw$lektury$, 2, $lektury$Nic dwa razy$lektury$, $lektury$nawiązanie do Heraklita. ZPE wiąże wiersz z myślą Heraklita „panta rhei”. Nic dwa razy. $lektury$, $lektury${"motyw":"nawiązanie do Heraklita","przyklad":"ZPE wiąże wiersz z myślą Heraklita „panta rhei”.","miejsce":"Nic dwa razy"}$lektury$::jsonb, $lektury$https://zpe.gov.pl/a/nic-dwa-razy-o-poezji-wislawy-szymborskiej/DbyoJxpeR$lektury$),
