insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-tetmajera$lektury$, $lektury$motyw$lektury$, 1, $lektury$Hymn do Nirwany$lektury$, $lektury$pragnienie nirwany i unicestwienia. Mówiący prosi o oddech nirwany, który ma go unicestwić, i o to, by nie pamiętać, że żył. Hymn do Nirwany. Twym unicestwiającym oddechem pierś niech sycę$lektury$, $lektury${"motyw":"pragnienie nirwany i unicestwienia","przyklad":"Mówiący prosi o oddech nirwany, który ma go unicestwić, i o to, by nie pamiętać, że żył.","miejsce":"Hymn do Nirwany","cytat":"Twym unicestwiającym oddechem pierś niech sycę"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-nirwany/$lektury$),
  ($lektury$wiersze-tetmajera$lektury$, $lektury$motyw$lektury$, 2, $lektury$Hymn do Nirwany$lektury$, $lektury$zmęczenie światem i pesymizm. Wiersz opisuje ludzką podłość, która bryzga „kałem w źrenice”, i dusza ciągle konwulsyjnie się tarza. Hymn do Nirwany. Z otchłani klęsk i cierpień podnoszę głos do ciebie,$lektury$, $lektury${"motyw":"zmęczenie światem i pesymizm","przyklad":"Wiersz opisuje ludzką podłość, która bryzga „kałem w źrenice”, i dusza ciągle konwulsyjnie się tarza.","miejsce":"Hymn do Nirwany","cytat":"Z otchłani klęsk i cierpień podnoszę głos do ciebie,"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-nirwany/$lektury$),
  ($lektury$wiersze-tetmajera$lektury$, $lektury$motyw$lektury$, 3, $lektury$Hymn do Nirwany$lektury$, $lektury$parodia modlitwy. Fragmenty „Przyjdź twe królestwo jako na ziemi, tak i w niebie” naśladują chrześcijańską modlitwę, adresując ją do Nirwany. Hymn do Nirwany. Przyjdź twe królestwo jako na ziemi, tak i w niebie$lektury$, $lektury${"motyw":"parodia modlitwy","przyklad":"Fragmenty „Przyjdź twe królestwo jako na ziemi, tak i w niebie” naśladują chrześcijańską modlitwę, adresując ją do Nirwany.","miejsce":"Hymn do Nirwany","cytat":"Przyjdź twe królestwo jako na ziemi, tak i w niebie"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-nirwany/$lektury$),
  ($lektury$wiersze-tetmajera$lektury$, $lektury$motyw$lektury$, 4, $lektury$Hymn do Nirwany$lektury$, $lektury$dekadentyzm. Utwór wyraża postawę typową dla dekadentyzmu: niechęć do życia, ucieczka w nicość. Hymn do Nirwany. $lektury$, $lektury${"motyw":"dekadentyzm","przyklad":"Utwór wyraża postawę typową dla dekadentyzmu: niechęć do życia, ucieczka w nicość.","miejsce":"Hymn do Nirwany"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-nirwany/$lektury$),
  ($lektury$wiersze-tetmajera$lektury$, $lektury$utwor$lektury$, 1, $lektury$cały wiersz$lektury$, $lektury$Hymn do Nirwany. Wiersz zbudowany jak modlitwa-parodia „Ojcze nasz”, z refrenem „Nirwano!” po każdym dwuwersie. Mówiący, udręczony ludzką podłością, błaga Nirwanę o zapomnienie, wyzwolenie od pamięci i cierpienia oraz o pochłonięcie w nicość. Typowy utwór dekadentyzmu Młodej Polski.$lektury$, $lektury${"tytul":"Hymn do Nirwany","miejsce":"cały wiersz","opis":"Wiersz zbudowany jak modlitwa-parodia „Ojcze nasz”, z refrenem „Nirwano!” po każdym dwuwersie. Mówiący, udręczony ludzką podłością, błaga Nirwanę o zapomnienie, wyzwolenie od pamięci i cierpienia oraz o pochłonięcie w nicość. Typowy utwór dekadentyzmu Młodej Polski."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-nirwany/$lektury$),
  ($lektury$wiersze-tetmajera$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pełny tekst; cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/hymn-do-nirwany/","rodzaj":"utwór","co":"Pełny tekst; cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-nirwany/$lektury$),
  ($lektury$wiersze-tetmajera$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Tetmajer zmarł w 1940 r. (domena publiczna). Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony (np. „Melodia mgieł nocnych”, „Evviva l’arte”).$lektury$, $lektury${"tekst":"Tetmajer zmarł w 1940 r. (domena publiczna). Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony (np. „Melodia mgieł nocnych”, „Evviva l’arte”)."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-nirwany/$lektury$),
  ($lektury$wiersze-tetmajera$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Zaliczenie utworu do dekadentyzmu i buddyjskie pojęcie nirwany są tu opisane z lektury samego tekstu; do potwierdzenia w opracowaniu.$lektury$, $lektury${"tekst":"Zaliczenie utworu do dekadentyzmu i buddyjskie pojęcie nirwany są tu opisane z lektury samego tekstu; do potwierdzenia w opracowaniu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/hymn-do-nirwany/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wiersze-tuwima$lektury$, $lektury$motyw$lektury$, 1, $lektury$Do prostego człowieka, strofa I–II$lektury$, $lektury$krytyka propagandy wojennej. Plakaty „do ludności” i „do żołnierzy” oraz hasła o ojczyźnie, chwale i rubieży mają skłonić ludzi do walki. Do prostego człowieka, strofa I–II. Wiedz, że na trwogę biją w dzwony$lektury$, $lektury${"motyw":"krytyka propagandy wojennej","przyklad":"Plakaty „do ludności” i „do żołnierzy” oraz hasła o ojczyźnie, chwale i rubieży mają skłonić ludzi do walki.","miejsce":"Do prostego człowieka, strofa I–II","cytat":"Wiedz, że na trwogę biją w dzwony"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/tuwim-do-prostego-czlowieka/$lektury$),
  ($lektury$wiersze-tuwima$lektury$, $lektury$motyw$lektury$, 2, $lektury$Do prostego człowieka, strofa III$lektury$, $lektury$wojna jako interes elit. Wiersz mówi, że wojna wybucha, bo komuś „nafta z ziemi sikła”, a w bankach „coś nie sztymuje”. Do prostego człowieka, strofa III. Twoja jest krew, a ich jest nafta!$lektury$, $lektury${"motyw":"wojna jako interes elit","przyklad":"Wiersz mówi, że wojna wybucha, bo komuś „nafta z ziemi sikła”, a w bankach „coś nie sztymuje”.","miejsce":"Do prostego człowieka, strofa III","cytat":"Twoja jest krew, a ich jest nafta!"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/tuwim-do-prostego-czlowieka/$lektury$),
  ($lektury$wiersze-tuwima$lektury$, $lektury$motyw$lektury$, 3, $lektury$Do prostego człowieka, strofa III$lektury$, $lektury$apel do pokoju i oporu. Końcowy wers wzywa żołnierza do buntu przeciw rozkazom. Do prostego człowieka, strofa III. Rżnij karabinem w bruk ulicy!$lektury$, $lektury${"motyw":"apel do pokoju i oporu","przyklad":"Końcowy wers wzywa żołnierza do buntu przeciw rozkazom.","miejsce":"Do prostego człowieka, strofa III","cytat":"Rżnij karabinem w bruk ulicy!"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/tuwim-do-prostego-czlowieka/$lektury$),
  ($lektury$wiersze-tuwima$lektury$, $lektury$motyw$lektury$, 4, $lektury$Do prostego człowieka, strofa II$lektury$, $lektury$krytyka patriotycznej retoryki. Biskup, pastor i rabin błogosławią karabin, a „stado dzikich bab” obrzuca żołnierzy kwiatami; można odczytać to jako krytykę fałszywego patriotyzmu. Do prostego człowieka, strofa II. $lektury$, $lektury${"motyw":"krytyka patriotycznej retoryki","przyklad":"Biskup, pastor i rabin błogosławią karabin, a „stado dzikich bab” obrzuca żołnierzy kwiatami; można odczytać to jako krytykę fałszywego patriotyzmu.","miejsce":"Do prostego człowieka, strofa II"}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/tuwim-do-prostego-czlowieka/$lektury$),
  ($lektury$wiersze-tuwima$lektury$, $lektury$utwor$lektury$, 1, $lektury$cały wiersz$lektury$, $lektury$Do prostego człowieka. Wiersz-apel antywojenny. Mówiący wylicza, jak władza i prasa przygotowują wojnę (plakaty, hasła, błogosławieństwo duchownych, „kolorowe godło”), po czym zwraca się do „prostego człowieka”: wojna służy interesom „króli z panami brzuchatymi” (nafta, banki, cło). Kończy wezwaniem do oporu.$lektury$, $lektury${"tytul":"Do prostego człowieka","miejsce":"cały wiersz","opis":"Wiersz-apel antywojenny. Mówiący wylicza, jak władza i prasa przygotowują wojnę (plakaty, hasła, błogosławieństwo duchownych, „kolorowe godło”), po czym zwraca się do „prostego człowieka”: wojna służy interesom „króli z panami brzuchatymi” (nafta, banki, cło). Kończy wezwaniem do oporu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/tuwim-do-prostego-czlowieka/$lektury$),
  ($lektury$wiersze-tuwima$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Pełny tekst; cytaty sprawdzone.$lektury$, $lektury${"url":"https://wolnelektury.pl/katalog/lektura/tuwim-do-prostego-czlowieka/","rodzaj":"utwór","co":"Pełny tekst; cytaty sprawdzone."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/tuwim-do-prostego-czlowieka/$lektury$),
  ($lektury$wiersze-tuwima$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Tuwim zmarł w 1953 r., więc jego utwory weszły do domeny publicznej w 2024 r.; Wolne Lektury udostępniają ten wiersz — sprawdzono wyłącznie ten tekst.$lektury$, $lektury${"tekst":"Tuwim zmarł w 1953 r., więc jego utwory weszły do domeny publicznej w 2024 r.; Wolne Lektury udostępniają ten wiersz — sprawdzono wyłącznie ten tekst."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/tuwim-do-prostego-czlowieka/$lektury$),
  ($lektury$wiersze-tuwima$lektury$, $lektury$weryfikacja$lektury$, 2, $lektury$$lektury$, $lektury$Data powstania i okoliczności pierwodruku nie zostały sprawdzone — do weryfikacji.$lektury$, $lektury${"tekst":"Data powstania i okoliczności pierwodruku nie zostały sprawdzone — do weryfikacji."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/tuwim-do-prostego-czlowieka/$lektury$),
  ($lektury$wiersze-tuwima$lektury$, $lektury$weryfikacja$lektury$, 3, $lektury$$lektury$, $lektury$Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony.$lektury$, $lektury${"tekst":"Wybór wierszy CKE poza przykładem z katalogu nie został sprawdzony."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/tuwim-do-prostego-czlowieka/$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$wyznania-augustyna$lektury$, $lektury$motyw$lektury$, 1, $lektury$ks. I, rozdz. 1 i ks. II, rozdz. 1$lektury$, $lektury$wyznanie jako modlitwa. Augustyn od początku zwraca się do Boga, a wracając do własnej młodości wyjaśnia sens bolesnego rozpamiętywania przeszłości. ks. I, rozdz. 1 i ks. II, rozdz. 1. $lektury$, $lektury${"motyw":"wyznanie jako modlitwa","przyklad":"Augustyn od początku zwraca się do Boga, a wracając do własnej młodości wyjaśnia sens bolesnego rozpamiętywania przeszłości.","miejsce":"ks. I, rozdz. 1 i ks. II, rozdz. 1"}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$motyw$lektury$, 2, $lektury$ks. II, rozdz. 2–3$lektury$, $lektury$dojrzewanie i nacisk otoczenia. Augustyn przywołuje przestrogę matki i wspomina, że wśród rówieśników wstydził się uchodzić za mniej występnego. ks. II, rozdz. 2–3. $lektury$, $lektury${"motyw":"dojrzewanie i nacisk otoczenia","przyklad":"Augustyn przywołuje przestrogę matki i wspomina, że wśród rówieśników wstydził się uchodzić za mniej występnego.","miejsce":"ks. II, rozdz. 2–3"}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$motyw$lektury$, 3, $lektury$ks. II, rozdz. 4 i 6$lektury$, $lektury$kradzież i przyjemność przekroczenia. Augustyn wspomina kradzież gruszek, których nie potrzebował, żeby zbadać przyjemność, jaką dawał sam zakazany czyn. ks. II, rozdz. 4 i 6. $lektury$, $lektury${"motyw":"kradzież i przyjemność przekroczenia","przyklad":"Augustyn wspomina kradzież gruszek, których nie potrzebował, żeby zbadać przyjemność, jaką dawał sam zakazany czyn.","miejsce":"ks. II, rozdz. 4 i 6"}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$motyw$lektury$, 4, $lektury$ks. II, rozdz. 5–6$lektury$, $lektury$pozór dobra. Autor zastanawia się, jak człowiek szuka w niewłaściwych czynach zniekształconego odpowiednika dóbr, których pragnie. ks. II, rozdz. 5–6. $lektury$, $lektury${"motyw":"pozór dobra","przyklad":"Autor zastanawia się, jak człowiek szuka w niewłaściwych czynach zniekształconego odpowiednika dóbr, których pragnie.","miejsce":"ks. II, rozdz. 5–6"}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$motyw$lektury$, 5, $lektury$ks. II, rozdz. 8–9$lektury$, $lektury$wspólnota i odpowiedzialność. Augustyn dochodzi do wniosku, że sam nie poszedłby po gruszki i że wspólnicy mieli wpływ na jego decyzję. ks. II, rozdz. 8–9. $lektury$, $lektury${"motyw":"wspólnota i odpowiedzialność","przyklad":"Augustyn dochodzi do wniosku, że sam nie poszedłby po gruszki i że wspólnicy mieli wpływ na jego decyzję.","miejsce":"ks. II, rozdz. 8–9"}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$motyw$lektury$, 6, $lektury$ks. II, rozdz. 7 i 10$lektury$, $lektury$łaska i pamięć. Augustyn dziękuje za przebaczenie i kończy księgę zwrotem do Boga, w którym szuka oparcia po rozważeniu własnych błędów. ks. II, rozdz. 7 i 10. $lektury$, $lektury${"motyw":"łaska i pamięć","przyklad":"Augustyn dziękuje za przebaczenie i kończy księgę zwrotem do Boga, w którym szuka oparcia po rozważeniu własnych błędów.","miejsce":"ks. II, rozdz. 7 i 10"}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$motyw$lektury$, 7, $lektury$ks. VIII, rozdz. 11–12$lektury$, $lektury$konflikt woli i nawrócenie. W ogrodzie Augustyn odczuwa rozdźwięk między zamiarem zmiany a dotychczasowymi przyzwyczajeniami, po czym odczytuje wezwanie zasłyszane z sąsiedztwa jako polecenie lektury tekstu Pawła. ks. VIII, rozdz. 11–12. $lektury$, $lektury${"motyw":"konflikt woli i nawrócenie","przyklad":"W ogrodzie Augustyn odczuwa rozdźwięk między zamiarem zmiany a dotychczasowymi przyzwyczajeniami, po czym odczytuje wezwanie zasłyszane z sąsiedztwa jako polecenie lektury tekstu Pawła.","miejsce":"ks. VIII, rozdz. 11–12"}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$motyw$lektury$, 8, $lektury$ks. XI, rozdz. 20 i 26–28$lektury$, $lektury$czas przeżywany. Rozróżnienie pamięci, uwagi i oczekiwania pozwala Augustynowi mówić o przeszłości i przyszłości z perspektywy teraźniejszego doświadczenia. ks. XI, rozdz. 20 i 26–28. $lektury$, $lektury${"motyw":"czas przeżywany","przyklad":"Rozróżnienie pamięci, uwagi i oczekiwania pozwala Augustynowi mówić o przeszłości i przyszłości z perspektywy teraźniejszego doświadczenia.","miejsce":"ks. XI, rozdz. 20 i 26–28"}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$utwor$lektury$, 1, $lektury$ks. I, rozdz. 1$lektury$, $lektury$Modlitwa otwierająca dzieło. Augustyn pyta o możliwość szukania Boga i przedstawia ludzkie pragnienie spoczynku w Nim.$lektury$, $lektury${"tytul":"Modlitwa otwierająca dzieło","miejsce":"ks. I, rozdz. 1","opis":"Augustyn pyta o możliwość szukania Boga i przedstawia ludzkie pragnienie spoczynku w Nim."}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$utwor$lektury$, 2, $lektury$ks. II, rozdz. 1–3$lektury$, $lektury$Powrót do młodości. Augustyn wyjaśnia, czemu wraca do przeszłości, i opisuje wpływ obyczajów rówieśników na własne zachowanie.$lektury$, $lektury${"tytul":"Powrót do młodości","miejsce":"ks. II, rozdz. 1–3","opis":"Augustyn wyjaśnia, czemu wraca do przeszłości, i opisuje wpływ obyczajów rówieśników na własne zachowanie."}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$utwor$lektury$, 3, $lektury$ks. II, rozdz. 4–6$lektury$, $lektury$Kradzież gruszek i pobudki. Opowieść o drobnym występku służy rozważaniu o złu, przyjemności przekroczenia i dobrach pozornych.$lektury$, $lektury${"tytul":"Kradzież gruszek i pobudki","miejsce":"ks. II, rozdz. 4–6","opis":"Opowieść o drobnym występku służy rozważaniu o złu, przyjemności przekroczenia i dobrach pozornych."}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$utwor$lektury$, 4, $lektury$ks. II, rozdz. 7–10$lektury$, $lektury$Towarzystwo, przebaczenie i zakończenie modlitwy. Augustyn dziękuje za przebaczenie, bada swój udział w czynie grupy i kończy modlitwą.$lektury$, $lektury${"tytul":"Towarzystwo, przebaczenie i zakończenie modlitwy","miejsce":"ks. II, rozdz. 7–10","opis":"Augustyn dziękuje za przebaczenie, bada swój udział w czynie grupy i kończy modlitwą."}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$utwor$lektury$, 5, $lektury$ks. VIII, rozdz. 11–12$lektury$, $lektury$Nawrócenie w ogrodzie. Opór przed zmianą życia ustępuje w chwili, w której Augustyn odczytuje ustęp z Listu do Rzymian.$lektury$, $lektury${"tytul":"Nawrócenie w ogrodzie","miejsce":"ks. VIII, rozdz. 11–12","opis":"Opór przed zmianą życia ustępuje w chwili, w której Augustyn odczytuje ustęp z Listu do Rzymian."}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$utwor$lektury$, 6, $lektury$ks. XI, rozdz. 20 i 26–28$lektury$, $lektury$Rozważania o czasie. Augustyn wiąże doświadczenie czasu z czynnościami umysłu: pamiętaniem, uwagą i oczekiwaniem.$lektury$, $lektury${"tytul":"Rozważania o czasie","miejsce":"ks. XI, rozdz. 20 i 26–28","opis":"Augustyn wiąże doświadczenie czasu z czynnościami umysłu: pamiętaniem, uwagą i oczekiwaniem."}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$zrodlo$lektury$, 1, $lektury$$lektury$, $lektury$Informator wymienia fragmenty Wyznań w zakresie rozszerzonym.$lektury$, $lektury${"url":"https://bip.cke.gov.pl/attachments/download/10092","rodzaj":"opracowanie","co":"Informator wymienia fragmenty Wyznań w zakresie rozszerzonym."}$lektury$::jsonb, $lektury$https://bip.cke.gov.pl/attachments/download/10092$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$zrodlo$lektury$, 2, $lektury$$lektury$, $lektury$Księga II w przekładzie Piotra Franciszka Pękalskiego; sprawdzono rozdziały 1–10 i przebieg rozważań o kradzieży.$lektury$, $lektury${"url":"https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87","rodzaj":"utwór","co":"Księga II w przekładzie Piotra Franciszka Pękalskiego; sprawdzono rozdziały 1–10 i przebieg rozważań o kradzieży."}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$zrodlo$lektury$, 3, $lektury$$lektury$, $lektury$Łaciński tekst modlitwy otwierającej Wyznania.$lektury$, $lektury${"url":"https://www.augustinus.it/latino/confessioni/conf_01_libro.htm","rodzaj":"utwór","co":"Łaciński tekst modlitwy otwierającej Wyznania."}$lektury$::jsonb, $lektury$https://www.augustinus.it/latino/confessioni/conf_01_libro.htm$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$zrodlo$lektury$, 4, $lektury$$lektury$, $lektury$Łaciński tekst księgi VIII; sprawdzono opis nawrócenia z rozdziałów 11–12.$lektury$, $lektury${"url":"https://www.augustinus.it/latino/confessioni/conf_08_libro.htm","rodzaj":"utwór","co":"Łaciński tekst księgi VIII; sprawdzono opis nawrócenia z rozdziałów 11–12."}$lektury$::jsonb, $lektury$https://www.augustinus.it/latino/confessioni/conf_08_libro.htm$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$zrodlo$lektury$, 5, $lektury$$lektury$, $lektury$Łaciński tekst księgi XI, rozważania o czasie i doświadczeniu umysłu.$lektury$, $lektury${"url":"https://www.augustinus.it/latino/confessioni/conf_11_libro.htm","rodzaj":"utwór","co":"Łaciński tekst księgi XI, rozważania o czasie i doświadczeniu umysłu."}$lektury$::jsonb, $lektury$https://www.augustinus.it/latino/confessioni/conf_11_libro.htm$lektury$),
  ($lektury$wyznania-augustyna$lektury$, $lektury$weryfikacja$lektury$, 1, $lektury$$lektury$, $lektury$Informator nie wylicza fragmentów; księga II jest przykładem katalogowym, a ustępy z ksiąg I, VIII i XI uzupełniają wybór.$lektury$, $lektury${"tekst":"Informator nie wylicza fragmentów; księga II jest przykładem katalogowym, a ustępy z ksiąg I, VIII i XI uzupełniają wybór."}$lektury$::jsonb, $lektury$https://pl.wikisource.org/wiki/Wyznania_(Augustyn_z_Hippony,_1847)/Ksi%C4%99ga_Druga/ca%C5%82o%C5%9B%C4%87$lektury$);
insert into private.lektury_elementy (utwor, rodzaj, nr, miejsce, tekst, dane, zrodlo_url) values
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 1, $lektury$początek noweli$lektury$, $lektury$początek noweli. Ramzes, lekarz z Karnaku. Egipt, pałac Ramzesa. Stuletni, ciężko chory faraon Ramzes każe najmędrszemu lekarzowi ze świątyni w Karnaku przyrządzić lekarstwo, które albo zabije, albo od razu wyleczy.$lektury$, $lektury${"nr":1,"miejsce":"początek noweli","kto":["Ramzes","lekarz z Karnaku"],"gdzie":"Egipt, pałac Ramzesa","opis":"Stuletni, ciężko chory faraon Ramzes każe najmędrszemu lekarzowi ze świątyni w Karnaku przyrządzić lekarstwo, które albo zabije, albo od razu wyleczy."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 2, $lektury$początek noweli$lektury$, $lektury$początek noweli. Ramzes, lekarz z Karnaku. Egipt, pałac Ramzesa. Lekarz się waha, ale Ramzes nakazuje spełnić rozkaz, przypominając, że żyje jego trzydziestoletni wnuk i następca, Horus; wypija lekarstwo.$lektury$, $lektury${"nr":2,"miejsce":"początek noweli","kto":["Ramzes","lekarz z Karnaku"],"gdzie":"Egipt, pałac Ramzesa","opis":"Lekarz się waha, ale Ramzes nakazuje spełnić rozkaz, przypominając, że żyje jego trzydziestoletni wnuk i następca, Horus; wypija lekarstwo."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 3, $lektury$początek noweli$lektury$, $lektury$początek noweli. Ramzes, astrolog z Teb, lekarz z Karnaku. Egipt, pałac Ramzesa. Astrolog odczytuje z gwiazd (Saturn połączony z Księżycem) śmierć członka dynastii; lekarz mówi, że przed świtem Ramzes albo wyzdrowieje, albo pierścień przejdzie na rękę Horusa.$lektury$, $lektury${"nr":3,"miejsce":"początek noweli","kto":["Ramzes","astrolog z Teb","lekarz z Karnaku"],"gdzie":"Egipt, pałac Ramzesa","opis":"Astrolog odczytuje z gwiazd (Saturn połączony z Księżycem) śmierć członka dynastii; lekarz mówi, że przed świtem Ramzes albo wyzdrowieje, albo pierścień przejdzie na rękę Horusa."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 4, $lektury$sala faraonów, ganek nad Nilem$lektury$, $lektury$sala faraonów, ganek nad Nilem. Ramzes, Horus. Egipt, sala faraonów. Ramzes każe zaprowadzić Horusa do sali faraonów, żeby czekał na pierścień i na ostatnie słowa dziada.$lektury$, $lektury${"nr":4,"miejsce":"sala faraonów, ganek nad Nilem","kto":["Ramzes","Horus"],"gdzie":"Egipt, sala faraonów","opis":"Ramzes każe zaprowadzić Horusa do sali faraonów, żeby czekał na pierścień i na ostatnie słowa dziada."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 5, $lektury$sala faraonów, ganek nad Nilem$lektury$, $lektury$sala faraonów, ganek nad Nilem. Horus, dworzanin. ganek nad Nilem. Horus patrzy na tłum zgromadzony w nocy i dowiaduje się, że ludzie czekają na nowego faraona; pierwszy raz czuje dumę władzy.$lektury$, $lektury${"nr":5,"miejsce":"sala faraonów, ganek nad Nilem","kto":["Horus","dworzanin"],"gdzie":"ganek nad Nilem","opis":"Horus patrzy na tłum zgromadzony w nocy i dowiaduje się, że ludzie czekają na nowego faraona; pierwszy raz czuje dumę władzy."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 6, $lektury$sala faraonów, ganek nad Nilem$lektury$, $lektury$sala faraonów, ganek nad Nilem. Horus, dworzanin. ganek nad Nilem. Horus dowiaduje się, że kapłani przenoszą zwłoki jego matki Zefory do katakumb faraonów, że kanclerz wysłał gońców po jego nauczyciela Jetrona oraz że Berenika czeka na wolność w klasztornym więzieniu.$lektury$, $lektury${"nr":6,"miejsce":"sala faraonów, ganek nad Nilem","kto":["Horus","dworzanin"],"gdzie":"ganek nad Nilem","opis":"Horus dowiaduje się, że kapłani przenoszą zwłoki jego matki Zefory do katakumb faraonów, że kanclerz wysłał gońców po jego nauczyciela Jetrona oraz że Berenika czeka na wolność w klasztornym więzieniu."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 7, $lektury$sala faraonów, ganek nad Nilem$lektury$, $lektury$sala faraonów, ganek nad Nilem. Horus, dworzanin. ganek nad Nilem. Horusa ukąsiła w nogę pszczoła, dworzanin mówi, że dobrze, iż nie pająk, którego jad bywa o tej porze śmiertelny.$lektury$, $lektury${"nr":7,"miejsce":"sala faraonów, ganek nad Nilem","kto":["Horus","dworzanin"],"gdzie":"ganek nad Nilem","opis":"Horusa ukąsiła w nogę pszczoła, dworzanin mówi, że dobrze, iż nie pająk, którego jad bywa o tej porze śmiertelny."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 8, $lektury$sala faraonów$lektury$, $lektury$sala faraonów. Horus, wódz armii. sala faraonów. Wódz armii przekazuje rozkaz Ramzesa, by spełniać wolę Horusa po zobaczeniu pierścienia; Horus każe napisać edykt o pokoju z Etiopami i drugi, że jeńcom nie wolno wyrywać języków.$lektury$, $lektury${"nr":8,"miejsce":"sala faraonów","kto":["Horus","wódz armii"],"gdzie":"sala faraonów","opis":"Wódz armii przekazuje rozkaz Ramzesa, by spełniać wolę Horusa po zobaczeniu pierścienia; Horus każe napisać edykt o pokoju z Etiopami i drugi, że jeńcom nie wolno wyrywać języków."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 9, $lektury$sala faraonów$lektury$, $lektury$sala faraonów. Horus, kanclerz. sala faraonów. Kanclerz, spełniając ten sam rozkaz, słyszy edykt o zmniejszeniu o połowę czynszów i podatków oraz o trzech dniach wolnych w tygodniu dla niewolników, a także o powrocie Jetrona z wygnania.$lektury$, $lektury${"nr":9,"miejsce":"sala faraonów","kto":["Horus","kanclerz"],"gdzie":"sala faraonów","opis":"Kanclerz, spełniając ten sam rozkaz, słyszy edykt o zmniejszeniu o połowę czynszów i podatków oraz o trzech dniach wolnych w tygodniu dla niewolników, a także o powrocie Jetrona z wygnania."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 10, $lektury$sala faraonów$lektury$, $lektury$sala faraonów. Horus, arcykapłan. sala faraonów. Arcykapłan obiecuje posłuszeństwo; Horus zapowiada nowe świątynie i żąda edyktów o przeniesieniu zwłok Zefory i o uwolnieniu Bereniki z klasztoru.$lektury$, $lektury${"nr":10,"miejsce":"sala faraonów","kto":["Horus","arcykapłan"],"gdzie":"sala faraonów","opis":"Arcykapłan obiecuje posłuszeństwo; Horus zapowiada nowe świątynie i żąda edyktów o przeniesieniu zwłok Zefory i o uwolnieniu Bereniki z klasztoru."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 11, $lektury$sala faraonów$lektury$, $lektury$sala faraonów. Horus, lekarz z Karnaku. sala faraonów. Lekarz mówi, że Ramzes kona, i widząc bladość Horusa, ogląda jego nogę; stwierdza, że ukąsił go bardzo jadowity pająk i że książę umrze, zanim księżyc schowa się za palmę.$lektury$, $lektury${"nr":11,"miejsce":"sala faraonów","kto":["Horus","lekarz z Karnaku"],"gdzie":"sala faraonów","opis":"Lekarz mówi, że Ramzes kona, i widząc bladość Horusa, ogląda jego nogę; stwierdza, że ukąsił go bardzo jadowity pająk i że książę umrze, zanim księżyc schowa się za palmę."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 12, $lektury$sala faraonów$lektury$, $lektury$sala faraonów. Horus, kanclerz, wódz armii, arcykapłan, lekarz z Karnaku. sala faraonów. Ministrowie przynoszą gotowe edykty, ale brakuje pierścienia faraona; lekarz odlicza, ile kroków dzieli Horusa od śmierci (od tysiąca do stu).$lektury$, $lektury${"nr":12,"miejsce":"sala faraonów","kto":["Horus","kanclerz","wódz armii","arcykapłan","lekarz z Karnaku"],"gdzie":"sala faraonów","opis":"Ministrowie przynoszą gotowe edykty, ale brakuje pierścienia faraona; lekarz odlicza, ile kroków dzieli Horusa od śmierci (od tysiąca do stu)."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 13, $lektury$sala faraonów$lektury$, $lektury$sala faraonów. Horus. sala faraonów. W miarę odliczania kolejne edykty wypadają Horusowi z rąk, a na końcu zostaje tylko rozkaz uwolnienia Bereniki.$lektury$, $lektury${"nr":13,"miejsce":"sala faraonów","kto":["Horus"],"gdzie":"sala faraonów","opis":"W miarę odliczania kolejne edykty wypadają Horusowi z rąk, a na końcu zostaje tylko rozkaz uwolnienia Bereniki."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$wydarzenie$lektury$, 14, $lektury$zakończenie noweli$lektury$, $lektury$zakończenie noweli. zastępca arcykapłana, Horus, lekarz z Karnaku. sala faraonów. Wbiega zastępca arcykapłana z wieścią, że Ramzes cudownie odzyskał zdrowie i zaprasza Horusa na łowy; Horus spogląda w stronę światła w więzieniu Bereniki i umiera.$lektury$, $lektury${"nr":14,"miejsce":"zakończenie noweli","kto":["zastępca arcykapłana","Horus","lekarz z Karnaku"],"gdzie":"sala faraonów","opis":"Wbiega zastępca arcykapłana z wieścią, że Ramzes cudownie odzyskał zdrowie i zaprasza Horusa na łowy; Horus spogląda w stronę światła w więzieniu Bereniki i umiera."}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
  ($lektury$z-legend-dawnego-egiptu$lektury$, $lektury$postac$lektury$, 1, $lektury$pałac Ramzesa$lektury$, $lektury$Ramzes. Ramzesa, Ramzesowi, Ramzesem, Ramzesie, faraon. stuletni faraon, surowy i potężny; po lekarstwie odzyskuje zdrowie dziad Horusa, ojciec Zefory (wg kontekstu: teść), władca, który wygnał Jetrona pałac Ramzesa; sala faraonów$lektury$, $lektury${"imie":"Ramzes","odmiany":["Ramzesa","Ramzesowi","Ramzesem","Ramzesie","faraon"],"rola":"stuletni faraon, surowy i potężny; po lekarstwie odzyskuje zdrowie","relacje":"dziad Horusa, ojciec Zefory (wg kontekstu: teść), władca, który wygnał Jetrona","miejsca":["pałac Ramzesa","sala faraonów"]}$lektury$::jsonb, $lektury$https://wolnelektury.pl/katalog/lektura/z-legend-dawnego-egiptu/$lektury$),
